window.INDUCTO_DATA = {"generated":true,"library":"Inducto Learning & Knowledge Library","tracks":[{"id":"01-ai-general","name":"AI Courses","blurb":"What AI is, what it can do, and where it breaks."},{"id":"02-ai-daily-work","name":"AI for Day-to-Day Work","blurb":"The jobs you already do, done in less time."},{"id":"03-prompt-engineering","name":"Prompt Engineering","blurb":"Asking well enough to get a usable answer."},{"id":"04-professional-skills","name":"Professional Skills","blurb":"The skills AI assists and never replaces."},{"id":"05-security-privacy","name":"Security & Data Privacy","blurb":"Keeping our data, and our customers', where it belongs."}],"modules":[{"id":"AI-01","code":"AI-01","area":"01-ai-general","title":"AI Fundamentals","summary":"What AI actually is, in plain language — and what it changes on your desk on Monday morning.","duration":18,"audience":"New joiners + staff","href":"modules/ai01.html","sectionCount":13,"lessons":15,"video":true},{"id":"AI-02","code":"AI-02","area":"01-ai-general","title":"Generative AI","summary":"What it actually makes, why every answer is different, and where it beats a search box.","duration":18,"audience":"New joiners + staff","href":"modules/ai02.html","sectionCount":13,"lessons":14,"video":true},{"id":"AI-03","code":"AI-03","area":"01-ai-general","title":"AI Capabilities","summary":"The tasks where these tools genuinely save you an hour — and how to spot one on your own desk.","duration":17,"audience":"New joiners + staff","href":"modules/ai03.html","sectionCount":13,"lessons":14,"video":true},{"id":"AI-04","code":"AI-04","area":"01-ai-general","title":"AI Limitations","summary":"Where these tools break, why they break exactly there, and what to reach for instead.","duration":17,"audience":"New joiners + staff","href":"modules/ai04.html","sectionCount":13,"lessons":14,"video":true},{"id":"AI-05","code":"AI-05","area":"01-ai-general","title":"Hallucinations & Fact-Checking","summary":"How to catch a confident wrong answer in under a minute, before it reaches a customer.","duration":18,"audience":"New joiners + staff","href":"modules/ai05.html","sectionCount":13,"lessons":14,"video":true},{"id":"DW-01","code":"DW-01","area":"02-ai-daily-work","title":"Email Writing with AI","summary":"Thirty emails a day, written in a third of the time, without sounding like a robot wrote them.","duration":18,"audience":"New joiners + staff","href":"modules/dw01.html","sectionCount":13,"lessons":14,"video":true},{"id":"DW-02","code":"DW-02","area":"02-ai-daily-work","title":"Research with AI","summary":"Using it to find the right questions fast — without letting it invent the answers.","duration":18,"audience":"New joiners + staff","href":"modules/dw02.html","sectionCount":13,"lessons":13,"video":true},{"id":"DW-03","code":"DW-03","area":"02-ai-daily-work","title":"Report Preparation with AI","summary":"Turning what you already know into a report somebody actually reads to the end.","duration":18,"audience":"New joiners + staff","href":"modules/dw03.html","sectionCount":13,"lessons":14,"video":true},{"id":"DW-04","code":"DW-04","area":"02-ai-daily-work","title":"Data Analysis with AI","summary":"Getting a straight answer out of your numbers, without letting it do the arithmetic.","duration":18,"audience":"New joiners + staff","href":"modules/dw04.html","sectionCount":13,"lessons":14,"video":true},{"id":"DW-05","code":"DW-05","area":"02-ai-daily-work","title":"Excel with AI","summary":"Formulas written for you, messy data cleaned up, and every one of them tested on a single row first.","duration":19,"audience":"New joiners + staff","href":"modules/dw05.html","sectionCount":13,"lessons":14,"video":true},{"id":"DW-06","code":"DW-06","area":"02-ai-daily-work","title":"Presentations with AI","summary":"Get the argument straight before you open PowerPoint.","duration":17,"audience":"New joiners + staff","href":"modules/dw06.html","sectionCount":13,"lessons":14,"video":true},{"id":"DW-07","code":"DW-07","area":"02-ai-daily-work","title":"Documentation with AI","summary":"SOPs, process notes and handovers somebody can follow without ringing you to ask what you meant.","duration":18,"audience":"New joiners + staff","href":"modules/dw07.html","sectionCount":13,"lessons":14,"video":true},{"id":"DW-08","code":"DW-08","area":"02-ai-daily-work","title":"Meeting Notes & Follow-ups","summary":"Turning an hour of discussion into decisions and owners, before anyone leaves the room.","duration":17,"audience":"New joiners + staff","href":"modules/dw08.html","sectionCount":13,"lessons":14,"video":true},{"id":"DW-09","code":"DW-09","area":"02-ai-daily-work","title":"Brainstorming with AI","summary":"Twenty options in two minutes, and a way to tell which three are actually worth your time.","duration":16,"audience":"New joiners + staff","href":"modules/dw09.html","sectionCount":13,"lessons":14,"video":true},{"id":"DW-10","code":"DW-10","area":"02-ai-daily-work","title":"Planning with AI","summary":"Turning a long list of intentions into a week you can actually finish.","duration":16,"audience":"New joiners + staff","href":"modules/dw10.html","sectionCount":13,"lessons":14,"video":true},{"id":"DW-11","code":"DW-11","area":"02-ai-daily-work","title":"Automation Basics","summary":"Spotting the jobs worth automating, and describing one clearly enough that somebody can actually build it.","duration":18,"audience":"New joiners + staff","href":"modules/dw11.html","sectionCount":13,"lessons":14,"video":true},{"id":"PE-01","code":"PE-01","area":"03-prompt-engineering","title":"Basic Prompting","summary":"The first prompt you ever write — and the six-part shape that makes it work every time, not just when you get lucky.","duration":20,"audience":"New joiners + staff","href":"modules/pe01.html","sectionCount":13,"lessons":15,"video":true},{"id":"PE-02","code":"PE-02","area":"03-prompt-engineering","title":"Instructions & Context","summary":"How much background to give — and the point where adding more starts making the answer worse.","duration":18,"audience":"New joiners + staff","href":"modules/pe02.html","sectionCount":13,"lessons":14,"video":true},{"id":"PE-03","code":"PE-03","area":"03-prompt-engineering","title":"Role-Based Prompts","summary":"\"Act as a…\" — what it actually changes, when it helps, and when it is just decoration.","duration":16,"audience":"New joiners + staff","href":"modules/pe03.html","sectionCount":13,"lessons":14,"video":true},{"id":"PE-04","code":"PE-04","area":"03-prompt-engineering","title":"Examples & Structured Prompts","summary":"Showing one good example beats three paragraphs describing what good looks like.","duration":18,"audience":"New joiners + staff","href":"modules/pe04.html","sectionCount":13,"lessons":14,"video":true},{"id":"PE-05","code":"PE-05","area":"03-prompt-engineering","title":"Advanced Prompting","summary":"Breaking a big job into steps, setting limits the answer must respect, and checking the work as you go.","duration":20,"audience":"Staff who already prompt daily","href":"modules/pe05.html","sectionCount":13,"lessons":14,"video":true},{"id":"PE-06","code":"PE-06","area":"03-prompt-engineering","title":"Reusable Prompts","summary":"Turning the prompts that worked into a library you and your team stop rewriting every week.","duration":17,"audience":"New joiners + staff","href":"modules/pe06.html","sectionCount":13,"lessons":14,"video":true},{"id":"PE-07","code":"PE-07","area":"03-prompt-engineering","title":"Evaluating AI Responses","summary":"A thirty-second way to decide whether to send it, fix it or throw it away.","duration":17,"audience":"New joiners + staff","href":"modules/pe07.html","sectionCount":13,"lessons":14,"video":true},{"id":"PS-01","code":"PS-01","area":"04-professional-skills","title":"Business Communication","summary":"Getting a decision out of people who are busy, in messages they read to the end.","duration":17,"audience":"New joiners + staff","href":"modules/ps01.html","sectionCount":13,"lessons":14,"video":true},{"id":"PS-02","code":"PS-02","area":"04-professional-skills","title":"Professional Email Writing","summary":"The mechanics — subject lines, openings, tone, and knowing when not to send at all.","duration":17,"audience":"New joiners + staff","href":"modules/ps02.html","sectionCount":13,"lessons":14,"video":true},{"id":"PS-03","code":"PS-03","area":"04-professional-skills","title":"English for the Workplace","summary":"The handful of patterns that cause almost every misunderstanding at work — and how to sidestep them.","duration":17,"audience":"New joiners + staff","href":"modules/ps03.html","sectionCount":13,"lessons":13,"video":true},{"id":"PS-04","code":"PS-04","area":"04-professional-skills","title":"Time Management","summary":"Protecting the two hours a day where your real work actually gets done.","duration":16,"audience":"New joiners + staff","href":"modules/ps04.html","sectionCount":13,"lessons":13,"video":true},{"id":"PS-05","code":"PS-05","area":"04-professional-skills","title":"Productivity Systems","summary":"A system simple enough that you will still be using it in March.","duration":16,"audience":"New joiners + staff","href":"modules/ps05.html","sectionCount":13,"lessons":13,"video":true},{"id":"PS-06","code":"PS-06","area":"04-professional-skills","title":"Problem-Solving","summary":"Finding the actual cause before you spend a fortnight fixing the wrong thing.","duration":17,"audience":"New joiners + staff","href":"modules/ps06.html","sectionCount":13,"lessons":13,"video":true},{"id":"PS-07","code":"PS-07","area":"04-professional-skills","title":"Critical Thinking","summary":"Telling evidence from assertion — including in your own reasoning, which is the harder half.","duration":17,"audience":"New joiners + staff","href":"modules/ps07.html","sectionCount":13,"lessons":14,"video":true},{"id":"PS-08","code":"PS-08","area":"04-professional-skills","title":"Presentation Skills","summary":"Standing up and saying it — including when you are interrupted on slide three.","duration":17,"audience":"New joiners + staff","href":"modules/ps08.html","sectionCount":13,"lessons":14,"video":true},{"id":"PS-09","code":"PS-09","area":"04-professional-skills","title":"Teamwork & Collaboration","summary":"Handing work over so it arrives finished, and asking for help without friction.","duration":17,"audience":"New joiners + staff","href":"modules/ps09.html","sectionCount":13,"lessons":13,"video":true},{"id":"SEC-01","code":"SEC-01","area":"05-security-privacy","title":"Password Security","summary":"Why one reused password is the most likely way this company gets broken into.","duration":16,"audience":"Mandatory for all staff","href":"modules/sec01.html","sectionCount":13,"lessons":14,"video":true},{"id":"SEC-02","code":"SEC-02","area":"05-security-privacy","title":"Phishing & Social Engineering","summary":"How people get talked into handing over the password, the payment or the file — and the pause that stops it.","duration":18,"audience":"Mandatory for all staff","href":"modules/sec02.html","sectionCount":13,"lessons":13,"video":true},{"id":"SEC-03","code":"SEC-03","area":"05-security-privacy","title":"Multi-Factor Authentication","summary":"The second lock that makes a stolen password almost useless — and the one way people still get past it.","duration":15,"audience":"Mandatory for all staff","href":"modules/sec03.html","sectionCount":13,"lessons":14,"video":true},{"id":"SEC-04","code":"SEC-04","area":"05-security-privacy","title":"Data Protection Basics","summary":"What counts as personal data, what the law expects, and what that means for your inbox on an ordinary Tuesday.","duration":18,"audience":"Mandatory for all staff","href":"modules/sec04.html","sectionCount":13,"lessons":13,"video":true},{"id":"SEC-05","code":"SEC-05","area":"05-security-privacy","title":"Handling Confidential Information","summary":"The commercial material that is not personal data, and still must never leave the building.","duration":16,"audience":"Mandatory for all staff","href":"modules/sec05.html","sectionCount":13,"lessons":13,"video":true},{"id":"SEC-06","code":"SEC-06","area":"05-security-privacy","title":"Safe Use of AI at Work","summary":"Which tools are approved, which settings to switch off, and how to keep a trail you can actually explain.","duration":17,"audience":"Mandatory for all staff","href":"modules/sec06.html","sectionCount":13,"lessons":13,"video":true},{"id":"SEC-07","code":"SEC-07","area":"05-security-privacy","title":"What Never to Paste Into AI","summary":"The five red lines, the two-second test, and exactly what to type instead when you are in a hurry.","duration":16,"audience":"Mandatory for all staff","href":"modules/sec07.html","sectionCount":13,"lessons":14,"video":true}],"glossary":[{"term":"#N/A","def":"Excel's way of saying it found no match. Usually a text versus number problem.","module":"DW-05","href":"modules/dw05.html#glossary"},{"term":"[CHECK]","def":"A marker the tool writes where a fact is missing, instead of inventing one.","module":"DW-03","href":"modules/dw03.html#glossary"},{"term":"[GAP]","def":"A marker the tool writes where a beginner would need information you did not supply.","module":"DW-07","href":"modules/dw07.html#glossary"},{"term":"[WEAK]","def":"A marker showing a reason you have asserted without evidence.","module":"DW-06","href":"modules/dw06.html#glossary"},{"term":"Accountability","def":"A named person owns the output, regardless of what helped produce it.","module":"SEC-06","href":"modules/sec06.html#glossary"},{"term":"Action","def":"Something one named person will do by a stated date. Anything else is a discussion point.","module":"DW-08","href":"modules/dw08.html#glossary"},{"term":"Aggregate","def":"A calculated summary — a total, an average, a top five — rather than the underlying rows.","module":"DW-04","href":"modules/dw04.html#glossary"},{"term":"Ambiguity","def":"A sentence with two possible meanings. The main cost of unclear writing at work.","module":"PS-03","href":"modules/ps03.html#glossary"},{"term":"Anonymise","def":"Replacing names and identifiers with labels like Customer A, so nobody can be identified.","module":"DW-04","href":"modules/dw04.html#glossary"},{"term":"Appendix","def":"Slides kept after the end, ready if asked, invisible if not.","module":"DW-06","href":"modules/dw06.html#glossary"},{"term":"Approved tool","def":"An AI service the company holds an agreement with, used through your work account.","module":"SEC-06","href":"modules/sec06.html#glossary"},{"term":"Argument","def":"The point you want agreed, the reasons for it, and what you are asking for.","module":"DW-06","href":"modules/dw06.html#glossary"},{"term":"Article","def":"\"The\" and \"a\". Small words that make instructions read less abrupt.","module":"PS-03","href":"modules/ps03.html#glossary"},{"term":"Ask","def":"The one thing you need the reader to do. It belongs in the first sentence.","module":"PS-01","href":"modules/ps01.html#glossary"},{"term":"Assertion","def":"A claim stated without evidence. Often true, and not yet demonstrated.","module":"PS-07","href":"modules/ps07.html#glossary"},{"term":"Audit trail","def":"A record of what was used, on what, by whom. Written at the time, not reconstructed.","module":"SEC-06","href":"modules/sec06.html#glossary"},{"term":"Authenticator app","def":"An app showing a rotating code, tied to the device rather than to a phone number.","module":"SEC-03","href":"modules/sec03.html#glossary"},{"term":"Background","def":"Context for the few readers who want it. Always below the ask.","module":"PS-01","href":"modules/ps01.html#glossary"},{"term":"Backup codes","def":"One-time codes for when you lose your phone. Stored away from that phone.","module":"SEC-03","href":"modules/sec03.html#glossary"},{"term":"Batching","def":"Holding several small requests and handling them together at one point in the day.","module":"PS-04","href":"modules/ps04.html#glossary"},{"term":"Blocker","def":"Something stopping progress. Should reach a named person within hours, not days.","module":"PS-09","href":"modules/ps09.html#glossary"},{"term":"Bracket","def":"A labelled gap like [CLIENT] that says what belongs there, and keeps real data out.","module":"PE-06","href":"modules/pe06.html#glossary"},{"term":"Breach","def":"A site losing its user list, usually including email addresses and passwords.","module":"SEC-01","href":"modules/sec01.html#glossary"},{"term":"Buffer","def":"Extra time added to absorb delays. Useful, and it hides the problem if used instead of fixing it.","module":"PS-09","href":"modules/ps09.html#glossary"},{"term":"Business email compromise","def":"An attacker using a real or lookalike account to redirect a payment.","module":"SEC-02","href":"modules/sec02.html#glossary"},{"term":"Capability","def":"Something the tool can reliably do. Here it means language work, not knowledge work.","module":"AI-03","href":"modules/ai03.html#glossary"},{"term":"Capture","def":"Writing a commitment down the moment it is made, in under ten seconds.","module":"PS-05","href":"modules/ps05.html#glossary"},{"term":"Cause","def":"Why something happened. Only you can establish this, and only if you checked.","module":"DW-03","href":"modules/dw03.html#glossary"},{"term":"Chaining","def":"Breaking one large request into ordered steps, checking each before the next uses it.","module":"PE-05","href":"modules/pe05.html#glossary"},{"term":"Channel","def":"Email, call, chat or in person. Choosing deliberately prevents most communication problems.","module":"PS-01","href":"modules/ps01.html#glossary"},{"term":"Citation","def":"A reference to a real document. AI produces convincing ones that do not exist.","module":"DW-02","href":"modules/dw02.html#glossary"},{"term":"Classification","def":"Deciding which of the four classes a document belongs to, and who may open it.","module":"SEC-05","href":"modules/sec05.html#glossary"},{"term":"Close","def":"The final line, where warmth belongs. It is read; the opening often is not.","module":"PS-02","href":"modules/ps02.html#glossary"},{"term":"Confidential","def":"Damaging if it leaves the company, even though no individual is identifiable.","module":"SEC-05","href":"modules/sec05.html#glossary"},{"term":"Confirmation bias","def":"Noticing evidence that fits your view and not registering the rest.","module":"PS-07","href":"modules/ps07.html#glossary"},{"term":"Consequence","def":"What actually happens if a task slips. The only reliable way to sort a long list.","module":"DW-10","href":"modules/dw10.html#glossary"},{"term":"Constraint","def":"Something that rules an option out: a contract, a licence, a budget, a piece of equipment.","module":"DW-09","href":"modules/dw09.html#glossary"},{"term":"Consumer tier","def":"A free or personal subscription. Terms nobody here negotiated, and often training on your input.","module":"SEC-06","href":"modules/sec06.html#glossary"},{"term":"Context","def":"The background you give so the tool knows who the text is for and why.","module":"AI-03","href":"modules/ai03.html#glossary"},{"term":"Context switching","def":"Moving between tasks. Costs roughly fifteen minutes of refocusing each time.","module":"PS-04","href":"modules/ps04.html#glossary"},{"term":"Convergent thinking","def":"Narrowing many options down to a decision. The part the room does.","module":"DW-09","href":"modules/dw09.html#glossary"},{"term":"Correction","def":"A follow-up naming what to keep, what to change, and the correct value.","module":"PE-07","href":"modules/pe07.html#glossary"},{"term":"Credential stuffing","def":"Trying leaked email and password pairs automatically against many services at once.","module":"SEC-01","href":"modules/sec01.html#glossary"},{"term":"Curse of knowledge","def":"The habit of leaving out steps that have become invisible to you through practice.","module":"DW-07","href":"modules/dw07.html#glossary"},{"term":"Cut-off date","def":"The point where a model's training text stops. Nothing after it was ever seen.","module":"AI-04","href":"modules/ai04.html#glossary"},{"term":"Daily review","def":"Four questions at the same point each day. Two minutes, and it survives bad weeks.","module":"PS-05","href":"modules/ps05.html#glossary"},{"term":"Data breach","def":"Personal data going somewhere it should not. No attacker is required.","module":"SEC-04","href":"modules/sec04.html#glossary"},{"term":"Data minimisation","def":"Collecting only what you actually need. The strongest protection available.","module":"SEC-04","href":"modules/sec04.html#glossary"},{"term":"Deadlock","def":"Two stated positions and no movement. Usually social rather than analytical.","module":"DW-09","href":"modules/dw09.html#glossary"},{"term":"Deep work","def":"Work needing sustained concentration. It never feels urgent, and it is what gets remembered.","module":"PS-04","href":"modules/ps04.html#glossary"},{"term":"Definition of done","def":"What the finished output looks like, stated before anyone starts.","module":"PS-09","href":"modules/ps09.html#glossary"},{"term":"Divergent thinking","def":"Producing many options without judging them. The part AI does well.","module":"DW-09","href":"modules/dw09.html#glossary"},{"term":"DPDP Act","def":"India's Digital Personal Data Protection Act, covering consent, purpose and breach notification.","module":"SEC-04","href":"modules/sec04.html#glossary"},{"term":"Escalation","def":"Moving a stalled request to a call, then to a manager, factually and without complaint.","module":"PS-01","href":"modules/ps01.html#glossary"},{"term":"Evaluation","def":"Deciding whether an answer can be sent, needs fixing, or should be thrown away.","module":"PE-07","href":"modules/pe07.html#glossary"},{"term":"Exception","def":"A case where reality does not match the rule. The automation should stop and tell someone.","module":"DW-11","href":"modules/dw11.html#glossary"},{"term":"Executive summary","def":"The opening paragraph carrying the conclusion, the reason and the ask.","module":"DW-03","href":"modules/dw03.html#glossary"},{"term":"Extract","def":"A fresh document containing only the part somebody actually needs.","module":"SEC-05","href":"modules/sec05.html#glossary"},{"term":"Falsification","def":"Designing a test that would show you were wrong. Worth more than confirmation.","module":"PS-06","href":"modules/ps06.html#glossary"},{"term":"Feedback","def":"One specific thing, its effect, and what you would like instead. Within two days.","module":"PS-09","href":"modules/ps09.html#glossary"},{"term":"Few-shot","def":"Giving one or two examples of what good looks like before you make your request.","module":"PE-01","href":"modules/pe01.html#glossary"},{"term":"Finding","def":"Something you observed. Different from a cause, which is an explanation of it.","module":"DW-03","href":"modules/dw03.html#glossary"},{"term":"First action","def":"The concrete five minutes that starts a stuck task.","module":"DW-10","href":"modules/dw10.html#glossary"},{"term":"Five whys","def":"Asking why repeatedly, with a fact at each step, until you reach something changeable.","module":"PS-06","href":"modules/ps06.html#glossary"},{"term":"Folklore","def":"A number everybody repeats that nobody can trace to a source.","module":"PS-07","href":"modules/ps07.html#glossary"},{"term":"Formula","def":"An instruction Excel calculates itself. Checkable, repeatable and safe.","module":"DW-05","href":"modules/dw05.html#glossary"},{"term":"Front-loading","def":"Putting the conclusion and the request before the reasoning.","module":"PS-01","href":"modules/ps01.html#glossary"},{"term":"Generative AI","def":"A system that builds new text, images or code rather than retrieving something that already exists.","module":"AI-02","href":"modules/ai02.html#glossary"},{"term":"Grounding","def":"Giving the tool the actual source text so its answer has something real to stand on.","module":"AI-04","href":"modules/ai04.html#glossary"},{"term":"Hallucination","def":"A confident answer that is simply made up. Usually a name, a number or a date.","module":"AI-01","href":"modules/ai01.html#glossary"},{"term":"Handover","def":"A document covering what you do, who to call, and what usually goes wrong while you are away.","module":"DW-07","href":"modules/dw07.html#glossary"},{"term":"Hedging","def":"Answering both ways at once. Usually a sign it has nothing specific to say.","module":"PE-07","href":"modules/pe07.html#glossary"},{"term":"Inbox","def":"A list of other people's priorities, sorted by when they were sent.","module":"PS-05","href":"modules/ps05.html#glossary"},{"term":"Instruction","def":"What to do with that background: the task, the length, the tone, the format.","module":"PE-02","href":"modules/pe02.html#glossary"},{"term":"Judgement","def":"A decision needing context a rule cannot see. Never automated.","module":"DW-11","href":"modules/dw11.html#glossary"},{"term":"Like-for-like","def":"A comparison where period, definition and scope are all the same.","module":"PS-07","href":"modules/ps07.html#glossary"},{"term":"Lookup","def":"Matching a value in one sheet against a table in another, such as VLOOKUP or XLOOKUP.","module":"DW-05","href":"modules/dw05.html#glossary"},{"term":"Mapping","def":"Learning the shape of a subject: its terms, its questions, its usual mistakes.","module":"DW-02","href":"modules/dw02.html#glossary"},{"term":"Metadata","def":"Information about a file: its name, author, comments and tracked changes.","module":"SEC-05","href":"modules/sec05.html#glossary"},{"term":"MFA fatigue","def":"Flooding you with approval prompts until you tap one to stop the noise.","module":"SEC-03","href":"modules/sec03.html#glossary"},{"term":"Model","def":"The trained system that produces the answer. ChatGPT, Copilot and Gemini are apps built around a model.","module":"AI-01","href":"modules/ai01.html#glossary"},{"term":"Movement","def":"A change between two periods. Something you calculate and the tool describes.","module":"DW-04","href":"modules/dw04.html#glossary"},{"term":"Multi-factor","def":"A second proof of identity beyond the password. Covered in SEC-03.","module":"SEC-01","href":"modules/sec01.html#glossary"},{"term":"Multi-factor authentication","def":"Proving who you are with two different kinds of thing: something you know and something you have.","module":"SEC-03","href":"modules/sec03.html#glossary"},{"term":"Need to know","def":"The test for sharing: does this person require it for work they are actually doing?","module":"SEC-05","href":"modules/sec05.html#glossary"},{"term":"Negative instruction","def":"Naming something you do not want, so a common habit is ruled out.","module":"PE-02","href":"modules/pe02.html#glossary"},{"term":"Not-now list","def":"A separate file for items with no consequence, reviewed monthly rather than daily.","module":"DW-10","href":"modules/dw10.html#glossary"},{"term":"One-row test","def":"Checking a formula against a row whose answer you already know, before filling down.","module":"DW-05","href":"modules/dw05.html#glossary"},{"term":"One-time code","def":"A short code proving it is you. Never shared with anyone, for any reason.","module":"SEC-02","href":"modules/sec02.html#glossary"},{"term":"Open item","def":"Something not settled, with a named person bringing it back.","module":"DW-08","href":"modules/dw08.html#glossary"},{"term":"Opening","def":"The first thirty seconds. The only moment you have everybody's attention.","module":"PS-08","href":"modules/ps08.html#glossary"},{"term":"Out-of-band","def":"Checking through a different channel the sender does not control.","module":"SEC-02","href":"modules/sec02.html#glossary"},{"term":"Output","def":"What comes back. Always a draft you are responsible for, never a source you can quote.","module":"AI-01","href":"modules/ai01.html#glossary"},{"term":"Overrun","def":"Going past the finish time. It costs the decision you came for.","module":"PS-08","href":"modules/ps08.html#glossary"},{"term":"Owner","def":"The single person accountable. Never a team, never two people.","module":"DW-08","href":"modules/dw08.html#glossary"},{"term":"Padding","def":"Extra words added for politeness that make the request harder to find.","module":"PS-03","href":"modules/ps03.html#glossary"},{"term":"Parking","def":"Agreeing to take a question outside the meeting, with a date attached.","module":"PS-08","href":"modules/ps08.html#glossary"},{"term":"Passkey","def":"A modern factor tied to the real website address, so it cannot be used on a fake page.","module":"SEC-03","href":"modules/sec03.html#glossary"},{"term":"Passphrase","def":"A password made of several unrelated words. Long, memorable and hard to break.","module":"SEC-01","href":"modules/sec01.html#glossary"},{"term":"Password manager","def":"Software that stores a unique password for every account, behind one phrase you learn.","module":"SEC-01","href":"modules/sec01.html#glossary"},{"term":"Persona","def":"Another word for the role you give the tool. It changes style, never knowledge.","module":"PE-03","href":"modules/pe03.html#glossary"},{"term":"Personal data","def":"Anything identifying a person: a name, a phone number, an address, an account.","module":"DW-01","href":"modules/dw01.html#glossary"},{"term":"Phishing","def":"A message designed to make you hand over access, money or a document.","module":"SEC-02","href":"modules/sec02.html#glossary"},{"term":"PII","def":"Personally Identifiable Information. Another term for personal data, used mostly in US and UAE documents.","module":"SEC-07","href":"modules/sec07.html#glossary"},{"term":"Planning horizon","def":"How far ahead you can usefully plan. Around three days for most operational roles.","module":"DW-10","href":"modules/dw10.html#glossary"},{"term":"Point-first","def":"Stating what a slide means before showing its detail.","module":"PS-08","href":"modules/ps08.html#glossary"},{"term":"Prompt","def":"Everything you type in: your request plus any facts you choose to supply.","module":"AI-01","href":"modules/ai01.html#glossary"},{"term":"Prompt library","def":"A shared file of named prompts your team reuses instead of writing from scratch.","module":"PE-06","href":"modules/pe06.html#glossary"},{"term":"Protected block","def":"Two hours booked in the calendar, with notifications off and one task decided.","module":"PS-04","href":"modules/ps04.html#glossary"},{"term":"Reactive work","def":"Work that arrives and demands a response. It fills any space you leave open.","module":"PS-04","href":"modules/ps04.html#glossary"},{"term":"Recency bias","def":"Treating the most recent event as a trend, and quiet periods as nothing.","module":"PS-07","href":"modules/ps07.html#glossary"},{"term":"Register","def":"How formal a message is. Plain and warm travels better than heavy formality.","module":"PS-03","href":"modules/ps03.html#glossary"},{"term":"Reply all","def":"Sending to everyone on a thread. Appropriate only when all of them need it.","module":"PS-02","href":"modules/ps02.html#glossary"},{"term":"Restricted","def":"Material limited to a named few, including inside the company.","module":"SEC-05","href":"modules/sec05.html#glossary"},{"term":"Retention","def":"How long we keep something. Old copies are the ones that cause incidents.","module":"SEC-04","href":"modules/sec04.html#glossary"},{"term":"Reversible","def":"A change you can undo cheaply. Reversible fixes make good experiments.","module":"PS-06","href":"modules/ps06.html#glossary"},{"term":"Role prompt","def":"A line naming who the answer is written by or for, which shifts vocabulary and depth.","module":"PE-03","href":"modules/pe03.html#glossary"},{"term":"Root cause","def":"The change that started it. Fixing this stops the problem returning.","module":"PS-06","href":"modules/ps06.html#glossary"},{"term":"Ruled out","def":"Something already tested and eliminated. Record it so nobody repeats it.","module":"PS-06","href":"modules/ps06.html#glossary"},{"term":"Sentence title","def":"A slide heading that states the point rather than naming the topic.","module":"DW-06","href":"modules/dw06.html#glossary"},{"term":"Shadow AI","def":"AI tools in use at work that nobody assessed or approved. Usually browser extensions and bots.","module":"SEC-06","href":"modules/sec06.html#glossary"},{"term":"Shared account","def":"One login used by several people. It destroys any record of who did what.","module":"SEC-01","href":"modules/sec01.html#glossary"},{"term":"Signposting","def":"Telling the room where you are, especially after an interruption.","module":"PS-08","href":"modules/ps08.html#glossary"},{"term":"Social engineering","def":"Manipulating a person rather than attacking a system. The pressure signals are the tools.","module":"SEC-02","href":"modules/sec02.html#glossary"},{"term":"SOP","def":"Standard Operating Procedure. A written process somebody can follow without asking questions.","module":"DW-07","href":"modules/dw07.html#glossary"},{"term":"Source","def":"A document, system or person you can point at. A model is never one.","module":"AI-05","href":"modules/ai05.html#glossary"},{"term":"Speaker notes","def":"What you will actually say, written as spoken sentences.","module":"DW-06","href":"modules/dw06.html#glossary"},{"term":"Specification","def":"A description clear enough that somebody who has never seen your job could build it.","module":"DW-11","href":"modules/dw11.html#glossary"},{"term":"Spoofing","def":"Making a message appear to come from somebody else. Display names are free text.","module":"SEC-02","href":"modules/sec02.html#glossary"},{"term":"Stale list","def":"A list nobody has opened for days. Restart from memory rather than reading it.","module":"PS-05","href":"modules/ps05.html#glossary"},{"term":"Stated default","def":"What you will do if nobody replies. It turns silence into a decision.","module":"PS-01","href":"modules/ps01.html#glossary"},{"term":"Step-by-step","def":"Asking the tool to show its intermediate reasoning rather than only the conclusion.","module":"PE-05","href":"modules/pe05.html#glossary"},{"term":"Structured prompt","def":"A prompt with fixed headings the answer must fill in, so every result is comparable.","module":"PE-04","href":"modules/pe04.html#glossary"},{"term":"Subject access request","def":"A person asking what data we hold about them. It has a legal response period.","module":"SEC-04","href":"modules/sec04.html#glossary"},{"term":"Symptom","def":"What you notice when something is wrong. Usually not the thing to fix.","module":"PS-06","href":"modules/ps06.html#glossary"},{"term":"Template","def":"A prompt with brackets where the specifics go, so you reuse it without rewriting.","module":"DW-01","href":"modules/dw01.html#glossary"},{"term":"Tense","def":"How a verb shows time. Adding a clock time removes most tense problems entirely.","module":"PS-03","href":"modules/ps03.html#glossary"},{"term":"The trade","def":"Offering a choice about what slips, rather than accepting silently or refusing.","module":"PS-04","href":"modules/ps04.html#glossary"},{"term":"Thread","def":"An email conversation with replies stacked inside it. Full of names and signature blocks.","module":"DW-01","href":"modules/dw01.html#glossary"},{"term":"Throat-clearing","def":"An opening sentence that carries no information. Usually safe to delete.","module":"PS-02","href":"modules/ps02.html#glossary"},{"term":"Token","def":"A small piece of text, roughly three quarters of a word. AI tools read and write in tokens, not in letters.","module":"AI-01","href":"modules/ai01.html#glossary"},{"term":"Tone","def":"The register of a message: firm, warm, neutral, apologetic. Name it rather than hoping.","module":"DW-01","href":"modules/dw01.html#glossary"},{"term":"Traceable","def":"Every fact in the answer can be pointed back to something you supplied.","module":"PE-07","href":"modules/pe07.html#glossary"},{"term":"Training data","def":"The public text the model learned from, up to a fixed cut-off date. Our files were never in it.","module":"AI-01","href":"modules/ai01.html#glossary"},{"term":"Training on your data","def":"Using what you type to improve the service. Usually switchable on business tiers.","module":"SEC-06","href":"modules/sec06.html#glossary"},{"term":"Transcript","def":"A written record of everything said. Personal data about everyone present.","module":"DW-08","href":"modules/dw08.html#glossary"},{"term":"Trigger","def":"What starts an automation: a time, a file arriving, an email, a form submission.","module":"DW-11","href":"modules/dw11.html#glossary"},{"term":"Zero-shot","def":"Asking for something without showing an example first. Most everyday prompts are zero-shot.","module":"PE-01","href":"modules/pe01.html#glossary"}],"search":[{"k":"module","t":"AI Fundamentals","s":"What AI actually is, in plain language — and what it changes on your desk on Monday morning.","m":"AI-01","h":"modules/ai01.html"},{"k":"lesson","t":"It predicts the next word","s":"An AI assistant does not look up an answer.","m":"AI-01","h":"modules/ai01.html#s_what"},{"k":"lesson","t":"It knows nothing about our company","s":"Everything it can say came from text it read before a fixed cut-off date.","m":"AI-01","h":"modules/ai01.html#why"},{"k":"lesson","t":"Three words you will hear daily","s":"","m":"AI-01","h":"modules/ai01.html#why"},{"k":"lesson","t":"Search finds pages. AI writes text.","s":"","m":"AI-01","h":"modules/ai01.html#s_vs"},{"k":"lesson","t":"Which one do I open?","s":"","m":"AI-01","h":"modules/ai01.html#why"},{"k":"lesson","t":"Do this now: your first 90 seconds","s":"","m":"AI-01","h":"modules/ai01.html#s_first"},{"k":"lesson","t":"The same job, asked two ways","s":"","m":"AI-01","h":"modules/ai01.html#why"},{"k":"lesson","t":"Turn rough notes into a report","s":"This is the most useful thing most people do with AI all week.","m":"AI-01","h":"modules/ai01.html#why"},{"k":"lesson","t":"When it is 80% right, correct it","s":"","m":"AI-01","h":"modules/ai01.html#why"},{"k":"lesson","t":"Three things it is good at","s":"","m":"AI-01","h":"modules/ai01.html#s_fit"},{"k":"lesson","t":"Where it breaks","s":"","m":"AI-01","h":"modules/ai01.html#why"},{"k":"lesson","t":"Should I use AI for this task?","s":"","m":"AI-01","h":"modules/ai01.html#why"},{"k":"lesson","t":"Four habits that keep you safe","s":"","m":"AI-01","h":"modules/ai01.html#s_safe"},{"k":"lesson","t":"Four checks before you press send","s":"","m":"AI-01","h":"modules/ai01.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"AI-01","h":"modules/ai01.html#why"},{"k":"term","t":"Token","s":"A small piece of text, roughly three quarters of a word.","m":"AI-01","h":"modules/ai01.html#glossary"},{"k":"term","t":"Model","s":"The trained system that produces the answer.","m":"AI-01","h":"modules/ai01.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: your request plus any facts you choose to supply.","m":"AI-01","h":"modules/ai01.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Always a draft you are responsible for, never a source you can quote.","m":"AI-01","h":"modules/ai01.html#glossary"},{"k":"term","t":"Hallucination","s":"A confident answer that is simply made up.","m":"AI-01","h":"modules/ai01.html#glossary"},{"k":"term","t":"Training data","s":"The public text the model learned from, up to a fixed cut-off date.","m":"AI-01","h":"modules/ai01.html#glossary"},{"k":"rule","t":"It predicts, it does not look up","s":"Every answer is built piece by piece from patterns in text, not fetched from a database of facts.","m":"AI-01","h":"modules/ai01.html#recap"},{"k":"rule","t":"Search finds pages, AI writes text","s":"Need something you can quote? Search. Need a draft, summary or rewrite? Assistant.","m":"AI-01","h":"modules/ai01.html#recap"},{"k":"rule","t":"You bring the facts","s":"It has none of our order numbers, clients, policies or systems until you type them in.","m":"AI-01","h":"modules/ai01.html#recap"},{"k":"rule","t":"Check every number and name","s":"A confident tone is not evidence. Verify before anything leaves your desk.","m":"AI-01","h":"modules/ai01.html#recap"},{"k":"rule","t":"Facts, never files","s":"Type the order number. Never paste the contract, the salary sheet or the client list.","m":"AI-01","h":"modules/ai01.html#recap"},{"k":"rule","t":"Correct it, don't restart it","s":"Say what to keep and what to change. The second answer is usually the one you send.","m":"AI-01","h":"modules/ai01.html#recap"},{"k":"toolkit","t":"The late-delivery email prompt","s":"Order number, both dates, reason, tone, word limit.","m":"AI-01","h":"modules/ai01.html#toolkit"},{"k":"toolkit","t":"The notes-into-report prompt","s":"Six rough bullets in, a 180-word report out, with nothing added.","m":"AI-01","h":"modules/ai01.html#toolkit"},{"k":"toolkit","t":"The correction prompt","s":"Say what to keep, then name three specific changes.","m":"AI-01","h":"modules/ai01.html#toolkit"},{"k":"module","t":"Generative AI","s":"What it actually makes, why every answer is different, and where it beats a search box.","m":"AI-02","h":"modules/ai02.html"},{"k":"lesson","t":"It builds. It does not fetch.","s":"There is no file it is copying from. Every sentence is assembled the moment you ask for it.","m":"AI-02","h":"modules/ai02.html#s_gen"},{"k":"lesson","t":"A generator is not a database","s":"","m":"AI-02","h":"modules/ai02.html#why"},{"k":"lesson","t":"Four things it makes well","s":"","m":"AI-02","h":"modules/ai02.html#s_makes"},{"k":"lesson","t":"It makes more than text","s":"","m":"AI-02","h":"modules/ai02.html#why"},{"k":"lesson","t":"Same words, different answer","s":"","m":"AI-02","h":"modules/ai02.html#s_vary"},{"k":"lesson","t":"Turn that into an advantage","s":"Variation is a problem when you did not ask for it, and a gift when you did.","m":"AI-02","h":"modules/ai02.html#why"},{"k":"lesson","t":"Which one do I need?","s":"","m":"AI-02","h":"modules/ai02.html#s_pick"},{"k":"lesson","t":"Gaps get filled, never flagged","s":"","m":"AI-02","h":"modules/ai02.html#why"},{"k":"lesson","t":"Do this now: make something","s":"","m":"AI-02","h":"modules/ai02.html#s_do"},{"k":"lesson","t":"The four seconds that matter","s":"","m":"AI-02","h":"modules/ai02.html#why"},{"k":"lesson","t":"Four habits with generated text","s":"","m":"AI-02","h":"modules/ai02.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"AI-02","h":"modules/ai02.html#why"},{"k":"lesson","t":"Where it genuinely earns its keep","s":"","m":"AI-02","h":"modules/ai02.html#why"},{"k":"lesson","t":"The one habit that matters","s":"","m":"AI-02","h":"modules/ai02.html#why"},{"k":"term","t":"Generative AI","s":"A system that builds new text, images or code rather than retrieving something that already exists.","m":"AI-02","h":"modules/ai02.html#glossary"},{"k":"term","t":"Model","s":"The trained system behind the app. ChatGPT, Copilot and Gemini are apps built around models.","m":"AI-02","h":"modules/ai02.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: the request plus the facts you choose to supply.","m":"AI-02","h":"modules/ai02.html#glossary"},{"k":"term","t":"Hallucination","s":"A confident, invented answer. Usually a name, a number, a date or a policy.","m":"AI-02","h":"modules/ai02.html#glossary"},{"k":"term","t":"Training data","s":"The public text a model learned from, up to a fixed cut-off date.","m":"AI-02","h":"modules/ai02.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"AI-02","h":"modules/ai02.html#glossary"},{"k":"rule","t":"It builds, it does not fetch","s":"Every answer is constructed fresh. There is no page behind it.","m":"AI-02","h":"modules/ai02.html#recap"},{"k":"rule","t":"Different every time","s":"Two colleagues asking the same thing get two answers.","m":"AI-02","h":"modules/ai02.html#recap"},{"k":"rule","t":"Gaps get filled, not flagged","s":"A missing fact produces a plausible invention, never a blank space.","m":"AI-02","h":"modules/ai02.html#recap"},{"k":"rule","t":"Strong on shape, weak on truth","s":"Drafting, shortening, restructuring, options.","m":"AI-02","h":"modules/ai02.html#recap"},{"k":"rule","t":"Read every line","s":"Anything you did not supply and cannot verify comes out before you send.","m":"AI-02","h":"modules/ai02.html#recap"},{"k":"rule","t":"Never a source","s":"It is your draft, that you checked. That is the only honest description of it.","m":"AI-02","h":"modules/ai02.html#recap"},{"k":"toolkit","t":"The three-versions prompt","s":"Formal, friendly and very short, from one set of facts.","m":"AI-02","h":"modules/ai02.html#toolkit"},{"k":"toolkit","t":"The internal-note prompt","s":"Two changes, seventy words, friendly but clear.","m":"AI-02","h":"modules/ai02.html#toolkit"},{"k":"toolkit","t":"The read-before-send check","s":"Delete anything you did not supply and cannot verify.","m":"AI-02","h":"modules/ai02.html#toolkit"},{"k":"module","t":"AI Capabilities","s":"The tasks where these tools genuinely save you an hour — and how to spot one on your own desk.","m":"AI-03","h":"modules/ai03.html"},{"k":"lesson","t":"Four shapes it handles well","s":"Almost every useful AI task at work is one of these four.","m":"AI-03","h":"modules/ai03.html#s_shapes"},{"k":"lesson","t":"What they have in common","s":"","m":"AI-03","h":"modules/ai03.html#why"},{"k":"lesson","t":"The weekly jobs it removes","s":"","m":"AI-03","h":"modules/ai03.html#s_time"},{"k":"lesson","t":"Deepa's three hours, in one prompt","s":"","m":"AI-03","h":"modules/ai03.html#why"},{"k":"lesson","t":"When you cannot start","s":"A blank page costs more time than a bad draft ever will.","m":"AI-03","h":"modules/ai03.html#s_stuck"},{"k":"lesson","t":"Three unblocking moves","s":"","m":"AI-03","h":"modules/ai03.html#why"},{"k":"lesson","t":"The ten-second test","s":"","m":"AI-03","h":"modules/ai03.html#s_spot"},{"k":"lesson","t":"Do this now: find one job","s":"","m":"AI-03","h":"modules/ai03.html#why"},{"k":"lesson","t":"Fits that are not fits","s":"","m":"AI-03","h":"modules/ai03.html#s_stop"},{"k":"lesson","t":"The reframe that rescues a task","s":"Most poor-fit tasks become good-fit tasks if you move the knowledge back to your side.","m":"AI-03","h":"modules/ai03.html#why"},{"k":"lesson","t":"Four checks before you rely on it","s":"","m":"AI-03","h":"modules/ai03.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"AI-03","h":"modules/ai03.html#why"},{"k":"lesson","t":"What good use looks like","s":"","m":"AI-03","h":"modules/ai03.html#why"},{"k":"lesson","t":"The capability rule","s":"","m":"AI-03","h":"modules/ai03.html#why"},{"k":"term","t":"Capability","s":"Something the tool can reliably do. Here it means language work, not knowledge work.","m":"AI-03","h":"modules/ai03.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: the request plus the facts you supply.","m":"AI-03","h":"modules/ai03.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"AI-03","h":"modules/ai03.html#glossary"},{"k":"term","t":"Hallucination","s":"A confident, invented answer. Usually a name, a number, a date or a policy.","m":"AI-03","h":"modules/ai03.html#glossary"},{"k":"term","t":"Context","s":"The background you give so the tool knows who the text is for and why.","m":"AI-03","h":"modules/ai03.html#glossary"},{"k":"term","t":"Model","s":"The trained system behind the app you are typing into.","m":"AI-03","h":"modules/ai03.html#glossary"},{"k":"rule","t":"Four shapes it does well","s":"Turn into, shorten, reshape, generate options.","m":"AI-03","h":"modules/ai03.html#recap"},{"k":"rule","t":"The ten-second test","s":"Do I already know everything the answer needs? If no, it is a poor fit.","m":"AI-03","h":"modules/ai03.html#recap"},{"k":"rule","t":"Reframe a poor fit","s":"Move the knowing to your side. Ask it to write, never to know.","m":"AI-03","h":"modules/ai03.html#recap"},{"k":"rule","t":"The line that stops invention","s":"\"Do not add anything I have not given you.\" Put it in every prompt.","m":"AI-03","h":"modules/ai03.html#recap"},{"k":"rule","t":"Save the weekly job","s":"The task you repeat is the one worth turning into a stored prompt.","m":"AI-03","h":"modules/ai03.html#recap"},{"k":"rule","t":"Judgement stays with you","s":"It can describe what happened. It cannot know why, and it carries no consequences.","m":"AI-03","h":"modules/ai03.html#recap"},{"k":"toolkit","t":"The figures-into-summary prompt","s":"Three movements, no invented causes, 150 words.","m":"AI-03","h":"modules/ai03.html#toolkit"},{"k":"toolkit","t":"The outline prompt","s":"Five parts, one line each, and nothing written for you.","m":"AI-03","h":"modules/ai03.html#toolkit"},{"k":"toolkit","t":"The no-invention line","s":"\"Do not add anything I have not given you.\"","m":"AI-03","h":"modules/ai03.html#toolkit"},{"k":"module","t":"AI Limitations","s":"Where these tools break, why they break exactly there, and what to reach for instead.","m":"AI-04","h":"modules/ai04.html"},{"k":"lesson","t":"Five things it cannot do","s":"","m":"AI-04","h":"modules/ai04.html#s_limits"},{"k":"lesson","t":"Why the gap gets filled","s":"It is built to produce the most likely next words.","m":"AI-04","h":"modules/ai04.html#why"},{"k":"lesson","t":"Everything recent is missing","s":"","m":"AI-04","h":"modules/ai04.html#s_cutoff"},{"k":"lesson","t":"The question to ask yourself","s":"","m":"AI-04","h":"modules/ai04.html#why"},{"k":"lesson","t":"Numbers are the weakest point","s":"A figure looks like evidence. That is exactly why an invented one does the most damage.","m":"AI-04","h":"modules/ai04.html#s_numbers"},{"k":"lesson","t":"Make it show its working","s":"","m":"AI-04","h":"modules/ai04.html#why"},{"k":"lesson","t":"The right tool per limit","s":"","m":"AI-04","h":"modules/ai04.html#s_instead"},{"k":"lesson","t":"Two minutes that save a quotation","s":"","m":"AI-04","h":"modules/ai04.html#why"},{"k":"lesson","t":"Ask so it cannot hurt you","s":"","m":"AI-04","h":"modules/ai04.html#s_design"},{"k":"lesson","t":"Four ways to blunt the risk","s":"","m":"AI-04","h":"modules/ai04.html#why"},{"k":"lesson","t":"Where people get caught","s":"","m":"AI-04","h":"modules/ai04.html#why"},{"k":"lesson","t":"What it is still excellent at","s":"Limits are not a reason to avoid it. They are a map of where to point it.","m":"AI-04","h":"modules/ai04.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"AI-04","h":"modules/ai04.html#why"},{"k":"lesson","t":"The limitation rule","s":"","m":"AI-04","h":"modules/ai04.html#why"},{"k":"term","t":"Cut-off date","s":"The point where a model's training text stops.","m":"AI-04","h":"modules/ai04.html#glossary"},{"k":"term","t":"Training data","s":"The public text a model learned from, up to that cut-off date.","m":"AI-04","h":"modules/ai04.html#glossary"},{"k":"term","t":"Hallucination","s":"A confident, invented answer. Usually a name, a number, a date or a policy.","m":"AI-04","h":"modules/ai04.html#glossary"},{"k":"term","t":"Grounding","s":"Giving the tool the actual source text so its answer has something real to stand on.","m":"AI-04","h":"modules/ai04.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: the request plus the facts you supply.","m":"AI-04","h":"modules/ai04.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"AI-04","h":"modules/ai04.html#glossary"},{"k":"rule","t":"It cannot look anything up","s":"No pages, no systems, no live data, unless the tool visibly shows you otherwise.","m":"AI-04","h":"modules/ai04.html#recap"},{"k":"rule","t":"Recent means invented","s":"Anything after the cut-off gets a plausible answer rather than an honest blank.","m":"AI-04","h":"modules/ai04.html#recap"},{"k":"rule","t":"Numbers are the weak point","s":"A precise figure reads as researched. It was produced like every other word.","m":"AI-04","h":"modules/ai04.html#recap"},{"k":"rule","t":"Confidence is not a signal","s":"The tone never changes, whether the answer is solid or entirely made up.","m":"AI-04","h":"modules/ai04.html#recap"},{"k":"rule","t":"Bring the fact to the tool","s":"Paste the clause, the figure, the circular.","m":"AI-04","h":"modules/ai04.html#recap"},{"k":"rule","t":"If you cannot check it, do not use it","s":"That is a rule about anything you sign, not a rule about AI.","m":"AI-04","h":"modules/ai04.html#recap"},{"k":"toolkit","t":"The source-labelling prompt","s":"Mark every number as mine or yours, plainly.","m":"AI-04","h":"modules/ai04.html#toolkit"},{"k":"toolkit","t":"The quotation-letter prompt","s":"Your figures, your terms, and no invented numbers.","m":"AI-04","h":"modules/ai04.html#toolkit"},{"k":"toolkit","t":"The could-it-have-changed test","s":"If yes, it is not a question for a model.","m":"AI-04","h":"modules/ai04.html#toolkit"},{"k":"module","t":"Hallucinations & Fact-Checking","s":"How to catch a confident wrong answer in under a minute, before it reaches a customer.","m":"AI-05","h":"modules/ai05.html"},{"k":"lesson","t":"A gap does not stay a gap","s":"It is not lying. It has no concept of true. It is completing a sentence in the most likely way.","m":"AI-05","h":"modules/ai05.html#s_what"},{"k":"lesson","t":"Why it never says \"I don't know\"","s":"","m":"AI-05","h":"modules/ai05.html#why"},{"k":"lesson","t":"The four risky answer types","s":"","m":"AI-05","h":"modules/ai05.html#s_where"},{"k":"lesson","t":"The tell-tale shape","s":"","m":"AI-05","h":"modules/ai05.html#why"},{"k":"lesson","t":"Four checks, under a minute","s":"Run these in order. Most answers fail or pass on step two.","m":"AI-05","h":"modules/ai05.html#s_check"},{"k":"lesson","t":"What tracing looks like","s":"","m":"AI-05","h":"modules/ai05.html#why"},{"k":"lesson","t":"Make the gaps visible","s":"","m":"AI-05","h":"modules/ai05.html#s_honest"},{"k":"lesson","t":"Grounding beats asking","s":"","m":"AI-05","h":"modules/ai05.html#why"},{"k":"lesson","t":"Correct, do not restart","s":"","m":"AI-05","h":"modules/ai05.html#s_found"},{"k":"lesson","t":"Four habits that catch them","s":"","m":"AI-05","h":"modules/ai05.html#why"},{"k":"lesson","t":"Asking twice is not checking","s":"","m":"AI-05","h":"modules/ai05.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"AI-05","h":"modules/ai05.html#why"},{"k":"lesson","t":"Where checking matters most","s":"","m":"AI-05","h":"modules/ai05.html#why"},{"k":"lesson","t":"The fact-checking rule","s":"","m":"AI-05","h":"modules/ai05.html#why"},{"k":"term","t":"Hallucination","s":"A confident, invented answer. Usually a quote, a figure, a name or a reference.","m":"AI-05","h":"modules/ai05.html#glossary"},{"k":"term","t":"Grounding","s":"Giving the tool the actual source text, so its answer has something real to stand on.","m":"AI-05","h":"modules/ai05.html#glossary"},{"k":"term","t":"Training data","s":"The public text a model learned from, up to a fixed cut-off date.","m":"AI-05","h":"modules/ai05.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: the request plus the facts you supply.","m":"AI-05","h":"modules/ai05.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"AI-05","h":"modules/ai05.html#glossary"},{"k":"term","t":"Source","s":"A document, system or person you can point at.","m":"AI-05","h":"modules/ai05.html#glossary"},{"k":"rule","t":"A gap never stays a gap","s":"It completes the sentence with something likely, rather than leaving a blank.","m":"AI-05","h":"modules/ai05.html#recap"},{"k":"rule","t":"Four risky types","s":"Quotes, figures, names and references. These are where inventions cluster.","m":"AI-05","h":"modules/ai05.html#recap"},{"k":"rule","t":"Underline, trace, open, cut","s":"Mark the details, ask who supplied them, check the source, delete the rest.","m":"AI-05","h":"modules/ai05.html#recap"},{"k":"rule","t":"Paste the document in","s":"Grounding it in real text is far safer than asking about text it cannot see.","m":"AI-05","h":"modules/ai05.html#recap"},{"k":"rule","t":"Asking twice proves nothing","s":"Two generations can agree and both be wrong.","m":"AI-05","h":"modules/ai05.html#recap"},{"k":"rule","t":"Correct, do not restart","s":"Name the error, give the right value, and protect the wording that worked.","m":"AI-05","h":"modules/ai05.html#recap"},{"k":"toolkit","t":"The honesty prompt","s":"\"If it is not in the supplied text, say so.\"","m":"AI-05","h":"modules/ai05.html#toolkit"},{"k":"toolkit","t":"The four-step check","s":"Underline, trace, open, cut. Under a minute.","m":"AI-05","h":"modules/ai05.html#toolkit"},{"k":"toolkit","t":"The correction line","s":"Name the error, give the truth, keep the rest.","m":"AI-05","h":"modules/ai05.html#toolkit"},{"k":"module","t":"Email Writing with AI","s":"Thirty emails a day, written in a third of the time, without sounding like a robot wrote them.","m":"DW-01","h":"modules/dw01.html"},{"k":"lesson","t":"Four shapes cover your week","s":"Almost every routine work email is one of these.","m":"DW-01","h":"modules/dw01.html#s_shapes"},{"k":"lesson","t":"What every shape needs","s":"","m":"DW-01","h":"modules/dw01.html#why"},{"k":"lesson","t":"Choose the tone on purpose","s":"","m":"DW-01","h":"modules/dw01.html#s_tone"},{"k":"lesson","t":"The bad-news email prompt","s":"","m":"DW-01","h":"modules/dw01.html#why"},{"k":"lesson","t":"The twelve-message thread","s":"You have been added to a thread with a decision buried in it.","m":"DW-01","h":"modules/dw01.html#s_thread"},{"k":"lesson","t":"Strip it before you paste it","s":"","m":"DW-01","h":"modules/dw01.html#why"},{"k":"lesson","t":"Where most emails fail","s":"","m":"DW-01","h":"modules/dw01.html#s_subject"},{"k":"lesson","t":"Ask for ten, keep one","s":"","m":"DW-01","h":"modules/dw01.html#why"},{"k":"lesson","t":"Do this now: write a real one","s":"","m":"DW-01","h":"modules/dw01.html#s_do"},{"k":"lesson","t":"Four habits that keep it human","s":"","m":"DW-01","h":"modules/dw01.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"DW-01","h":"modules/dw01.html#why"},{"k":"lesson","t":"When not to use it at all","s":"","m":"DW-01","h":"modules/dw01.html#why"},{"k":"lesson","t":"What good use looks like","s":"","m":"DW-01","h":"modules/dw01.html#why"},{"k":"lesson","t":"The email rule","s":"","m":"DW-01","h":"modules/dw01.html#why"},{"k":"term","t":"Tone","s":"The register of a message: firm, warm, neutral, apologetic.","m":"DW-01","h":"modules/dw01.html#glossary"},{"k":"term","t":"Thread","s":"An email conversation with replies stacked inside it.","m":"DW-01","h":"modules/dw01.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: the facts, your position, the tone and the ask.","m":"DW-01","h":"modules/dw01.html#glossary"},{"k":"term","t":"Template","s":"A prompt with brackets where the specifics go, so you reuse it without rewriting.","m":"DW-01","h":"modules/dw01.html#glossary"},{"k":"term","t":"Personal data","s":"Anything identifying a person: a name, a phone number, an address, an account.","m":"DW-01","h":"modules/dw01.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"DW-01","h":"modules/dw01.html#glossary"},{"k":"rule","t":"Four shapes cover the week","s":"Bad news, chasing, refusing, confirming. One prompt each.","m":"DW-01","h":"modules/dw01.html#recap"},{"k":"rule","t":"Facts, position, tone, ask","s":"Give it all four and the first draft is usually sendable.","m":"DW-01","h":"modules/dw01.html#recap"},{"k":"rule","t":"Name the tone, cap the apologies","s":"\"Firm, one apology at most\" beats \"make it professional\".","m":"DW-01","h":"modules/dw01.html#recap"},{"k":"rule","t":"Never paste the customer's email","s":"Describe the situation instead. The reply is just as good.","m":"DW-01","h":"modules/dw01.html#recap"},{"k":"rule","t":"Subject lines carry the message","s":"Topic plus whether they must act. Ask for ten, keep one.","m":"DW-01","h":"modules/dw01.html#recap"},{"k":"rule","t":"Read the middle before sending","s":"Openings and closings get checked. Middles carry the invented line.","m":"DW-01","h":"modules/dw01.html#recap"},{"k":"toolkit","t":"The four-bracket email prompt","s":"Facts, position, tone, ask. Covers most of a week.","m":"DW-01","h":"modules/dw01.html#toolkit"},{"k":"toolkit","t":"The thread prompt","s":"Agreed, open, my action. Three lines, forty seconds.","m":"DW-01","h":"modules/dw01.html#toolkit"},{"k":"toolkit","t":"The ten subject lines prompt","s":"Under nine words each, action or no action.","m":"DW-01","h":"modules/dw01.html#toolkit"},{"k":"module","t":"Research with AI","s":"Using it to find the right questions fast — without letting it invent the answers.","m":"DW-02","h":"modules/dw02.html"},{"k":"lesson","t":"Research has two halves","s":"AI is genuinely excellent at one of them and actively dangerous at the other.","m":"DW-02","h":"modules/dw02.html#s_halves"},{"k":"lesson","t":"Why mapping is safe","s":"","m":"DW-02","h":"modules/dw02.html#why"},{"k":"lesson","t":"Ten minutes to map a subject","s":"","m":"DW-02","h":"modules/dw02.html#s_map"},{"k":"lesson","t":"Ask for questions, not answers","s":"","m":"DW-02","h":"modules/dw02.html#why"},{"k":"lesson","t":"Facts come from sources","s":"","m":"DW-02","h":"modules/dw02.html#s_facts"},{"k":"lesson","t":"The invented citation","s":"","m":"DW-02","h":"modules/dw02.html#why"},{"k":"lesson","t":"Forty pages, four minutes","s":"This is grounded research: it can only describe text you actually gave it.","m":"DW-02","h":"modules/dw02.html#s_read"},{"k":"lesson","t":"Check the document is yours to paste","s":"","m":"DW-02","h":"modules/dw02.html#why"},{"k":"lesson","t":"Do this now: map something","s":"","m":"DW-02","h":"modules/dw02.html#s_do"},{"k":"lesson","t":"Four habits for research","s":"","m":"DW-02","h":"modules/dw02.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"DW-02","h":"modules/dw02.html#why"},{"k":"lesson","t":"What good research looks like","s":"","m":"DW-02","h":"modules/dw02.html#why"},{"k":"lesson","t":"The research rule","s":"","m":"DW-02","h":"modules/dw02.html#why"},{"k":"term","t":"Grounding","s":"Giving the tool the actual source text so its answer has something real to stand on.","m":"DW-02","h":"modules/dw02.html#glossary"},{"k":"term","t":"Citation","s":"A reference to a real document. AI produces convincing ones that do not exist.","m":"DW-02","h":"modules/dw02.html#glossary"},{"k":"term","t":"Mapping","s":"Learning the shape of a subject: its terms, its questions, its usual mistakes.","m":"DW-02","h":"modules/dw02.html#glossary"},{"k":"term","t":"Cut-off date","s":"The point where a model's training text stops.","m":"DW-02","h":"modules/dw02.html#glossary"},{"k":"term","t":"Hallucination","s":"A confident, invented answer. Citations and statistics are the classic cases.","m":"DW-02","h":"modules/dw02.html#glossary"},{"k":"term","t":"Source","s":"A document, system or person you can point at.","m":"DW-02","h":"modules/dw02.html#glossary"},{"k":"rule","t":"Research has two halves","s":"Mapping a subject, and verifying facts. AI does the first well and the second never.","m":"DW-02","h":"modules/dw02.html#recap"},{"k":"rule","t":"Ask for questions, not answers","s":"The person in the meeting knows. Your job is knowing what to ask them.","m":"DW-02","h":"modules/dw02.html#recap"},{"k":"rule","t":"Ban numbers in mapping prompts","s":"\"No numbers, no standards, no prices\" removes what it would invent.","m":"DW-02","h":"modules/dw02.html#recap"},{"k":"rule","t":"Paste public documents","s":"Grounded reading of a real circular is safe, fast and checkable.","m":"DW-02","h":"modules/dw02.html#recap"},{"k":"rule","t":"Never paste private ones","s":"Contracts, customer specifications and internal policy stay where they are.","m":"DW-02","h":"modules/dw02.html#recap"},{"k":"rule","t":"Open the source before quoting","s":"Anything you will repeat out loud has to survive a thirty-second check.","m":"DW-02","h":"modules/dw02.html#recap"},{"k":"toolkit","t":"The subject-mapping prompt","s":"Eight terms, five questions, three mistakes, no numbers.","m":"DW-02","h":"modules/dw02.html#toolkit"},{"k":"toolkit","t":"The document-reading prompt","s":"Requires, deadlines, unclear — with exact wording quoted.","m":"DW-02","h":"modules/dw02.html#toolkit"},{"k":"toolkit","t":"The public-or-private test","s":"Published document, paste it. Ours, read it yourself.","m":"DW-02","h":"modules/dw02.html#toolkit"},{"k":"module","t":"Report Preparation with AI","s":"Turning what you already know into a report somebody actually reads to the end.","m":"DW-03","h":"modules/dw03.html"},{"k":"lesson","t":"Page eleven is too late","s":"Most work reports are written in the order the work happened.","m":"DW-03","h":"modules/dw03.html#s_first"},{"k":"lesson","t":"The one paragraph that matters","s":"","m":"DW-03","h":"modules/dw03.html#why"},{"k":"lesson","t":"One shape for every report","s":"","m":"DW-03","h":"modules/dw03.html#s_shape"},{"k":"lesson","t":"Why a fixed shape helps","s":"","m":"DW-03","h":"modules/dw03.html#why"},{"k":"lesson","t":"Rough notes into a report","s":"","m":"DW-03","h":"modules/dw03.html#s_notes"},{"k":"lesson","t":"The line that protects you","s":"","m":"DW-03","h":"modules/dw03.html#why"},{"k":"lesson","t":"Cut it without losing it","s":"","m":"DW-03","h":"modules/dw03.html#s_cut"},{"k":"lesson","t":"What to cut, what to keep","s":"","m":"DW-03","h":"modules/dw03.html#why"},{"k":"lesson","t":"Do this now: rewrite one","s":"","m":"DW-03","h":"modules/dw03.html#s_do"},{"k":"lesson","t":"Before it leaves your desk","s":"","m":"DW-03","h":"modules/dw03.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"DW-03","h":"modules/dw03.html#why"},{"k":"lesson","t":"Reports you should not automate","s":"","m":"DW-03","h":"modules/dw03.html#why"},{"k":"lesson","t":"What a good report does","s":"","m":"DW-03","h":"modules/dw03.html#why"},{"k":"lesson","t":"The report rule","s":"","m":"DW-03","h":"modules/dw03.html#why"},{"k":"term","t":"Executive summary","s":"The opening paragraph carrying the conclusion, the reason and the ask.","m":"DW-03","h":"modules/dw03.html#glossary"},{"k":"term","t":"Finding","s":"Something you observed. Different from a cause, which is an explanation of it.","m":"DW-03","h":"modules/dw03.html#glossary"},{"k":"term","t":"Cause","s":"Why something happened. Only you can establish this, and only if you checked.","m":"DW-03","h":"modules/dw03.html#glossary"},{"k":"term","t":"[CHECK]","s":"A marker the tool writes where a fact is missing, instead of inventing one.","m":"DW-03","h":"modules/dw03.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: your notes, the structure and the constraints.","m":"DW-03","h":"modules/dw03.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"DW-03","h":"modules/dw03.html#glossary"},{"k":"rule","t":"Answer first, always","s":"Conclusion, reason and ask in the first eighty words.","m":"DW-03","h":"modules/dw03.html#recap"},{"k":"rule","t":"One shape every time","s":"Found, matters, recommend, saw. Faster to write and to read.","m":"DW-03","h":"modules/dw03.html#recap"},{"k":"rule","t":"Never let it supply causes","s":"It was not there. An invented cause sends people to fix the wrong thing.","m":"DW-03","h":"modules/dw03.html#recap"},{"k":"rule","t":"Mark gaps with [CHECK]","s":"A visible gap is worth far more than a smooth invention.","m":"DW-03","h":"modules/dw03.html#recap"},{"k":"rule","t":"Protect before you cut","s":"Name the numbers, dates and recommendations that must survive.","m":"DW-03","h":"modules/dw03.html#recap"},{"k":"rule","t":"Write for the reader who stops","s":"Almost nobody reaches the end. Design for the first page.","m":"DW-03","h":"modules/dw03.html#recap"},{"k":"toolkit","t":"The notes-into-report prompt","s":"Four-part structure, no invented causes, [CHECK] for gaps.","m":"DW-03","h":"modules/dw03.html#toolkit"},{"k":"toolkit","t":"The opening-paragraph prompt","s":"Conclusion, reason and ask in under eighty words.","m":"DW-03","h":"modules/dw03.html#toolkit"},{"k":"toolkit","t":"The safe-cutting prompt","s":"Half the length, with numbers and dates protected.","m":"DW-03","h":"modules/dw03.html#toolkit"},{"k":"module","t":"Data Analysis with AI","s":"Getting a straight answer out of your numbers, without letting it do the arithmetic.","m":"DW-04","h":"modules/dw04.html"},{"k":"lesson","t":"It predicts, it does not add","s":"A total is text to it, produced the same way as a sentence.","m":"DW-04","h":"modules/dw04.html#s_why"},{"k":"lesson","t":"Where the arithmetic breaks","s":"","m":"DW-04","h":"modules/dw04.html#why"},{"k":"lesson","t":"Excel calculates, AI explains","s":"","m":"DW-04","h":"modules/dw04.html#s_split"},{"k":"lesson","t":"The two-minute workflow","s":"","m":"DW-04","h":"modules/dw04.html#why"},{"k":"lesson","t":"Questions it answers well","s":"Anything about the shape of the data, once you have supplied the numbers.","m":"DW-04","h":"modules/dw04.html#s_ask"},{"k":"lesson","t":"The questions-to-check prompt","s":"","m":"DW-04","h":"modules/dw04.html#why"},{"k":"lesson","t":"Movements, never causes","s":"","m":"DW-04","h":"modules/dw04.html#s_desc"},{"k":"lesson","t":"What must never be pasted","s":"","m":"DW-04","h":"modules/dw04.html#why"},{"k":"lesson","t":"Do this now: summarise figures","s":"","m":"DW-04","h":"modules/dw04.html#s_do"},{"k":"lesson","t":"Four checks before it goes out","s":"","m":"DW-04","h":"modules/dw04.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"DW-04","h":"modules/dw04.html#why"},{"k":"lesson","t":"When to use a chart tool instead","s":"","m":"DW-04","h":"modules/dw04.html#why"},{"k":"lesson","t":"What good analysis looks like","s":"","m":"DW-04","h":"modules/dw04.html#why"},{"k":"lesson","t":"The data rule","s":"","m":"DW-04","h":"modules/dw04.html#why"},{"k":"term","t":"Aggregate","s":"A calculated summary — a total, an average, a top five — rather than the underlying rows.","m":"DW-04","h":"modules/dw04.html#glossary"},{"k":"term","t":"Anonymise","s":"Replacing names and identifiers with labels like Customer A, so nobody can be identified.","m":"DW-04","h":"modules/dw04.html#glossary"},{"k":"term","t":"Movement","s":"A change between two periods. Something you calculate and the tool describes.","m":"DW-04","h":"modules/dw04.html#glossary"},{"k":"term","t":"Cause","s":"Why something changed. Only established by you, never by the tool.","m":"DW-04","h":"modules/dw04.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: your calculated figures and the constraints.","m":"DW-04","h":"modules/dw04.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"DW-04","h":"modules/dw04.html#glossary"},{"k":"rule","t":"It does not calculate","s":"A total is produced as text. Over a long column it drifts, and looks fine.","m":"DW-04","h":"modules/dw04.html#recap"},{"k":"rule","t":"Excel first, always","s":"Totals, averages, percentages and rankings before anything is pasted.","m":"DW-04","h":"modules/dw04.html#recap"},{"k":"rule","t":"Paste results, not raw rows","s":"Six aggregated lines instead of forty rows with customers attached.","m":"DW-04","h":"modules/dw04.html#recap"},{"k":"rule","t":"Describe, never explain","s":"It can word a movement. It cannot know why the movement happened.","m":"DW-04","h":"modules/dw04.html#recap"},{"k":"rule","t":"Anonymise before pasting","s":"Customer A to E works perfectly well and exposes nobody.","m":"DW-04","h":"modules/dw04.html#recap"},{"k":"rule","t":"Check every figure back","s":"Each number in the text must match your spreadsheet exactly.","m":"DW-04","h":"modules/dw04.html#recap"},{"k":"toolkit","t":"The results-into-summary prompt","s":"Three movements, no calculating, no causes.","m":"DW-04","h":"modules/dw04.html#toolkit"},{"k":"toolkit","t":"The sceptical-manager prompt","s":"Five questions they would ask, unanswered.","m":"DW-04","h":"modules/dw04.html#toolkit"},{"k":"toolkit","t":"The aggregate-and-anonymise habit","s":"Excel first, Customer A to E, then paste.","m":"DW-04","h":"modules/dw04.html#toolkit"},{"k":"module","t":"Excel with AI","s":"Formulas written for you, messy data cleaned up, and every one of them tested on a single row first.","m":"DW-05","h":"modules/dw05.html"},{"k":"lesson","t":"Describe it in plain English","s":"You do not need to remember the syntax. You need to describe the job precisely.","m":"DW-05","h":"modules/dw05.html#s_describe"},{"k":"lesson","t":"The formula prompt","s":"","m":"DW-05","h":"modules/dw05.html#why"},{"k":"lesson","t":"Test it on one row first","s":"","m":"DW-05","h":"modules/dw05.html#s_test"},{"k":"lesson","t":"Why the one-row test matters","s":"","m":"DW-05","h":"modules/dw05.html#why"},{"k":"lesson","t":"Paste the error, not the sheet","s":"","m":"DW-05","h":"modules/dw05.html#s_fix"},{"k":"lesson","t":"The error-fixing prompt","s":"","m":"DW-05","h":"modules/dw05.html#why"},{"k":"lesson","t":"Cleaning without retyping","s":"","m":"DW-05","h":"modules/dw05.html#s_clean"},{"k":"lesson","t":"Ask for the steps, not the result","s":"For cleaning, the instructions are more useful than an answer, because you keep control of the sheet.","m":"DW-05","h":"modules/dw05.html#why"},{"k":"lesson","t":"Do this now: solve one problem","s":"","m":"DW-05","h":"modules/dw05.html#s_do"},{"k":"lesson","t":"Four habits with Excel and AI","s":"","m":"DW-05","h":"modules/dw05.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"DW-05","h":"modules/dw05.html#why"},{"k":"lesson","t":"Formula or macro?","s":"","m":"DW-05","h":"modules/dw05.html#why"},{"k":"lesson","t":"What good use looks like","s":"","m":"DW-05","h":"modules/dw05.html#why"},{"k":"lesson","t":"The Excel rule","s":"","m":"DW-05","h":"modules/dw05.html#why"},{"k":"term","t":"Formula","s":"An instruction Excel calculates itself. Checkable, repeatable and safe.","m":"DW-05","h":"modules/dw05.html#glossary"},{"k":"term","t":"Lookup","s":"Matching a value in one sheet against a table in another, such as VLOOKUP or XLOOKUP.","m":"DW-05","h":"modules/dw05.html#glossary"},{"k":"term","t":"#N/A","s":"Excel's way of saying it found no match. Usually a text versus number problem.","m":"DW-05","h":"modules/dw05.html#glossary"},{"k":"term","t":"One-row test","s":"Checking a formula against a row whose answer you already know, before filling down.","m":"DW-05","h":"modules/dw05.html#glossary"},{"k":"term","t":"Personal data","s":"Anything identifying a person: a name, a phone number, an account, an employee number.","m":"DW-05","h":"modules/dw05.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: your column descriptions and what you want to happen.","m":"DW-05","h":"modules/dw05.html#glossary"},{"k":"rule","t":"Describe, do not remember","s":"Name the sheets, the columns and what you want.","m":"DW-05","h":"modules/dw05.html#recap"},{"k":"rule","t":"Say what to do when nothing matches","s":"Otherwise half the column shows an error code you then misdiagnose.","m":"DW-05","h":"modules/dw05.html#recap"},{"k":"rule","t":"Test one row, every time","s":"A wrong formula does not error. It returns six hundred plausible answers.","m":"DW-05","h":"modules/dw05.html#recap"},{"k":"rule","t":"Paste the error, never the sheet","s":"The formula and the column descriptions are all it needs.","m":"DW-05","h":"modules/dw05.html#recap"},{"k":"rule","t":"Prefer a formula to an answer","s":"It lives in the sheet, updates itself, and solves next quarter too.","m":"DW-05","h":"modules/dw05.html#recap"},{"k":"rule","t":"Keep the ones that worked","s":"A notes file of five working formulas saves the same fight twice.","m":"DW-05","h":"modules/dw05.html#recap"},{"k":"toolkit","t":"The formula prompt","s":"Columns, what you want, what if missing, formula only.","m":"DW-05","h":"modules/dw05.html#toolkit"},{"k":"toolkit","t":"The error-fixing prompt","s":"The formula, the error, and what the columns hold.","m":"DW-05","h":"modules/dw05.html#toolkit"},{"k":"toolkit","t":"The one-row test","s":"A row you know the answer to, before you fill down.","m":"DW-05","h":"modules/dw05.html#toolkit"},{"k":"module","t":"Presentations with AI","s":"Get the argument straight before you open PowerPoint.","m":"DW-06","h":"modules/dw06.html"},{"k":"lesson","t":"Write the argument first","s":"If you cannot say it in ten lines, thirty slides will not rescue it.","m":"DW-06","h":"modules/dw06.html#s_argument"},{"k":"lesson","t":"The ten-line test","s":"","m":"DW-06","h":"modules/dw06.html#why"},{"k":"lesson","t":"One slide, one point","s":"","m":"DW-06","h":"modules/dw06.html#s_outline"},{"k":"lesson","t":"Titles that say something","s":"","m":"DW-06","h":"modules/dw06.html#why"},{"k":"lesson","t":"Half the slides, same message","s":"","m":"DW-06","h":"modules/dw06.html#s_cut"},{"k":"lesson","t":"The appendix is your friend","s":"","m":"DW-06","h":"modules/dw06.html#why"},{"k":"lesson","t":"Know the questions first","s":"Being stopped on slide four is normal. Being unprepared for it is a choice.","m":"DW-06","h":"modules/dw06.html#s_questions"},{"k":"lesson","t":"Speaker notes you can say","s":"","m":"DW-06","h":"modules/dw06.html#why"},{"k":"lesson","t":"Do this now: outline a deck","s":"","m":"DW-06","h":"modules/dw06.html#s_do"},{"k":"lesson","t":"What not to paste in","s":"","m":"DW-06","h":"modules/dw06.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"DW-06","h":"modules/dw06.html#why"},{"k":"lesson","t":"Should AI build the slides?","s":"","m":"DW-06","h":"modules/dw06.html#why"},{"k":"lesson","t":"What good preparation looks like","s":"","m":"DW-06","h":"modules/dw06.html#why"},{"k":"lesson","t":"The presentation rule","s":"","m":"DW-06","h":"modules/dw06.html#why"},{"k":"term","t":"Argument","s":"The point you want agreed, the reasons for it, and what you are asking for.","m":"DW-06","h":"modules/dw06.html#glossary"},{"k":"term","t":"Sentence title","s":"A slide heading that states the point rather than naming the topic.","m":"DW-06","h":"modules/dw06.html#glossary"},{"k":"term","t":"Appendix","s":"Slides kept after the end, ready if asked, invisible if not.","m":"DW-06","h":"modules/dw06.html#glossary"},{"k":"term","t":"Speaker notes","s":"What you will actually say, written as spoken sentences.","m":"DW-06","h":"modules/dw06.html#glossary"},{"k":"term","t":"[WEAK]","s":"A marker showing a reason you have asserted without evidence.","m":"DW-06","h":"modules/dw06.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: your notes, the structure and the constraints.","m":"DW-06","h":"modules/dw06.html#glossary"},{"k":"rule","t":"Argument before slides","s":"Point, three reasons, evidence, ask. Ten lines, at your desk.","m":"DW-06","h":"modules/dw06.html#recap"},{"k":"rule","t":"Fix [WEAK] before you build","s":"An unevidenced reason is where you will be stopped.","m":"DW-06","h":"modules/dw06.html#recap"},{"k":"rule","t":"One slide, one point","s":"Eight slides for a routine review is usually plenty.","m":"DW-06","h":"modules/dw06.html#recap"},{"k":"rule","t":"Titles that say something","s":"Read the titles alone and the argument should be complete.","m":"DW-06","h":"modules/dw06.html#recap"},{"k":"rule","t":"Appendix, not delete","s":"Move detail out of the way instead of throwing it away.","m":"DW-06","h":"modules/dw06.html#recap"},{"k":"rule","t":"Rehearse the five questions","s":"Hardest first, with the evidence located before the meeting.","m":"DW-06","h":"modules/dw06.html#recap"},{"k":"toolkit","t":"The ten-line argument prompt","s":"Point, reasons, evidence, ask, with [WEAK] flags.","m":"DW-06","h":"modules/dw06.html#toolkit"},{"k":"toolkit","t":"The slide outline prompt","s":"Eight sentence titles and what each visual shows.","m":"DW-06","h":"modules/dw06.html#toolkit"},{"k":"toolkit","t":"The hard-questions prompt","s":"Five questions, hardest first, unsoftened.","m":"DW-06","h":"modules/dw06.html#toolkit"},{"k":"module","t":"Documentation with AI","s":"SOPs, process notes and handovers somebody can follow without ringing you to ask what you meant.","m":"DW-07","h":"modules/dw07.html"},{"k":"lesson","t":"Experts write the worst steps","s":"The steps you leave out are exactly the ones you stopped noticing years ago.","m":"DW-07","h":"modules/dw07.html#s_curse"},{"k":"lesson","t":"What gets left out","s":"","m":"DW-07","h":"modules/dw07.html#why"},{"k":"lesson","t":"Talk it through, do not compose","s":"Explaining it out loud to an imaginary new joiner produces far better raw material than writing does.","m":"DW-07","h":"modules/dw07.html#s_talk"},{"k":"lesson","t":"What a good step looks like","s":"","m":"DW-07","h":"modules/dw07.html#why"},{"k":"lesson","t":"The new-joiner test","s":"","m":"DW-07","h":"modules/dw07.html#s_test"},{"k":"lesson","t":"Then test it on a person","s":"","m":"DW-07","h":"modules/dw07.html#why"},{"k":"lesson","t":"Documents rot quietly","s":"","m":"DW-07","h":"modules/dw07.html#s_current"},{"k":"lesson","t":"The update prompt","s":"","m":"DW-07","h":"modules/dw07.html#why"},{"k":"lesson","t":"Do this now: document one","s":"","m":"DW-07","h":"modules/dw07.html#s_do"},{"k":"lesson","t":"What not to put in a procedure","s":"","m":"DW-07","h":"modules/dw07.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"DW-07","h":"modules/dw07.html#why"},{"k":"lesson","t":"How much detail is right?","s":"","m":"DW-07","h":"modules/dw07.html#why"},{"k":"lesson","t":"The handover document","s":"","m":"DW-07","h":"modules/dw07.html#why"},{"k":"lesson","t":"The documentation rule","s":"","m":"DW-07","h":"modules/dw07.html#why"},{"k":"term","t":"SOP","s":"Standard Operating Procedure. A written process somebody can follow without asking questions.","m":"DW-07","h":"modules/dw07.html#glossary"},{"k":"term","t":"[GAP]","s":"A marker the tool writes where a beginner would need information you did not supply.","m":"DW-07","h":"modules/dw07.html#glossary"},{"k":"term","t":"Handover","s":"A document covering what you do, who to call, and what usually goes wrong while you are away.","m":"DW-07","h":"modules/dw07.html#glossary"},{"k":"term","t":"Curse of knowledge","s":"The habit of leaving out steps that have become invisible to you through practice.","m":"DW-07","h":"modules/dw07.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: your explanation and the constraints on shaping it.","m":"DW-07","h":"modules/dw07.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"DW-07","h":"modules/dw07.html#glossary"},{"k":"rule","t":"Experts leave out the obvious","s":"The steps you stopped noticing are the first four questions a beginner has.","m":"DW-07","h":"modules/dw07.html#recap"},{"k":"rule","t":"Talk it, then shape it","s":"Explaining out loud produces better raw material than writing does.","m":"DW-07","h":"modules/dw07.html#recap"},{"k":"rule","t":"One action per step","s":"Start with a verb, name the system, say what success looks like.","m":"DW-07","h":"modules/dw07.html#recap"},{"k":"rule","t":"Answer every [GAP]","s":"The marker exists so a missing step is visible rather than invented.","m":"DW-07","h":"modules/dw07.html#recap"},{"k":"rule","t":"Test it on a beginner","s":"Every hesitation is a defect. Watch, do not help, write it down.","m":"DW-07","h":"modules/dw07.html#recap"},{"k":"rule","t":"Date it and own it","s":"Undated documents get ignored. Unowned documents never get fixed.","m":"DW-07","h":"modules/dw07.html#recap"},{"k":"toolkit","t":"The shaping prompt","s":"Rambling explanation in, numbered steps and [GAP] markers out.","m":"DW-07","h":"modules/dw07.html#toolkit"},{"k":"toolkit","t":"The new-joiner test prompt","s":"Every point a beginner would stop and ask.","m":"DW-07","h":"modules/dw07.html#toolkit"},{"k":"toolkit","t":"The update prompt","s":"Change only affected steps, and list which ones.","m":"DW-07","h":"modules/dw07.html#toolkit"},{"k":"module","t":"Meeting Notes & Follow-ups","s":"Turning an hour of discussion into decisions and owners, before anyone leaves the room.","m":"DW-08","h":"modules/dw08.html"},{"k":"lesson","t":"Why minutes fail","s":"Most meeting notes record the conversation.","m":"DW-08","h":"modules/dw08.html#s_fail"},{"k":"lesson","t":"\"We agreed to look into it\"","s":"","m":"DW-08","h":"modules/dw08.html#why"},{"k":"lesson","t":"Only three columns matter","s":"","m":"DW-08","h":"modules/dw08.html#s_three"},{"k":"lesson","t":"Everything else is optional","s":"","m":"DW-08","h":"modules/dw08.html#why"},{"k":"lesson","t":"Five minutes after the meeting","s":"","m":"DW-08","h":"modules/dw08.html#s_rough"},{"k":"lesson","t":"The markers are the point","s":"","m":"DW-08","h":"modules/dw08.html#why"},{"k":"lesson","t":"Before you press record","s":"","m":"DW-08","h":"modules/dw08.html#s_record"},{"k":"lesson","t":"Notes are usually enough","s":"","m":"DW-08","h":"modules/dw08.html#why"},{"k":"lesson","t":"Do this now: process a meeting","s":"","m":"DW-08","h":"modules/dw08.html#s_do"},{"k":"lesson","t":"Chasing without an argument","s":"","m":"DW-08","h":"modules/dw08.html#why"},{"k":"lesson","t":"Four habits after every meeting","s":"","m":"DW-08","h":"modules/dw08.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"DW-08","h":"modules/dw08.html#why"},{"k":"lesson","t":"The follow-up that ends a meeting","s":"","m":"DW-08","h":"modules/dw08.html#why"},{"k":"lesson","t":"The meeting notes rule","s":"","m":"DW-08","h":"modules/dw08.html#why"},{"k":"term","t":"Action","s":"Something one named person will do by a stated date.","m":"DW-08","h":"modules/dw08.html#glossary"},{"k":"term","t":"Owner","s":"The single person accountable. Never a team, never two people.","m":"DW-08","h":"modules/dw08.html#glossary"},{"k":"term","t":"Open item","s":"Something not settled, with a named person bringing it back.","m":"DW-08","h":"modules/dw08.html#glossary"},{"k":"term","t":"Transcript","s":"A written record of everything said. Personal data about everyone present.","m":"DW-08","h":"modules/dw08.html#glossary"},{"k":"term","t":"Personal data","s":"Anything identifying a person, including their recorded voice and words.","m":"DW-08","h":"modules/dw08.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: your rough notes and the structure you want back.","m":"DW-08","h":"modules/dw08.html#glossary"},{"k":"rule","t":"Record decisions, not discussion","s":"Nobody ever goes back to read who said what.","m":"DW-08","h":"modules/dw08.html#recap"},{"k":"rule","t":"One name, one date","s":"\"The team will\" is not an action. It is a gap with a sentence around it.","m":"DW-08","h":"modules/dw08.html#recap"},{"k":"rule","t":"Mark the gaps, do not guess","s":"[OWNER?] and [DATE?] get closed in one message the same afternoon.","m":"DW-08","h":"modules/dw08.html#recap"},{"k":"rule","t":"Send it the same day","s":"Overnight, people half-remember a different meeting and act on it.","m":"DW-08","h":"modules/dw08.html#recap"},{"k":"rule","t":"Recording needs consent","s":"A transcript is personal data about everyone in the room.","m":"DW-08","h":"modules/dw08.html#recap"},{"k":"rule","t":"Chase neutrally","s":"State the dates, ask for a new one, and skip the apology.","m":"DW-08","h":"modules/dw08.html#recap"},{"k":"toolkit","t":"The three-section prompt","s":"Decisions, actions with owners, open items.","m":"DW-08","h":"modules/dw08.html#toolkit"},{"k":"toolkit","t":"The gap-closing message","s":"Every [OWNER?] and [DATE?] as one short question set.","m":"DW-08","h":"modules/dw08.html#toolkit"},{"k":"toolkit","t":"The neutral chaser","s":"Dates stated, no apology, new date requested.","m":"DW-08","h":"modules/dw08.html#toolkit"},{"k":"module","t":"Brainstorming with AI","s":"Twenty options in two minutes, and a way to tell which three are actually worth your time.","m":"DW-09","h":"modules/dw09.html"},{"k":"lesson","t":"Twenty beats four","s":"Meetings stall because people arrive with their best idea, not with twenty rough ones.","m":"DW-09","h":"modules/dw09.html#s_quantity"},{"k":"lesson","t":"Nobody owns a generated idea","s":"","m":"DW-09","h":"modules/dw09.html#why"},{"k":"lesson","t":"Ask for the bad ones too","s":"","m":"DW-09","h":"modules/dw09.html#s_range"},{"k":"lesson","t":"Why impossible ideas help","s":"","m":"DW-09","h":"modules/dw09.html#why"},{"k":"lesson","t":"Twenty down to three","s":"","m":"DW-09","h":"modules/dw09.html#s_sort"},{"k":"lesson","t":"The sorting prompt","s":"","m":"DW-09","h":"modules/dw09.html#why"},{"k":"lesson","t":"When two people are stuck","s":"Deadlocks are rarely about the options. They are about two people having stated a position out loud.","m":"DW-09","h":"modules/dw09.html#s_stuck"},{"k":"lesson","t":"Ideas that are quietly impossible","s":"","m":"DW-09","h":"modules/dw09.html#why"},{"k":"lesson","t":"Do this now: generate twenty","s":"","m":"DW-09","h":"modules/dw09.html#s_do"},{"k":"lesson","t":"Four habits for idea sessions","s":"","m":"DW-09","h":"modules/dw09.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"DW-09","h":"modules/dw09.html#why"},{"k":"lesson","t":"When brainstorming is the wrong tool","s":"","m":"DW-09","h":"modules/dw09.html#why"},{"k":"lesson","t":"What good use looks like","s":"","m":"DW-09","h":"modules/dw09.html#why"},{"k":"lesson","t":"The brainstorming rule","s":"","m":"DW-09","h":"modules/dw09.html#why"},{"k":"term","t":"Divergent thinking","s":"Producing many options without judging them.","m":"DW-09","h":"modules/dw09.html#glossary"},{"k":"term","t":"Convergent thinking","s":"Narrowing many options down to a decision.","m":"DW-09","h":"modules/dw09.html#glossary"},{"k":"term","t":"Constraint","s":"Something that rules an option out: a contract, a licence, a budget, a piece of equipment.","m":"DW-09","h":"modules/dw09.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: the problem, the range you want and the format.","m":"DW-09","h":"modules/dw09.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Raw material, none of which has been checked against reality.","m":"DW-09","h":"modules/dw09.html#glossary"},{"k":"term","t":"Deadlock","s":"Two stated positions and no movement. Usually social rather than analytical.","m":"DW-09","h":"modules/dw09.html#glossary"},{"k":"rule","t":"Twenty beats four","s":"Meetings stall because people bring their best idea, not twenty rough ones.","m":"DW-09","h":"modules/dw09.html#recap"},{"k":"rule","t":"Ask for range deliberately","s":"Five obvious, ten unusual, five impractical.","m":"DW-09","h":"modules/dw09.html#recap"},{"k":"rule","t":"Nobody owns a generated idea","s":"Seniority and ego stop deciding which options survive.","m":"DW-09","h":"modules/dw09.html#recap"},{"k":"rule","t":"Strike before you discuss","s":"Already tried, no budget, not permitted. Striking is fast.","m":"DW-09","h":"modules/dw09.html#recap"},{"k":"rule","t":"Test what one person can try in a week","s":"Two quick tests beat one twelve-month proposal.","m":"DW-09","h":"modules/dw09.html#recap"},{"k":"rule","t":"It does not know our constraints","s":"Contracts, licences and equipment are the room's job, not its own.","m":"DW-09","h":"modules/dw09.html#recap"},{"k":"toolkit","t":"The twenty-ideas prompt","s":"Five obvious, ten unusual, five impractical.","m":"DW-09","h":"modules/dw09.html#toolkit"},{"k":"toolkit","t":"The sorting prompt","s":"Testable in a week, needs budget, not worth pursuing.","m":"DW-09","h":"modules/dw09.html#toolkit"},{"k":"toolkit","t":"The deadlock prompt","s":"Five options that are neither A nor B, plus two combinations.","m":"DW-09","h":"modules/dw09.html#toolkit"},{"k":"module","t":"Planning with AI","s":"Turning a long list of intentions into a week you can actually finish.","m":"DW-10","h":"modules/dw10.html"},{"k":"lesson","t":"Sort by what breaks","s":"Urgency is a feeling and it is usually somebody else's.","m":"DW-10","h":"modules/dw10.html#s_sort"},{"k":"lesson","t":"The consequence prompt","s":"","m":"DW-10","h":"modules/dw10.html#why"},{"k":"lesson","t":"Plan three days, not five","s":"","m":"DW-10","h":"modules/dw10.html#s_three"},{"k":"lesson","t":"A realistic day","s":"","m":"DW-10","h":"modules/dw10.html#why"},{"k":"lesson","t":"The task that never starts","s":"Tasks that sit on a list for weeks are almost always unclear rather than hard.","m":"DW-10","h":"modules/dw10.html#s_stuck"},{"k":"lesson","t":"Why tasks stick","s":"","m":"DW-10","h":"modules/dw10.html#why"},{"k":"lesson","t":"The not-doing list","s":"","m":"DW-10","h":"modules/dw10.html#s_not"},{"k":"lesson","t":"Moved, not deleted","s":"","m":"DW-10","h":"modules/dw10.html#why"},{"k":"lesson","t":"Do this now: sort your list","s":"","m":"DW-10","h":"modules/dw10.html#s_do"},{"k":"lesson","t":"The five-minute weekly review","s":"","m":"DW-10","h":"modules/dw10.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"DW-10","h":"modules/dw10.html#why"},{"k":"lesson","t":"What not to paste into a planner","s":"","m":"DW-10","h":"modules/dw10.html#why"},{"k":"lesson","t":"Planning is not the work","s":"","m":"DW-10","h":"modules/dw10.html#why"},{"k":"lesson","t":"The planning rule","s":"","m":"DW-10","h":"modules/dw10.html#why"},{"k":"term","t":"Consequence","s":"What actually happens if a task slips. The only reliable way to sort a long list.","m":"DW-10","h":"modules/dw10.html#glossary"},{"k":"term","t":"Not-now list","s":"A separate file for items with no consequence, reviewed monthly rather than daily.","m":"DW-10","h":"modules/dw10.html#glossary"},{"k":"term","t":"Planning horizon","s":"How far ahead you can usefully plan. Around three days for most operational roles.","m":"DW-10","h":"modules/dw10.html#glossary"},{"k":"term","t":"First action","s":"The concrete five minutes that starts a stuck task.","m":"DW-10","h":"modules/dw10.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: your list and the sorting tests you want applied.","m":"DW-10","h":"modules/dw10.html#glossary"},{"k":"term","t":"Output","s":"What comes back. A suggested order, which you still decide on.","m":"DW-10","h":"modules/dw10.html#glossary"},{"k":"rule","t":"Sort by consequence","s":"What breaks if it slips. Urgency belongs to whoever shouted last.","m":"DW-10","h":"modules/dw10.html#recap"},{"k":"rule","t":"Plan three days","s":"Friday is fiction on Monday. Re-plan midweek in five minutes.","m":"DW-10","h":"modules/dw10.html#recap"},{"k":"rule","t":"Halve your estimates","s":"Almost everyone is about fifty per cent optimistic, consistently.","m":"DW-10","h":"modules/dw10.html#recap"},{"k":"rule","t":"Stuck means undefined","s":"Ask for the first five minutes and the information you are missing.","m":"DW-10","h":"modules/dw10.html#recap"},{"k":"rule","t":"Keep a not-now list","s":"Moved, not deleted. It turns background guilt into a decision.","m":"DW-10","h":"modules/dw10.html#recap"},{"k":"rule","t":"Re-planning is not working","s":"Twice a week is a system. Four times is avoidance.","m":"DW-10","h":"modules/dw10.html#recap"},{"k":"toolkit","t":"The consequence sort","s":"Stops something, customer notices, blocks a colleague, no consequence.","m":"DW-10","h":"modules/dw10.html#toolkit"},{"k":"toolkit","t":"The realistic day prompt","s":"Six hours, estimates halved, and what will not fit.","m":"DW-10","h":"modules/dw10.html#toolkit"},{"k":"toolkit","t":"The unsticking prompt","s":"First five minutes, and the input you are missing.","m":"DW-10","h":"modules/dw10.html#toolkit"},{"k":"module","t":"Automation Basics","s":"Spotting the jobs worth automating, and describing one clearly enough that somebody can actually build it.","m":"DW-11","h":"modules/dw11.html"},{"k":"lesson","t":"Rules can be automated","s":"If you can write the job as \"when this happens, do exactly that\", it can be automated.","m":"DW-11","h":"modules/dw11.html#s_what"},{"k":"lesson","t":"The three parts of any automation","s":"","m":"DW-11","h":"modules/dw11.html#why"},{"k":"lesson","t":"Four questions that find one","s":"","m":"DW-11","h":"modules/dw11.html#s_spot"},{"k":"lesson","t":"Four yeses is a candidate","s":"","m":"DW-11","h":"modules/dw11.html#why"},{"k":"lesson","t":"Describe it, do not build it","s":"Most automation requests fail because the description is vague, not because the tool was wrong.","m":"DW-11","h":"modules/dw11.html#s_describe"},{"k":"lesson","t":"Vague request, clear request","s":"","m":"DW-11","h":"modules/dw11.html#why"},{"k":"lesson","t":"Where automation hurts","s":"","m":"DW-11","h":"modules/dw11.html#s_manual"},{"k":"lesson","t":"The rule about approvals","s":"","m":"DW-11","h":"modules/dw11.html#why"},{"k":"lesson","t":"Do this now: describe one job","s":"","m":"DW-11","h":"modules/dw11.html#s_do"},{"k":"lesson","t":"Exceptions are the hard part","s":"","m":"DW-11","h":"modules/dw11.html#why"},{"k":"lesson","t":"Three rules for anything running","s":"","m":"DW-11","h":"modules/dw11.html#why"},{"k":"lesson","t":"What must never be in the description","s":"","m":"DW-11","h":"modules/dw11.html#why"},{"k":"lesson","t":"Is it worth automating?","s":"","m":"DW-11","h":"modules/dw11.html#why"},{"k":"lesson","t":"The automation rule","s":"","m":"DW-11","h":"modules/dw11.html#why"},{"k":"term","t":"Trigger","s":"What starts an automation: a time, a file arriving, an email, a form submission.","m":"DW-11","h":"modules/dw11.html#glossary"},{"k":"term","t":"Exception","s":"A case where reality does not match the rule.","m":"DW-11","h":"modules/dw11.html#glossary"},{"k":"term","t":"Specification","s":"A description clear enough that somebody who has never seen your job could build it.","m":"DW-11","h":"modules/dw11.html#glossary"},{"k":"term","t":"Owner","s":"The named person responsible for an automation and for switching it off.","m":"DW-11","h":"modules/dw11.html#glossary"},{"k":"term","t":"Judgement","s":"A decision needing context a rule cannot see.","m":"DW-11","h":"modules/dw11.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: your process description and the constraints.","m":"DW-11","h":"modules/dw11.html#glossary"},{"k":"rule","t":"Rules can be automated","s":"\"When this happens, do exactly that.\" If you cannot write it that way, it is not ready.","m":"DW-11","h":"modules/dw11.html#recap"},{"k":"rule","t":"Four questions find a candidate","s":"Frequent, identical, transferable, mechanical.","m":"DW-11","h":"modules/dw11.html#recap"},{"k":"rule","t":"Describe, do not build","s":"Trigger, steps in order, exceptions, and who gets told.","m":"DW-11","h":"modules/dw11.html#recap"},{"k":"rule","t":"Exceptions are the real work","s":"Missing files, duplicates and wrong formats are where things fail silently.","m":"DW-11","h":"modules/dw11.html#recap"},{"k":"rule","t":"Never automate the check","s":"If a step exists so a person looks, that step is the whole point.","m":"DW-11","h":"modules/dw11.html#recap"},{"k":"rule","t":"Someone owns it, someone can stop it","s":"Named owner, documented purpose, and an off switch anyone can use.","m":"DW-11","h":"modules/dw11.html#recap"},{"k":"toolkit","t":"The interview prompt","s":"One question at a time until the process is documented.","m":"DW-11","h":"modules/dw11.html#toolkit"},{"k":"toolkit","t":"The exception prompt","s":"Every way it could go wrong, and what to do instead.","m":"DW-11","h":"modules/dw11.html#toolkit"},{"k":"toolkit","t":"The four-question test","s":"Frequent, identical, transferable, mechanical.","m":"DW-11","h":"modules/dw11.html#toolkit"},{"k":"module","t":"Basic Prompting","s":"The first prompt you ever write — and the six-part shape that makes it work every time, not just when you get lucky.","m":"PE-01","h":"modules/pe01.html"},{"k":"lesson","t":"Why \"write an email\" fails","s":"The tool is not guessing badly. It is guessing — because you left it nothing else to do.","m":"PE-01","h":"modules/pe01.html#s_fail"},{"k":"lesson","t":"A prompt is a briefing","s":"Think of it as briefing a capable temp on their first morning.","m":"PE-01","h":"modules/pe01.html#why"},{"k":"lesson","t":"The six parts of a good prompt","s":"Say these six things and there is almost nothing left for the tool to guess.","m":"PE-01","h":"modules/pe01.html#s_six"},{"k":"lesson","t":"The six parts, in one paragraph","s":"You do not need headings or bullet points.","m":"PE-01","h":"modules/pe01.html#why"},{"k":"lesson","t":"Build one now, with your own work","s":"","m":"PE-01","h":"modules/pe01.html#s_build"},{"k":"lesson","t":"Four words versus six parts","s":"","m":"PE-01","h":"modules/pe01.html#why"},{"k":"lesson","t":"Length, tone and format do the work","s":"","m":"PE-01","h":"modules/pe01.html#s_out"},{"k":"lesson","t":"Ask for a table, get a table","s":"","m":"PE-01","h":"modules/pe01.html#why"},{"k":"lesson","t":"Words that make a prompt worse","s":"","m":"PE-01","h":"modules/pe01.html#why"},{"k":"lesson","t":"One follow-up beats a restart","s":"","m":"PE-01","h":"modules/pe01.html#s_fix"},{"k":"lesson","t":"Three follow-ups that always work","s":"","m":"PE-01","h":"modules/pe01.html#why"},{"k":"lesson","t":"When not to bother prompting","s":"","m":"PE-01","h":"modules/pe01.html#why"},{"k":"lesson","t":"Keep your best prompts","s":"The people who get the most out of these tools are not the fastest typists.","m":"PE-01","h":"modules/pe01.html#why"},{"k":"lesson","t":"A prompt you can reuse tomorrow","s":"","m":"PE-01","h":"modules/pe01.html#why"},{"k":"lesson","t":"Never put these in a prompt","s":"","m":"PE-01","h":"modules/pe01.html#why"},{"k":"term","t":"Prompt","s":"Everything you type in: the request plus the facts you choose to supply.","m":"PE-01","h":"modules/pe01.html#glossary"},{"k":"term","t":"Context","s":"The background you give so the tool knows who the text is for and why it is being written.","m":"PE-01","h":"modules/pe01.html#glossary"},{"k":"term","t":"Token","s":"A small piece of text, roughly three quarters of a word.","m":"PE-01","h":"modules/pe01.html#glossary"},{"k":"term","t":"Zero-shot","s":"Asking for something without showing an example first.","m":"PE-01","h":"modules/pe01.html#glossary"},{"k":"term","t":"Few-shot","s":"Giving one or two examples of what good looks like before you make your request.","m":"PE-01","h":"modules/pe01.html#glossary"},{"k":"term","t":"Output","s":"What comes back. A draft you are responsible for, never a source you can quote.","m":"PE-01","h":"modules/pe01.html#glossary"},{"k":"rule","t":"Six parts, one paragraph","s":"Task, context, facts, tone, length, format — in plain sentences.","m":"PE-01","h":"modules/pe01.html#recap"},{"k":"rule","t":"The facts are your job","s":"Dates, numbers and names are the part only you have.","m":"PE-01","h":"modules/pe01.html#recap"},{"k":"rule","t":"Say the number","s":"\"Under 100 words.\" \"Exactly five bullets.\" \"Three columns.\" Vague in, vague out.","m":"PE-01","h":"modules/pe01.html#recap"},{"k":"rule","t":"Adjectives do nothing","s":"\"Professional\", \"better\", \"urgent\" give it nothing to act on.","m":"PE-01","h":"modules/pe01.html#recap"},{"k":"rule","t":"Correct, don't restart","s":"\"Keep the first two paragraphs. Cut to 80 words.\" One line saves the whole draft.","m":"PE-01","h":"modules/pe01.html#recap"},{"k":"rule","t":"Save the shape, not the details","s":"Store the prompt with brackets where the customer data used to be.","m":"PE-01","h":"modules/pe01.html#recap"},{"k":"toolkit","t":"The six-part prompt","s":"Task, context, facts, tone, length, format.","m":"PE-01","h":"modules/pe01.html#toolkit"},{"k":"toolkit","t":"The \"make it a table\" prompt","s":"Name the columns, then say \"no extra commentary\".","m":"PE-01","h":"modules/pe01.html#toolkit"},{"k":"toolkit","t":"The one-line correction","s":"Keep what worked, name the change, supply the new fact.","m":"PE-01","h":"modules/pe01.html#toolkit"},{"k":"module","t":"Instructions & Context","s":"How much background to give — and the point where adding more starts making the answer worse.","m":"PE-02","h":"modules/pe02.html"},{"k":"lesson","t":"Four lines it cannot guess","s":"Without these it invents a company, a reader and a situation.","m":"PE-02","h":"modules/pe02.html#s_four"},{"k":"lesson","t":"What each line prevents","s":"","m":"PE-02","h":"modules/pe02.html#why"},{"k":"lesson","t":"Instruction or context?","s":"","m":"PE-02","h":"modules/pe02.html#s_vs"},{"k":"lesson","t":"Both, in one paragraph","s":"","m":"PE-02","h":"modules/pe02.html#why"},{"k":"lesson","t":"Say what not to do","s":"Three habits show up in almost every AI draft.","m":"PE-02","h":"modules/pe02.html#s_not"},{"k":"lesson","t":"The three lines to reuse","s":"","m":"PE-02","h":"modules/pe02.html#why"},{"k":"lesson","t":"Where extra context hurts","s":"","m":"PE-02","h":"modules/pe02.html#s_much"},{"k":"lesson","t":"Too little, right, too much","s":"","m":"PE-02","h":"modules/pe02.html#why"},{"k":"lesson","t":"Do this now: rewrite one prompt","s":"","m":"PE-02","h":"modules/pe02.html#s_do"},{"k":"lesson","t":"Context you should never add","s":"","m":"PE-02","h":"modules/pe02.html#why"},{"k":"lesson","t":"Four habits worth keeping","s":"","m":"PE-02","h":"modules/pe02.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PE-02","h":"modules/pe02.html#why"},{"k":"lesson","t":"What good context looks like","s":"","m":"PE-02","h":"modules/pe02.html#why"},{"k":"lesson","t":"The context rule","s":"","m":"PE-02","h":"modules/pe02.html#why"},{"k":"term","t":"Context","s":"The background you give so the tool knows who the text is for and why it is being written.","m":"PE-02","h":"modules/pe02.html#glossary"},{"k":"term","t":"Instruction","s":"What to do with that background: the task, the length, the tone, the format.","m":"PE-02","h":"modules/pe02.html#glossary"},{"k":"term","t":"Negative instruction","s":"Naming something you do not want, so a common habit is ruled out.","m":"PE-02","h":"modules/pe02.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: context plus instructions plus your facts.","m":"PE-02","h":"modules/pe02.html#glossary"},{"k":"term","t":"Token","s":"A small piece of text, roughly three quarters of a word.","m":"PE-02","h":"modules/pe02.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"PE-02","h":"modules/pe02.html#glossary"},{"k":"rule","t":"Four lines it cannot guess","s":"Who is reading, what we do, where we are, why it matters now.","m":"PE-02","h":"modules/pe02.html#recap"},{"k":"rule","t":"Context is not instruction","s":"One describes the situation, the other says what to do with it.","m":"PE-02","h":"modules/pe02.html#recap"},{"k":"rule","t":"Say what not to do","s":"No pleasantries, no restating the request, one specific apology.","m":"PE-02","h":"modules/pe02.html#recap"},{"k":"rule","t":"Volume equals emphasis","s":"Whatever you write most about becomes what the answer is about.","m":"PE-02","h":"modules/pe02.html#recap"},{"k":"rule","t":"The new colleague test","s":"Would they need this to do the job? If not, leave it out.","m":"PE-02","h":"modules/pe02.html#recap"},{"k":"rule","t":"Never identify anyone","s":"Every useful context line can be written without a name or a number.","m":"PE-02","h":"modules/pe02.html#recap"},{"k":"toolkit","t":"The four context lines","s":"Reader, business, place, urgency. One clause each.","m":"PE-02","h":"modules/pe02.html#toolkit"},{"k":"toolkit","t":"The three do-not lines","s":"No pleasantries, no preamble, one specific apology.","m":"PE-02","h":"modules/pe02.html#toolkit"},{"k":"toolkit","t":"The context-and-instructions prompt","s":"Two labelled blocks, works as written.","m":"PE-02","h":"modules/pe02.html#toolkit"},{"k":"module","t":"Role-Based Prompts","s":"\"Act as a…\" — what it actually changes, when it helps, and when it is just decoration.","m":"PE-03","h":"modules/pe03.html"},{"k":"lesson","t":"What a role actually changes","s":"It does not make the tool an expert. It shifts which words and which level of detail become likely.","m":"PE-03","h":"modules/pe03.html#s_change"},{"k":"lesson","t":"The same facts, two readers","s":"","m":"PE-03","h":"modules/pe03.html#why"},{"k":"lesson","t":"Name the reader, not the expert","s":"","m":"PE-03","h":"modules/pe03.html#s_reader"},{"k":"lesson","t":"The reader line, ready to use","s":"","m":"PE-03","h":"modules/pe03.html#why"},{"k":"lesson","t":"Three roles that work","s":"","m":"PE-03","h":"modules/pe03.html#s_work"},{"k":"lesson","t":"The critic role, ready to use","s":"","m":"PE-03","h":"modules/pe03.html#why"},{"k":"lesson","t":"Roles that do nothing","s":"","m":"PE-03","h":"modules/pe03.html#s_bad"},{"k":"lesson","t":"The authority trap","s":"","m":"PE-03","h":"modules/pe03.html#why"},{"k":"lesson","t":"Do this now: three roles","s":"","m":"PE-03","h":"modules/pe03.html#s_do"},{"k":"lesson","t":"Why three viewpoints work","s":"","m":"PE-03","h":"modules/pe03.html#why"},{"k":"lesson","t":"Four habits with roles","s":"","m":"PE-03","h":"modules/pe03.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PE-03","h":"modules/pe03.html#why"},{"k":"lesson","t":"When to skip the role entirely","s":"","m":"PE-03","h":"modules/pe03.html#why"},{"k":"lesson","t":"The role rule","s":"","m":"PE-03","h":"modules/pe03.html#why"},{"k":"term","t":"Role prompt","s":"A line naming who the answer is written by or for, which shifts vocabulary and depth.","m":"PE-03","h":"modules/pe03.html#glossary"},{"k":"term","t":"Persona","s":"Another word for the role you give the tool.","m":"PE-03","h":"modules/pe03.html#glossary"},{"k":"term","t":"Context","s":"The background you give so the tool knows the situation it is writing about.","m":"PE-03","h":"modules/pe03.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: context plus instructions plus your facts.","m":"PE-03","h":"modules/pe03.html#glossary"},{"k":"term","t":"Hallucination","s":"A confident, invented answer. A role makes these sound more authoritative, not less likely.","m":"PE-03","h":"modules/pe03.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"PE-03","h":"modules/pe03.html#glossary"},{"k":"rule","t":"A role shifts words, not knowledge","s":"Vocabulary, depth and assumptions change.","m":"PE-03","h":"modules/pe03.html#recap"},{"k":"rule","t":"Name the reader first","s":"Who receives it decides the language, the order and the length.","m":"PE-03","h":"modules/pe03.html#recap"},{"k":"rule","t":"Say what they must do next","s":"\"Will speak to the customer at 11\" sets urgency and shape in one clause.","m":"PE-03","h":"modules/pe03.html#recap"},{"k":"rule","t":"Use roles to attack, not to agree","s":"\"List what annoys you about this\" is worth far more than approval.","m":"PE-03","h":"modules/pe03.html#recap"},{"k":"rule","t":"Three seats beat one","s":"Ask as doer, payer and receiver. Fix whatever appears in two of three.","m":"PE-03","h":"modules/pe03.html#recap"},{"k":"rule","t":"Never impersonate a colleague","s":"You would be inventing the position of someone who can read the transcript.","m":"PE-03","h":"modules/pe03.html#recap"},{"k":"toolkit","t":"The reader line","s":"Who they are, what they lack, what they must do next.","m":"PE-03","h":"modules/pe03.html#toolkit"},{"k":"toolkit","t":"The critic prompt","s":"Three objections, in order, and no rewriting.","m":"PE-03","h":"modules/pe03.html#toolkit"},{"k":"toolkit","t":"The three-seats prompt","s":"Doer, payer, receiver. Two problems each.","m":"PE-03","h":"modules/pe03.html#toolkit"},{"k":"module","t":"Examples & Structured Prompts","s":"Showing one good example beats three paragraphs describing what good looks like.","m":"PE-04","h":"modules/pe04.html"},{"k":"lesson","t":"Why one example wins","s":"Describing a format is a translation step.","m":"PE-04","h":"modules/pe04.html#s_show"},{"k":"lesson","t":"Describing versus showing","s":"","m":"PE-04","h":"modules/pe04.html#why"},{"k":"lesson","t":"The one-example prompt","s":"","m":"PE-04","h":"modules/pe04.html#s_one"},{"k":"lesson","t":"What makes an example work","s":"","m":"PE-04","h":"modules/pe04.html#why"},{"k":"lesson","t":"Two examples fix a tone","s":"Tone is the thing people describe worst and recognise instantly.","m":"PE-04","h":"modules/pe04.html#s_two"},{"k":"lesson","t":"How many examples to give","s":"","m":"PE-04","h":"modules/pe04.html#why"},{"k":"lesson","t":"Structure that cannot drift","s":"","m":"PE-04","h":"modules/pe04.html#s_blank"},{"k":"lesson","t":"Where structure pays off most","s":"","m":"PE-04","h":"modules/pe04.html#why"},{"k":"lesson","t":"Do this now: build one template","s":"","m":"PE-04","h":"modules/pe04.html#s_do"},{"k":"lesson","t":"Never put these in an example","s":"","m":"PE-04","h":"modules/pe04.html#why"},{"k":"lesson","t":"Four habits with examples","s":"","m":"PE-04","h":"modules/pe04.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PE-04","h":"modules/pe04.html#why"},{"k":"lesson","t":"Describe or show?","s":"","m":"PE-04","h":"modules/pe04.html#why"},{"k":"lesson","t":"The example rule","s":"","m":"PE-04","h":"modules/pe04.html#why"},{"k":"term","t":"Few-shot","s":"Giving one or two worked examples before your request, so the pattern is shown rather than described.","m":"PE-04","h":"modules/pe04.html#glossary"},{"k":"term","t":"Zero-shot","s":"Asking without any example. Fine for simple jobs, weak for formats and tone.","m":"PE-04","h":"modules/pe04.html#glossary"},{"k":"term","t":"Template","s":"A reusable prompt with brackets where the specifics go.","m":"PE-04","h":"modules/pe04.html#glossary"},{"k":"term","t":"Structured prompt","s":"A prompt with fixed headings the answer must fill in, so every result is comparable.","m":"PE-04","h":"modules/pe04.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: context plus instructions plus your facts.","m":"PE-04","h":"modules/pe04.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"PE-04","h":"modules/pe04.html#glossary"},{"k":"rule","t":"Show, do not describe","s":"A description must be interpreted. An example cannot be misread.","m":"PE-04","h":"modules/pe04.html#recap"},{"k":"rule","t":"One example fixes structure","s":"Layout, order, punctuation and bracket style, all in one line.","m":"PE-04","h":"modules/pe04.html#recap"},{"k":"rule","t":"Two examples fix tone","s":"Register is easy to recognise and almost impossible to describe.","m":"PE-04","h":"modules/pe04.html#recap"},{"k":"rule","t":"Always add \"nothing else\"","s":"Otherwise you get your format plus a heading and an introduction.","m":"PE-04","h":"modules/pe04.html#recap"},{"k":"rule","t":"Use capitals for structure","s":"SITUATION, IMPACT, NEXT UPDATE. Headings in capitals get followed.","m":"PE-04","h":"modules/pe04.html#recap"},{"k":"rule","t":"Never show a real record","s":"The format works with invented data. A real one leaks a real customer.","m":"PE-04","h":"modules/pe04.html#recap"},{"k":"toolkit","t":"The one-example prompt","s":"One perfect line, then \"same pattern, nothing else\".","m":"PE-04","h":"modules/pe04.html#toolkit"},{"k":"toolkit","t":"The two-example tone prompt","s":"Two short samples, then your new message.","m":"PE-04","h":"modules/pe04.html#toolkit"},{"k":"toolkit","t":"The fill-in-the-blanks structure","s":"Capital headings, one sentence each, [CHECK] for gaps.","m":"PE-04","h":"modules/pe04.html#toolkit"},{"k":"module","t":"Advanced Prompting","s":"Breaking a big job into steps, setting limits the answer must respect, and checking the work as you go.","m":"PE-05","h":"modules/pe05.html"},{"k":"lesson","t":"The middle nobody checks","s":"A four-stage request produces one polished answer.","m":"PE-05","h":"modules/pe05.html#s_big"},{"k":"lesson","t":"One ask versus four","s":"","m":"PE-05","h":"modules/pe05.html#why"},{"k":"lesson","t":"Four asks instead of one","s":"","m":"PE-05","h":"modules/pe05.html#s_chain"},{"k":"lesson","t":"The tick between the steps","s":"The value is not the four prompts. It is the ten seconds you spend between them.","m":"PE-05","h":"modules/pe05.html#why"},{"k":"lesson","t":"Limits it must respect","s":"","m":"PE-05","h":"modules/pe05.html#s_limits"},{"k":"lesson","t":"Four constraints worth reusing","s":"","m":"PE-05","h":"modules/pe05.html#why"},{"k":"lesson","t":"Ask it to show its working","s":"For anything with reasoning in it, the steps are more checkable than the conclusion.","m":"PE-05","h":"modules/pe05.html#s_work"},{"k":"lesson","t":"What visible steps do not fix","s":"","m":"PE-05","h":"modules/pe05.html#why"},{"k":"lesson","t":"Do this now: chain a task","s":"","m":"PE-05","h":"modules/pe05.html#s_do"},{"k":"lesson","t":"Chained versus all at once","s":"","m":"PE-05","h":"modules/pe05.html#why"},{"k":"lesson","t":"When chaining is worth it","s":"","m":"PE-05","h":"modules/pe05.html#why"},{"k":"lesson","t":"Three habits worth keeping","s":"","m":"PE-05","h":"modules/pe05.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PE-05","h":"modules/pe05.html#why"},{"k":"lesson","t":"The advanced prompting rule","s":"","m":"PE-05","h":"modules/pe05.html#why"},{"k":"term","t":"Chaining","s":"Breaking one large request into ordered steps, checking each before the next uses it.","m":"PE-05","h":"modules/pe05.html#glossary"},{"k":"term","t":"Constraint","s":"A limit the answer must respect: a source, a word count, a forbidden habit.","m":"PE-05","h":"modules/pe05.html#glossary"},{"k":"term","t":"Step-by-step","s":"Asking the tool to show its intermediate reasoning rather than only the conclusion.","m":"PE-05","h":"modules/pe05.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: context plus instructions plus your facts.","m":"PE-05","h":"modules/pe05.html#glossary"},{"k":"term","t":"Hallucination","s":"A confident, invented answer. Chaining makes these easier to catch early.","m":"PE-05","h":"modules/pe05.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"PE-05","h":"modules/pe05.html#glossary"},{"k":"rule","t":"Split where errors hide","s":"Break the job at the points a mistake would be invisible in the final answer.","m":"PE-05","h":"modules/pe05.html#recap"},{"k":"rule","t":"Check between every step","s":"Four prompts with no reading between them is one prompt with extra steps.","m":"PE-05","h":"modules/pe05.html#recap"},{"k":"rule","t":"Feed forward only what you approved","s":"\"Using only the three I ticked\" stops cut items reappearing.","m":"PE-05","h":"modules/pe05.html#recap"},{"k":"rule","t":"Constrain the source","s":"\"Use only what I pasted\" plus [MISSING] for anything absent.","m":"PE-05","h":"modules/pe05.html#recap"},{"k":"rule","t":"Numbers, not adjectives","s":"\"200 words\" works. \"Be concise\" does not.","m":"PE-05","h":"modules/pe05.html#recap"},{"k":"rule","t":"Shown working is checkable, not correct","s":"It makes an error findable. It does not make the answer right.","m":"PE-05","h":"modules/pe05.html#recap"},{"k":"toolkit","t":"The four-step chain","s":"Requirements, gaps, fixes, note. Approve each one.","m":"PE-05","h":"modules/pe05.html#toolkit"},{"k":"toolkit","t":"The constraint block","s":"Source, [MISSING], word count, no padding.","m":"PE-05","h":"modules/pe05.html#toolkit"},{"k":"toolkit","t":"The show-your-working prompt","s":"Figures and origins first, then the calculation.","m":"PE-05","h":"modules/pe05.html#toolkit"},{"k":"module","t":"Reusable Prompts","s":"Turning the prompts that worked into a library you and your team stop rewriting every week.","m":"PE-06","h":"modules/pe06.html"},{"k":"lesson","t":"The Monday morning tax","s":"The prompt that worked is thinking you already did.","m":"PE-06","h":"modules/pe06.html#s_lost"},{"k":"lesson","t":"Which prompts are worth keeping","s":"","m":"PE-06","h":"modules/pe06.html#why"},{"k":"lesson","t":"Brackets do the work","s":"","m":"PE-06","h":"modules/pe06.html#s_template"},{"k":"lesson","t":"Make the template for me","s":"","m":"PE-06","h":"modules/pe06.html#why"},{"k":"lesson","t":"Name it the way you search","s":"A prompt you cannot find in ten seconds is a prompt you will rewrite.","m":"PE-06","h":"modules/pe06.html#s_store"},{"k":"lesson","t":"Where a library actually lives","s":"","m":"PE-06","h":"modules/pe06.html#why"},{"k":"lesson","t":"What must never be saved","s":"","m":"PE-06","h":"modules/pe06.html#s_share"},{"k":"lesson","t":"Strip it before you save it","s":"","m":"PE-06","h":"modules/pe06.html#why"},{"k":"lesson","t":"Do this now: build three","s":"","m":"PE-06","h":"modules/pe06.html#s_do"},{"k":"lesson","t":"Improving a stored prompt","s":"","m":"PE-06","h":"modules/pe06.html#why"},{"k":"lesson","t":"Four habits that keep it alive","s":"","m":"PE-06","h":"modules/pe06.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PE-06","h":"modules/pe06.html#why"},{"k":"lesson","t":"What a good library looks like","s":"","m":"PE-06","h":"modules/pe06.html#why"},{"k":"lesson","t":"The reusable prompt rule","s":"","m":"PE-06","h":"modules/pe06.html#why"},{"k":"term","t":"Template","s":"A prompt with brackets where the specifics go, so it can be reused without rewriting.","m":"PE-06","h":"modules/pe06.html#glossary"},{"k":"term","t":"Prompt library","s":"A shared file of named prompts your team reuses instead of writing from scratch.","m":"PE-06","h":"modules/pe06.html#glossary"},{"k":"term","t":"Bracket","s":"A labelled gap like [CLIENT] that says what belongs there, and keeps real data out.","m":"PE-06","h":"modules/pe06.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: context plus instructions plus your facts.","m":"PE-06","h":"modules/pe06.html#glossary"},{"k":"term","t":"Context","s":"The background you give so the tool knows the situation it is writing about.","m":"PE-06","h":"modules/pe06.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"PE-06","h":"modules/pe06.html#glossary"},{"k":"rule","t":"Save it the day it works","s":"The tab closes and the thinking goes with it.","m":"PE-06","h":"modules/pe06.html#recap"},{"k":"rule","t":"Brackets mark what changes","s":"[CLIENT], [WEEK], [NUMBER]. Ten seconds to fill, every time.","m":"PE-06","h":"modules/pe06.html#recap"},{"k":"rule","t":"Brackets also keep it safe","s":"No real name, account or price is ever stored in the file.","m":"PE-06","h":"modules/pe06.html#recap"},{"k":"rule","t":"Name it after the job","s":"\"Weekly ticket summary\", never \"structured prompt v3\".","m":"PE-06","h":"modules/pe06.html#recap"},{"k":"rule","t":"Fix the template, not the copy","s":"One line added to the stored version fixes it for everybody.","m":"PE-06","h":"modules/pe06.html#recap"},{"k":"rule","t":"Twenty is plenty","s":"A library nobody reads is a library that gets rewritten from scratch.","m":"PE-06","h":"modules/pe06.html#recap"},{"k":"toolkit","t":"The four-bracket template","s":"What, format, reader, tone. Covers most writing jobs.","m":"PE-06","h":"modules/pe06.html#toolkit"},{"k":"toolkit","t":"The template-builder prompt","s":"Turns a prompt that worked into a reusable one.","m":"PE-06","h":"modules/pe06.html#toolkit"},{"k":"toolkit","t":"The strip-before-saving check","s":"Bracket every name, number and price first.","m":"PE-06","h":"modules/pe06.html#toolkit"},{"k":"module","t":"Evaluating AI Responses","s":"A thirty-second way to decide whether to send it, fix it or throw it away.","m":"PE-07","h":"modules/pe07.html"},{"k":"lesson","t":"Four questions, thirty seconds","s":"Ask these in order. Most answers fail on question two, and you stop there.","m":"PE-07","h":"modules/pe07.html#s_four"},{"k":"lesson","t":"Why fluency fools people","s":"","m":"PE-07","h":"modules/pe07.html#why"},{"k":"lesson","t":"Send, fix or throw away","s":"","m":"PE-07","h":"modules/pe07.html#s_decide"},{"k":"lesson","t":"The three-way test in practice","s":"","m":"PE-07","h":"modules/pe07.html#why"},{"k":"lesson","t":"Keep, change, supply","s":"","m":"PE-07","h":"modules/pe07.html#s_fix"},{"k":"lesson","t":"Corrections that do not work","s":"","m":"PE-07","h":"modules/pe07.html#why"},{"k":"lesson","t":"The answer that dodges","s":"Some answers are perfectly written and contain nothing.","m":"PE-07","h":"modules/pe07.html#s_dodge"},{"k":"lesson","t":"Three signs of an empty answer","s":"","m":"PE-07","h":"modules/pe07.html#why"},{"k":"lesson","t":"Do this now: score one answer","s":"","m":"PE-07","h":"modules/pe07.html#s_do"},{"k":"lesson","t":"Comparing two answers fast","s":"","m":"PE-07","h":"modules/pe07.html#why"},{"k":"lesson","t":"Four habits before you send","s":"","m":"PE-07","h":"modules/pe07.html#why"},{"k":"lesson","t":"The round-four rule","s":"","m":"PE-07","h":"modules/pe07.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PE-07","h":"modules/pe07.html#why"},{"k":"lesson","t":"The evaluation rule","s":"","m":"PE-07","h":"modules/pe07.html#why"},{"k":"term","t":"Evaluation","s":"Deciding whether an answer can be sent, needs fixing, or should be thrown away.","m":"PE-07","h":"modules/pe07.html#glossary"},{"k":"term","t":"Traceable","s":"Every fact in the answer can be pointed back to something you supplied.","m":"PE-07","h":"modules/pe07.html#glossary"},{"k":"term","t":"Correction","s":"A follow-up naming what to keep, what to change, and the correct value.","m":"PE-07","h":"modules/pe07.html#glossary"},{"k":"term","t":"Hedging","s":"Answering both ways at once. Usually a sign it has nothing specific to say.","m":"PE-07","h":"modules/pe07.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type in: context plus instructions plus your facts.","m":"PE-07","h":"modules/pe07.html#glossary"},{"k":"term","t":"Output","s":"What comes back. Your draft, which you are responsible for checking.","m":"PE-07","h":"modules/pe07.html#glossary"},{"k":"rule","t":"Four questions, thirty seconds","s":"Traceable, complete, usable, safe. Most answers fail on the second.","m":"PE-07","h":"modules/pe07.html#recap"},{"k":"rule","t":"Ignore how well it reads","s":"Fluency is constant, so it carries no information about quality.","m":"PE-07","h":"modules/pe07.html#recap"},{"k":"rule","t":"Read the middle first","s":"That is where the invented step or date survives a skim.","m":"PE-07","h":"modules/pe07.html#recap"},{"k":"rule","t":"Keep, change, supply","s":"Protect the good part, name two changes, give the right value.","m":"PE-07","h":"modules/pe07.html#recap"},{"k":"rule","t":"Balance means it has nothing","s":"Ask for one recommendation and two reasons instead.","m":"PE-07","h":"modules/pe07.html#recap"},{"k":"rule","t":"Round four means rewrite","s":"Three rounds of drift is a prompt problem, not an answer problem.","m":"PE-07","h":"modules/pe07.html#recap"},{"k":"toolkit","t":"The four questions","s":"Traceable, complete, usable, safe. Thirty seconds.","m":"PE-07","h":"modules/pe07.html#toolkit"},{"k":"toolkit","t":"The correction pattern","s":"Keep this, change that, here is the right value.","m":"PE-07","h":"modules/pe07.html#toolkit"},{"k":"toolkit","t":"The comparison prompt","s":"Differences in substance only, one line each.","m":"PE-07","h":"modules/pe07.html#toolkit"},{"k":"module","t":"Business Communication","s":"Getting a decision out of people who are busy, in messages they read to the end.","m":"PS-01","h":"modules/ps01.html"},{"k":"lesson","t":"Put the ask in line one","s":"Most people read the first line and the last.","m":"PS-01","h":"modules/ps01.html#s_ask"},{"k":"lesson","t":"The four-part message","s":"","m":"PS-01","h":"modules/ps01.html#why"},{"k":"lesson","t":"Two questions get one answer","s":"","m":"PS-01","h":"modules/ps01.html#s_one"},{"k":"lesson","t":"The message, ready to use","s":"","m":"PS-01","h":"modules/ps01.html#why"},{"k":"lesson","t":"Email is not always right","s":"","m":"PS-01","h":"modules/ps01.html#s_channel"},{"k":"lesson","t":"The escalation ladder","s":"","m":"PS-01","h":"modules/ps01.html#why"},{"k":"lesson","t":"Say what silence means","s":"A deadline with no consequence attached is a suggestion, and everybody treats it as one.","m":"PS-01","h":"modules/ps01.html#s_default"},{"k":"lesson","t":"When not to use a default","s":"","m":"PS-01","h":"modules/ps01.html#why"},{"k":"lesson","t":"Do this now: rewrite one","s":"","m":"PS-01","h":"modules/ps01.html#s_do"},{"k":"lesson","t":"The subject line does work","s":"","m":"PS-01","h":"modules/ps01.html#why"},{"k":"lesson","t":"Four habits worth having","s":"","m":"PS-01","h":"modules/ps01.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PS-01","h":"modules/ps01.html#why"},{"k":"lesson","t":"Writing for someone senior","s":"","m":"PS-01","h":"modules/ps01.html#why"},{"k":"lesson","t":"The communication rule","s":"","m":"PS-01","h":"modules/ps01.html#why"},{"k":"term","t":"Ask","s":"The one thing you need the reader to do. It belongs in the first sentence.","m":"PS-01","h":"modules/ps01.html#glossary"},{"k":"term","t":"Stated default","s":"What you will do if nobody replies. It turns silence into a decision.","m":"PS-01","h":"modules/ps01.html#glossary"},{"k":"term","t":"Channel","s":"Email, call, chat or in person. Choosing deliberately prevents most communication problems.","m":"PS-01","h":"modules/ps01.html#glossary"},{"k":"term","t":"Escalation","s":"Moving a stalled request to a call, then to a manager, factually and without complaint.","m":"PS-01","h":"modules/ps01.html#glossary"},{"k":"term","t":"Front-loading","s":"Putting the conclusion and the request before the reasoning.","m":"PS-01","h":"modules/ps01.html#glossary"},{"k":"term","t":"Background","s":"Context for the few readers who want it. Always below the ask.","m":"PS-01","h":"modules/ps01.html#glossary"},{"k":"rule","t":"Ask first, always","s":"What you need and by when, in the first sentence.","m":"PS-01","h":"modules/ps01.html#recap"},{"k":"rule","t":"One message, one ask","s":"Two questions reliably produce one answer and a week of chasing.","m":"PS-01","h":"modules/ps01.html#recap"},{"k":"rule","t":"Say what happens if not","s":"A deadline with no consequence is read as a preference.","m":"PS-01","h":"modules/ps01.html#recap"},{"k":"rule","t":"Subject lines carry the decision","s":"Name the decision and the date, not the topic.","m":"PS-01","h":"modules/ps01.html#recap"},{"k":"rule","t":"Change channel, do not repeat","s":"After one missed deadline, a two-minute call beats a third email.","m":"PS-01","h":"modules/ps01.html#recap"},{"k":"rule","t":"Disagreement goes on the phone","s":"Tone is unreadable in text, and both sides reread it uncharitably.","m":"PS-01","h":"modules/ps01.html#recap"},{"k":"toolkit","t":"The five-bracket message","s":"Ask, deadline, consequence, options, background below.","m":"PS-01","h":"modules/ps01.html#toolkit"},{"k":"toolkit","t":"The stated default","s":"\"If I do not hear by Thursday, I will proceed with A.\"","m":"PS-01","h":"modules/ps01.html#toolkit"},{"k":"toolkit","t":"The channel test","s":"Record, disagreement, quick question, or a person.","m":"PS-01","h":"modules/ps01.html#toolkit"},{"k":"module","t":"Professional Email Writing","s":"The mechanics — subject lines, openings, tone, and knowing when not to send at all.","m":"PS-02","h":"modules/ps02.html"},{"k":"lesson","t":"Delete the first sentence","s":"The first sentence of most work emails carries no information.","m":"PS-02","h":"modules/ps02.html#s_open"},{"k":"lesson","t":"The four-part email","s":"","m":"PS-02","h":"modules/ps02.html#why"},{"k":"lesson","t":"Four phrases to retire","s":"","m":"PS-02","h":"modules/ps02.html#s_phrases"},{"k":"lesson","t":"Say what you want instead","s":"","m":"PS-02","h":"modules/ps02.html#why"},{"k":"lesson","t":"Neutral is a skill","s":"When you are annoyed, the email you write will read angrier than you meant.","m":"PS-02","h":"modules/ps02.html#s_tone"},{"k":"lesson","t":"The neutral chaser","s":"","m":"PS-02","h":"modules/ps02.html#why"},{"k":"lesson","t":"Three times not to send","s":"","m":"PS-02","h":"modules/ps02.html#s_dont"},{"k":"lesson","t":"The reply-all question","s":"","m":"PS-02","h":"modules/ps02.html#why"},{"k":"lesson","t":"Do this now: fix one email","s":"","m":"PS-02","h":"modules/ps02.html#s_do"},{"k":"lesson","t":"The ten-second check","s":"","m":"PS-02","h":"modules/ps02.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PS-02","h":"modules/ps02.html#why"},{"k":"lesson","t":"The close does the warmth","s":"","m":"PS-02","h":"modules/ps02.html#why"},{"k":"lesson","t":"Writing across cultures","s":"","m":"PS-02","h":"modules/ps02.html#why"},{"k":"lesson","t":"The email rule","s":"","m":"PS-02","h":"modules/ps02.html#why"},{"k":"term","t":"Throat-clearing","s":"An opening sentence that carries no information.","m":"PS-02","h":"modules/ps02.html#glossary"},{"k":"term","t":"Tone","s":"How a message reads, as distinct from what it says.","m":"PS-02","h":"modules/ps02.html#glossary"},{"k":"term","t":"Escalation","s":"Involving somebody's manager. A real step, and rarely the second one.","m":"PS-02","h":"modules/ps02.html#glossary"},{"k":"term","t":"Reply all","s":"Sending to everyone on a thread. Appropriate only when all of them need it.","m":"PS-02","h":"modules/ps02.html#glossary"},{"k":"term","t":"Close","s":"The final line, where warmth belongs. It is read; the opening often is not.","m":"PS-02","h":"modules/ps02.html#glossary"},{"k":"term","t":"Ask","s":"The one action you need, with a date attached.","m":"PS-02","h":"modules/ps02.html#glossary"},{"k":"rule","t":"Delete the first sentence","s":"It almost always carries no information. Start with the point.","m":"PS-02","h":"modules/ps02.html#recap"},{"k":"rule","t":"Retire four phrases","s":"\"As per my previous\", \"do the needful\", \"revert\", \"urgent\" everywhere.","m":"PS-02","h":"modules/ps02.html#recap"},{"k":"rule","t":"Warmth goes at the end","s":"One line in the close does more than three in the opening.","m":"PS-02","h":"modules/ps02.html#recap"},{"k":"rule","t":"Dates instead of adverbs","s":"\"Due on the 8th\" lands harder than \"repeatedly delayed\".","m":"PS-02","h":"modules/ps02.html#recap"},{"k":"rule","t":"Never send angry","s":"Write it, wait thirty minutes, and change the three things you will spot.","m":"PS-02","h":"modules/ps02.html#recap"},{"k":"rule","t":"Reply-all almost never","s":"Only when the whole group is genuinely waiting on your answer.","m":"PS-02","h":"modules/ps02.html#recap"},{"k":"toolkit","t":"The neutral chaser","s":"Dates, no blame, one small request at the end.","m":"PS-02","h":"modules/ps02.html#toolkit"},{"k":"toolkit","t":"The de-escalation rewrite","s":"Removes blame and adverbs, keeps the meaning.","m":"PS-02","h":"modules/ps02.html#toolkit"},{"k":"toolkit","t":"The ten-second check","s":"Recipients, subject, one ask, forwardable.","m":"PS-02","h":"modules/ps02.html#toolkit"},{"k":"module","t":"English for the Workplace","s":"The handful of patterns that cause almost every misunderstanding at work — and how to sidestep them.","m":"PS-03","h":"modules/ps03.html"},{"k":"lesson","t":"One idea per sentence","s":"Long sentences are where meaning gets lost.","m":"PS-03","h":"modules/ps03.html#s_one"},{"k":"lesson","t":"The full-stop test","s":"","m":"PS-03","h":"modules/ps03.html#why"},{"k":"lesson","t":"Where the confusion lives","s":"","m":"PS-03","h":"modules/ps03.html#s_tense"},{"k":"lesson","t":"Add the time, remove the doubt","s":"When in doubt about tense, add the actual time.","m":"PS-03","h":"modules/ps03.html#why"},{"k":"lesson","t":"Six patterns that cost time","s":"","m":"PS-03","h":"modules/ps03.html#s_six"},{"k":"lesson","t":"The date format problem","s":"","m":"PS-03","h":"modules/ps03.html#why"},{"k":"lesson","t":"Short is not rude","s":"Politeness comes from what you offer, not from how many words you use to ask.","m":"PS-03","h":"modules/ps03.html#s_polite"},{"k":"lesson","t":"Three phrases that carry warmth","s":"","m":"PS-03","h":"modules/ps03.html#why"},{"k":"lesson","t":"Do this now: proofread one","s":"","m":"PS-03","h":"modules/ps03.html#s_do"},{"k":"lesson","t":"The one-minute proofread","s":"","m":"PS-03","h":"modules/ps03.html#why"},{"k":"lesson","t":"Using tools without losing yourself","s":"","m":"PS-03","h":"modules/ps03.html#why"},{"k":"lesson","t":"Confidence, not perfection","s":"","m":"PS-03","h":"modules/ps03.html#why"},{"k":"lesson","t":"The English rule","s":"","m":"PS-03","h":"modules/ps03.html#why"},{"k":"term","t":"Ambiguity","s":"A sentence with two possible meanings. The main cost of unclear writing at work.","m":"PS-03","h":"modules/ps03.html#glossary"},{"k":"term","t":"Tense","s":"How a verb shows time. Adding a clock time removes most tense problems entirely.","m":"PS-03","h":"modules/ps03.html#glossary"},{"k":"term","t":"Padding","s":"Extra words added for politeness that make the request harder to find.","m":"PS-03","h":"modules/ps03.html#glossary"},{"k":"term","t":"Register","s":"How formal a message is. Plain and warm travels better than heavy formality.","m":"PS-03","h":"modules/ps03.html#glossary"},{"k":"term","t":"Handover","s":"A note written for the person taking over.","m":"PS-03","h":"modules/ps03.html#glossary"},{"k":"term","t":"Article","s":"\"The\" and \"a\". Small words that make instructions read less abrupt.","m":"PS-03","h":"modules/ps03.html#glossary"},{"k":"rule","t":"One idea per sentence","s":"The fastest improvement available, and it costs nothing.","m":"PS-03","h":"modules/ps03.html#recap"},{"k":"rule","t":"Read it aloud","s":"If you needed a breath, split it at the \"and\" or the \"which\".","m":"PS-03","h":"modules/ps03.html#recap"},{"k":"rule","t":"Real times, not vague ones","s":"\"Since 6am\" removes an ambiguity that \"since morning\" creates.","m":"PS-03","h":"modules/ps03.html#recap"},{"k":"rule","t":"Spell the month","s":"03/04 means two different things across the offices we work in.","m":"PS-03","h":"modules/ps03.html#recap"},{"k":"rule","t":"Short is not rude","s":"Warmth comes from offering something, not from adding words.","m":"PS-03","h":"modules/ps03.html#recap"},{"k":"rule","t":"Clear beats correct","s":"A short sentence with a small slip beats a perfect one nobody can parse.","m":"PS-03","h":"modules/ps03.html#recap"},{"k":"toolkit","t":"The short-sentences rewrite","s":"One idea each, same meaning, no added formality.","m":"PS-03","h":"modules/ps03.html#toolkit"},{"k":"toolkit","t":"The one-minute proofread","s":"Long sentences, numeric dates, vague times, \"same\".","m":"PS-03","h":"modules/ps03.html#toolkit"},{"k":"toolkit","t":"Three warm closes","s":"Offer something instead of padding the opening.","m":"PS-03","h":"modules/ps03.html#toolkit"},{"k":"module","t":"Time Management","s":"Protecting the two hours a day where your real work actually gets done.","m":"PS-04","h":"modules/ps04.html"},{"k":"lesson","t":"Ten hours, nothing moved","s":"Reactive work fills any space you give it.","m":"PS-04","h":"modules/ps04.html#s_busy"},{"k":"lesson","t":"The honest end-of-day test","s":"","m":"PS-04","h":"modules/ps04.html#why"},{"k":"lesson","t":"Two hours, defended","s":"","m":"PS-04","h":"modules/ps04.html#s_block"},{"k":"lesson","t":"Two hours is enough","s":"","m":"PS-04","h":"modules/ps04.html#why"},{"k":"lesson","t":"Thirty seconds each","s":"The cost of an interruption is not the two minutes.","m":"PS-04","h":"modules/ps04.html#s_interrupt"},{"k":"lesson","t":"The interruption ledger","s":"","m":"PS-04","h":"modules/ps04.html#why"},{"k":"lesson","t":"Saying no without damage","s":"","m":"PS-04","h":"modules/ps04.html#s_no"},{"k":"lesson","t":"Make the trade visible","s":"","m":"PS-04","h":"modules/ps04.html#why"},{"k":"lesson","t":"Do this now: book tomorrow","s":"","m":"PS-04","h":"modules/ps04.html#s_do"},{"k":"lesson","t":"Four habits worth having","s":"","m":"PS-04","h":"modules/ps04.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PS-04","h":"modules/ps04.html#why"},{"k":"lesson","t":"The meeting you did not need","s":"","m":"PS-04","h":"modules/ps04.html#why"},{"k":"lesson","t":"The time management rule","s":"","m":"PS-04","h":"modules/ps04.html#why"},{"k":"term","t":"Reactive work","s":"Work that arrives and demands a response.","m":"PS-04","h":"modules/ps04.html#glossary"},{"k":"term","t":"Protected block","s":"Two hours booked in the calendar, with notifications off and one task decided.","m":"PS-04","h":"modules/ps04.html#glossary"},{"k":"term","t":"Context switching","s":"Moving between tasks. Costs roughly fifteen minutes of refocusing each time.","m":"PS-04","h":"modules/ps04.html#glossary"},{"k":"term","t":"Batching","s":"Holding several small requests and handling them together at one point in the day.","m":"PS-04","h":"modules/ps04.html#glossary"},{"k":"term","t":"The trade","s":"Offering a choice about what slips, rather than accepting silently or refusing.","m":"PS-04","h":"modules/ps04.html#glossary"},{"k":"term","t":"Deep work","s":"Work needing sustained concentration. It never feels urgent, and it is what gets remembered.","m":"PS-04","h":"modules/ps04.html#glossary"},{"k":"rule","t":"Busy is not productive","s":"Reactive work fills any space you leave and leaves no trace.","m":"PS-04","h":"modules/ps04.html#recap"},{"k":"rule","t":"Two hours, defended","s":"Same time daily, in the calendar, notifications off, one task.","m":"PS-04","h":"modules/ps04.html#recap"},{"k":"rule","t":"Decide the night before","s":"Choosing inside the block spends its freshest twenty minutes.","m":"PS-04","h":"modules/ps04.html#recap"},{"k":"rule","t":"Size the interruption","s":"\"Two minutes or twenty?\" Batch the twenties to one point.","m":"PS-04","h":"modules/ps04.html#recap"},{"k":"rule","t":"Trade, defer, redirect","s":"Almost nothing needs a flat no, and a flat no costs the most.","m":"PS-04","h":"modules/ps04.html#recap"},{"k":"rule","t":"Judge by what finished","s":"Not by hours worked, emails cleared, or how tired you feel.","m":"PS-04","h":"modules/ps04.html#recap"},{"k":"toolkit","t":"The interruption question","s":"\"Two-minute thing or twenty-minute thing?\"","m":"PS-04","h":"modules/ps04.html#toolkit"},{"k":"toolkit","t":"Three ways to say no","s":"Offer the trade, defer to Monday, redirect to the right team.","m":"PS-04","h":"modules/ps04.html#toolkit"},{"k":"toolkit","t":"The end-of-day test","s":"Name one thing that actually finished.","m":"PS-04","h":"modules/ps04.html#toolkit"},{"k":"module","t":"Productivity Systems","s":"A system simple enough that you will still be using it in March.","m":"PS-05","h":"modules/ps05.html"},{"k":"lesson","t":"Complexity, not discipline","s":"People blame themselves for abandoning a system.","m":"PS-05","h":"modules/ps05.html#s_fail"},{"k":"lesson","t":"The third-week test","s":"","m":"PS-05","h":"modules/ps05.html#why"},{"k":"lesson","t":"One place, always","s":"","m":"PS-05","h":"modules/ps05.html#s_capture"},{"k":"lesson","t":"Where commitments actually arrive","s":"","m":"PS-05","h":"modules/ps05.html#why"},{"k":"lesson","t":"Two minutes, daily","s":"A weekly review is a good idea that most people never do twice.","m":"PS-05","h":"modules/ps05.html#s_review"},{"k":"lesson","t":"Daily beats weekly","s":"","m":"PS-05","h":"modules/ps05.html#why"},{"k":"lesson","t":"Restarting without guilt","s":"","m":"PS-05","h":"modules/ps05.html#s_collapse"},{"k":"lesson","t":"The list is not the work","s":"","m":"PS-05","h":"modules/ps05.html#why"},{"k":"lesson","t":"Do this now: set the minimum","s":"","m":"PS-05","h":"modules/ps05.html#s_do"},{"k":"lesson","t":"What goes where","s":"","m":"PS-05","h":"modules/ps05.html#why"},{"k":"lesson","t":"Four habits worth having","s":"","m":"PS-05","h":"modules/ps05.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PS-05","h":"modules/ps05.html#why"},{"k":"lesson","t":"The productivity rule","s":"","m":"PS-05","h":"modules/ps05.html#why"},{"k":"term","t":"Capture","s":"Writing a commitment down the moment it is made, in under ten seconds.","m":"PS-05","h":"modules/ps05.html#glossary"},{"k":"term","t":"Daily review","s":"Four questions at the same point each day.","m":"PS-05","h":"modules/ps05.html#glossary"},{"k":"term","t":"Stale list","s":"A list nobody has opened for days. Restart from memory rather than reading it.","m":"PS-05","h":"modules/ps05.html#glossary"},{"k":"term","t":"Consequence","s":"What breaks if a task slips. A better sort order than urgency or date.","m":"PS-05","h":"modules/ps05.html#glossary"},{"k":"term","t":"Protected block","s":"Time booked in the calendar for work needing concentration.","m":"PS-05","h":"modules/ps05.html#glossary"},{"k":"term","t":"Inbox","s":"A list of other people's priorities, sorted by when they were sent.","m":"PS-05","h":"modules/ps05.html#glossary"},{"k":"rule","t":"Simplicity is the requirement","s":"The best system is the one still running in March, not the cleverest one.","m":"PS-05","h":"modules/ps05.html#recap"},{"k":"rule","t":"One place to capture","s":"Always with you, under ten seconds, no sorting at the moment of writing.","m":"PS-05","h":"modules/ps05.html#recap"},{"k":"rule","t":"Two minutes daily","s":"Four questions at the same point every day.","m":"PS-05","h":"modules/ps05.html#recap"},{"k":"rule","t":"Calendar for times, list for everything else","s":"If it has a clock on it, it belongs where the clock is.","m":"PS-05","h":"modules/ps05.html#recap"},{"k":"rule","t":"Restart from your head","s":"The live commitments are the ones you are already worrying about.","m":"PS-05","h":"modules/ps05.html#recap"},{"k":"rule","t":"Tidying is not working","s":"Organising the list is the most convincing procrastination there is.","m":"PS-05","h":"modules/ps05.html#recap"},{"k":"toolkit","t":"The four review questions","s":"Uncaptured, overdue, tomorrow's one thing, what to strike.","m":"PS-05","h":"modules/ps05.html#toolkit"},{"k":"toolkit","t":"The restart routine","s":"Five minutes from memory, then skim and delete.","m":"PS-05","h":"modules/ps05.html#toolkit"},{"k":"toolkit","t":"The where-does-it-go test","s":"Fixed time means calendar. Everything else means list.","m":"PS-05","h":"modules/ps05.html#toolkit"},{"k":"module","t":"Problem-Solving","s":"Finding the actual cause before you spend a fortnight fixing the wrong thing.","m":"PS-06","h":"modules/ps06.html"},{"k":"lesson","t":"Fixing what you can see","s":"The symptom is what interrupts you. The cause is usually somewhere quieter, and further back.","m":"PS-06","h":"modules/ps06.html#s_symptom"},{"k":"lesson","t":"The question nobody asks","s":"","m":"PS-06","h":"modules/ps06.html#why"},{"k":"lesson","t":"Five whys, ten minutes","s":"","m":"PS-06","h":"modules/ps06.html#s_why"},{"k":"lesson","t":"Where the chain goes wrong","s":"","m":"PS-06","h":"modules/ps06.html#why"},{"k":"lesson","t":"The cheap experiment first","s":"Before you spend money or a fortnight, find the smallest test that would prove you wrong.","m":"PS-06","h":"modules/ps06.html#s_test"},{"k":"lesson","t":"One day beats three repairs","s":"","m":"PS-06","h":"modules/ps06.html#why"},{"k":"lesson","t":"Analysis has a limit","s":"","m":"PS-06","h":"modules/ps06.html#s_stop"},{"k":"lesson","t":"Write it up so others can help","s":"","m":"PS-06","h":"modules/ps06.html#why"},{"k":"lesson","t":"Do this now: one real problem","s":"","m":"PS-06","h":"modules/ps06.html#s_do"},{"k":"lesson","t":"Four habits worth having","s":"","m":"PS-06","h":"modules/ps06.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PS-06","h":"modules/ps06.html#why"},{"k":"lesson","t":"Problems that are not technical","s":"","m":"PS-06","h":"modules/ps06.html#why"},{"k":"lesson","t":"The problem-solving rule","s":"","m":"PS-06","h":"modules/ps06.html#why"},{"k":"term","t":"Symptom","s":"What you notice when something is wrong. Usually not the thing to fix.","m":"PS-06","h":"modules/ps06.html#glossary"},{"k":"term","t":"Root cause","s":"The change that started it. Fixing this stops the problem returning.","m":"PS-06","h":"modules/ps06.html#glossary"},{"k":"term","t":"Five whys","s":"Asking why repeatedly, with a fact at each step, until you reach something changeable.","m":"PS-06","h":"modules/ps06.html#glossary"},{"k":"term","t":"Falsification","s":"Designing a test that would show you were wrong.","m":"PS-06","h":"modules/ps06.html#glossary"},{"k":"term","t":"Ruled out","s":"Something already tested and eliminated. Record it so nobody repeats it.","m":"PS-06","h":"modules/ps06.html#glossary"},{"k":"term","t":"Reversible","s":"A change you can undo cheaply. Reversible fixes make good experiments.","m":"PS-06","h":"modules/ps06.html#glossary"},{"k":"rule","t":"Symptom is not cause","s":"The symptom interrupts you. The cause is quieter and further back.","m":"PS-06","h":"modules/ps06.html#recap"},{"k":"rule","t":"Ask when it started","s":"Then ask what changed around that date. Most causes live there.","m":"PS-06","h":"modules/ps06.html#recap"},{"k":"rule","t":"Five whys, written down","s":"Chains kept in your head skip links. Each answer must be a fact.","m":"PS-06","h":"modules/ps06.html#recap"},{"k":"rule","t":"Never stop at human error","s":"Ask why it was possible, and why nothing downstream caught it.","m":"PS-06","h":"modules/ps06.html#recap"},{"k":"rule","t":"Test to be proved wrong","s":"One shift with the old film beats three replacement parts.","m":"PS-06","h":"modules/ps06.html#recap"},{"k":"rule","t":"Write down what you ruled out","s":"Otherwise three colleagues test the same thing over two months.","m":"PS-06","h":"modules/ps06.html#recap"},{"k":"toolkit","t":"The five whys chain","s":"Each answer a fact, stopping at something you can change.","m":"PS-06","h":"modules/ps06.html#toolkit"},{"k":"toolkit","t":"The five-line write-up","s":"Problem, started, changed then, ruled out, next test.","m":"PS-06","h":"modules/ps06.html#toolkit"},{"k":"toolkit","t":"The cheap experiment","s":"Reverse, isolate, compare, check the timeline.","m":"PS-06","h":"modules/ps06.html#toolkit"},{"k":"module","t":"Critical Thinking","s":"Telling evidence from assertion — including in your own reasoning, which is the harder half.","m":"PS-07","h":"modules/ps07.html"},{"k":"lesson","t":"Three questions, every claim","s":"Most workplace claims are true, unchecked, or true once and never re-examined.","m":"PS-07","h":"modules/ps07.html#s_fact"},{"k":"lesson","t":"How a number becomes a fact","s":"","m":"PS-07","h":"modules/ps07.html#why"},{"k":"lesson","t":"Asking without friction","s":"","m":"PS-07","h":"modules/ps07.html#s_numbers"},{"k":"lesson","t":"Three kinds of number","s":"","m":"PS-07","h":"modules/ps07.html#why"},{"k":"lesson","t":"The two that matter at work","s":"","m":"PS-07","h":"modules/ps07.html#s_bias"},{"k":"lesson","t":"Deciding in advance","s":"","m":"PS-07","h":"modules/ps07.html#why"},{"k":"lesson","t":"Like with like","s":"","m":"PS-07","h":"modules/ps07.html#s_compare"},{"k":"lesson","t":"The four checks","s":"","m":"PS-07","h":"modules/ps07.html#why"},{"k":"lesson","t":"Do this now: test one claim","s":"","m":"PS-07","h":"modules/ps07.html#s_do"},{"k":"lesson","t":"Disagreeing well","s":"","m":"PS-07","h":"modules/ps07.html#why"},{"k":"lesson","t":"Four habits worth having","s":"","m":"PS-07","h":"modules/ps07.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PS-07","h":"modules/ps07.html#why"},{"k":"lesson","t":"When to stop questioning","s":"","m":"PS-07","h":"modules/ps07.html#why"},{"k":"lesson","t":"The critical thinking rule","s":"","m":"PS-07","h":"modules/ps07.html#why"},{"k":"term","t":"Assertion","s":"A claim stated without evidence. Often true, and not yet demonstrated.","m":"PS-07","h":"modules/ps07.html#glossary"},{"k":"term","t":"Confirmation bias","s":"Noticing evidence that fits your view and not registering the rest.","m":"PS-07","h":"modules/ps07.html#glossary"},{"k":"term","t":"Recency bias","s":"Treating the most recent event as a trend, and quiet periods as nothing.","m":"PS-07","h":"modules/ps07.html#glossary"},{"k":"term","t":"Like-for-like","s":"A comparison where period, definition and scope are all the same.","m":"PS-07","h":"modules/ps07.html#glossary"},{"k":"term","t":"Folklore","s":"A number everybody repeats that nobody can trace to a source.","m":"PS-07","h":"modules/ps07.html#glossary"},{"k":"term","t":"Falsification","s":"Deciding in advance what evidence would show you are wrong.","m":"PS-07","h":"modules/ps07.html#glossary"},{"k":"rule","t":"Three questions, every claim","s":"Where from, when true, and what would change my mind.","m":"PS-07","h":"modules/ps07.html#recap"},{"k":"rule","t":"Hedges vanish in writing","s":"\"About eight, I think\" becomes 8% two documents later.","m":"PS-07","h":"modules/ps07.html#recap"},{"k":"rule","t":"Decide the test before you look","s":"It is the only reliable protection against finding what you expected.","m":"PS-07","h":"modules/ps07.html#recap"},{"k":"rule","t":"Check like with like","s":"Same period length, same definition, same scope, rate or total.","m":"PS-07","h":"modules/ps07.html#recap"},{"k":"rule","t":"Question reasoning, not people","s":"\"I might be missing something\" costs nothing and keeps everyone working.","m":"PS-07","h":"modules/ps07.html#recap"},{"k":"rule","t":"Precision has a price","s":"If the decision would not change, note it as approximate and move on.","m":"PS-07","h":"modules/ps07.html#recap"},{"k":"toolkit","t":"The three claim questions","s":"Source, date, and what would change your mind.","m":"PS-07","h":"modules/ps07.html#toolkit"},{"k":"toolkit","t":"The low-friction challenge","s":"\"I might be missing something — can I check one thing?\"","m":"PS-07","h":"modules/ps07.html#toolkit"},{"k":"toolkit","t":"The four comparison checks","s":"Period, definition, scope, rate or total.","m":"PS-07","h":"modules/ps07.html#toolkit"},{"k":"module","t":"Presentation Skills","s":"Standing up and saying it — including when you are interrupted on slide three.","m":"PS-08","h":"modules/ps08.html"},{"k":"lesson","t":"Point first, evidence second","s":"If people do not know what a slide is for, they read it instead of listening to you.","m":"PS-08","h":"modules/ps08.html#s_point"},{"k":"lesson","t":"Never read the slide","s":"","m":"PS-08","h":"modules/ps08.html#why"},{"k":"lesson","t":"You get one opening","s":"","m":"PS-08","h":"modules/ps08.html#s_open"},{"k":"lesson","t":"What not to open with","s":"","m":"PS-08","h":"modules/ps08.html#why"},{"k":"lesson","t":"Interruptions are normal","s":"Being stopped on slide three usually means somebody is engaged.","m":"PS-08","h":"modules/ps08.html#s_interrupt"},{"k":"lesson","t":"Finding your place again","s":"","m":"PS-08","h":"modules/ps08.html#why"},{"k":"lesson","t":"Three honest options","s":"","m":"PS-08","h":"modules/ps08.html#s_dontknow"},{"k":"lesson","t":"The commitment matters","s":"","m":"PS-08","h":"modules/ps08.html#why"},{"k":"lesson","t":"Do this now: rehearse one opening","s":"","m":"PS-08","h":"modules/ps08.html#s_do"},{"k":"lesson","t":"Finishing early is a gift","s":"","m":"PS-08","h":"modules/ps08.html#why"},{"k":"lesson","t":"Four habits worth having","s":"","m":"PS-08","h":"modules/ps08.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PS-08","h":"modules/ps08.html#why"},{"k":"lesson","t":"Nerves are not the problem","s":"","m":"PS-08","h":"modules/ps08.html#why"},{"k":"lesson","t":"The presentation rule","s":"","m":"PS-08","h":"modules/ps08.html#why"},{"k":"term","t":"Point-first","s":"Stating what a slide means before showing its detail.","m":"PS-08","h":"modules/ps08.html#glossary"},{"k":"term","t":"Signposting","s":"Telling the room where you are, especially after an interruption.","m":"PS-08","h":"modules/ps08.html#glossary"},{"k":"term","t":"Parking","s":"Agreeing to take a question outside the meeting, with a date attached.","m":"PS-08","h":"modules/ps08.html#glossary"},{"k":"term","t":"Appendix","s":"Slides kept after the end for questions you might be asked.","m":"PS-08","h":"modules/ps08.html#glossary"},{"k":"term","t":"Opening","s":"The first thirty seconds. The only moment you have everybody's attention.","m":"PS-08","h":"modules/ps08.html#glossary"},{"k":"term","t":"Overrun","s":"Going past the finish time. It costs the decision you came for.","m":"PS-08","h":"modules/ps08.html#glossary"},{"k":"rule","t":"Point before evidence","s":"Tell them what a slide means before they build their own view of it.","m":"PS-08","h":"modules/ps08.html#recap"},{"k":"rule","t":"Never read the slide","s":"They read faster than you speak. Say what is not written on it.","m":"PS-08","h":"modules/ps08.html#recap"},{"k":"rule","t":"Three numbered things","s":"Plus the decision you need, in the first thirty seconds.","m":"PS-08","h":"modules/ps08.html#recap"},{"k":"rule","t":"Answer, then signpost","s":"Deal with the interruption, then name where you are again.","m":"PS-08","h":"modules/ps08.html#recap"},{"k":"rule","t":"Never guess a number","s":"\"I would rather not guess — I will confirm by Thursday.\"","m":"PS-08","h":"modules/ps08.html#recap"},{"k":"rule","t":"Stop when you have the decision","s":"Finishing early is remembered far more warmly than finishing everything.","m":"PS-08","h":"modules/ps08.html#recap"},{"k":"toolkit","t":"The thirty-second opening","s":"Three numbered things and the decision you need.","m":"PS-08","h":"modules/ps08.html#toolkit"},{"k":"toolkit","t":"The interruption move","s":"One-sentence answer, then name where you are.","m":"PS-08","h":"modules/ps08.html#toolkit"},{"k":"toolkit","t":"The honest non-answer","s":"\"I would rather not guess. Thursday.\" Then write it down.","m":"PS-08","h":"modules/ps08.html#toolkit"},{"k":"module","t":"Teamwork & Collaboration","s":"Handing work over so it arrives finished, and asking for help without friction.","m":"PS-09","h":"modules/ps09.html"},{"k":"lesson","t":"Four lines, no questions","s":"Most handover friction is not disagreement.","m":"PS-09","h":"modules/ps09.html#s_handover"},{"k":"lesson","t":"The same job, two ways","s":"","m":"PS-09","h":"modules/ps09.html#why"},{"k":"lesson","t":"\"Done\" is the failure point","s":"Two people can both be right about whether something is finished, and disagree completely.","m":"PS-09","h":"modules/ps09.html#s_done"},{"k":"lesson","t":"Say what done looks like","s":"","m":"PS-09","h":"modules/ps09.html#why"},{"k":"lesson","t":"Getting a fast answer","s":"","m":"PS-09","h":"modules/ps09.html#s_help"},{"k":"lesson","t":"The three-line ask","s":"","m":"PS-09","h":"modules/ps09.html#why"},{"k":"lesson","t":"Without a confrontation","s":"Most cross-team problems are process problems that look like people problems.","m":"PS-09","h":"modules/ps09.html#s_problem"},{"k":"lesson","t":"Where to raise it","s":"","m":"PS-09","h":"modules/ps09.html#why"},{"k":"lesson","t":"Do this now: rewrite one handover","s":"","m":"PS-09","h":"modules/ps09.html#s_do"},{"k":"lesson","t":"Feedback that changes something","s":"","m":"PS-09","h":"modules/ps09.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"PS-09","h":"modules/ps09.html#why"},{"k":"lesson","t":"Working across sites","s":"","m":"PS-09","h":"modules/ps09.html#why"},{"k":"lesson","t":"The collaboration rule","s":"","m":"PS-09","h":"modules/ps09.html#why"},{"k":"term","t":"Handover","s":"Passing work to somebody else. Needs four lines, not a file and two words.","m":"PS-09","h":"modules/ps09.html#glossary"},{"k":"term","t":"Definition of done","s":"What the finished output looks like, stated before anyone starts.","m":"PS-09","h":"modules/ps09.html#glossary"},{"k":"term","t":"Escalation","s":"Involving managers. Appropriate for a repeated pattern, not a first occurrence.","m":"PS-09","h":"modules/ps09.html#glossary"},{"k":"term","t":"Blocker","s":"Something stopping progress. Should reach a named person within hours, not days.","m":"PS-09","h":"modules/ps09.html#glossary"},{"k":"term","t":"Feedback","s":"One specific thing, its effect, and what you would like instead.","m":"PS-09","h":"modules/ps09.html#glossary"},{"k":"term","t":"Buffer","s":"Extra time added to absorb delays. Useful, and it hides the problem if used instead of fixing it.","m":"PS-09","h":"modules/ps09.html#glossary"},{"k":"rule","t":"Four lines with every handover","s":"What, done means, by when, and who to ask if stuck.","m":"PS-09","h":"modules/ps09.html#recap"},{"k":"rule","t":"Define done explicitly","s":"\"Ready to send without me editing it\" removes the whole ambiguity.","m":"PS-09","h":"modules/ps09.html#recap"},{"k":"rule","t":"Give a time, not a day","s":"\"Wednesday 3pm\" starts work on Tuesday. \"Wednesday\" starts it on Wednesday.","m":"PS-09","h":"modules/ps09.html#recap"},{"k":"rule","t":"Name one person to ask","s":"\"Ask Priya\" beats \"ask the team\", which means asking nobody.","m":"PS-09","h":"modules/ps09.html#recap"},{"k":"rule","t":"Say what you already tried","s":"It is the difference between a two-minute answer and a ten-minute one.","m":"PS-09","h":"modules/ps09.html#recap"},{"k":"rule","t":"Raise patterns, not people","s":"The fourth late delivery is a process fault.","m":"PS-09","h":"modules/ps09.html#recap"},{"k":"toolkit","t":"The four-line handover","s":"What, done means, by when, if stuck.","m":"PS-09","h":"modules/ps09.html#toolkit"},{"k":"toolkit","t":"The three-line ask for help","s":"Problem, what you tried, specific question, time needed.","m":"PS-09","h":"modules/ps09.html#toolkit"},{"k":"toolkit","t":"The no-blame problem raise","s":"The dates, blame removed, an offer to look together.","m":"PS-09","h":"modules/ps09.html#toolkit"},{"k":"module","t":"Password Security","s":"Why one reused password is the most likely way this company gets broken into.","m":"SEC-01","h":"modules/sec01.html"},{"k":"lesson","t":"Nobody sits and guesses","s":"The film version is somebody typing guesses.","m":"SEC-01","h":"modules/sec01.html#s_how"},{"k":"lesson","t":"What actually gets used","s":"","m":"SEC-01","h":"modules/sec01.html#why"},{"k":"lesson","t":"One breach, every account","s":"","m":"SEC-01","h":"modules/sec01.html#s_reuse"},{"k":"lesson","t":"Small changes do not help","s":"","m":"SEC-01","h":"modules/sec01.html#why"},{"k":"lesson","t":"Length beats symbols","s":"Three or four unrelated words are harder to break and far easier to type than eight random characters.","m":"SEC-01","h":"modules/sec01.html#s_build"},{"k":"lesson","t":"Weak, medium, strong","s":"","m":"SEC-01","h":"modules/sec01.html#why"},{"k":"lesson","t":"Stop trying to remember","s":"","m":"SEC-01","h":"modules/sec01.html#s_manager"},{"k":"lesson","t":"Where passwords must never live","s":"","m":"SEC-01","h":"modules/sec01.html#why"},{"k":"lesson","t":"Do this now: check and change","s":"","m":"SEC-01","h":"modules/sec01.html#s_do"},{"k":"lesson","t":"If a password is exposed","s":"","m":"SEC-01","h":"modules/sec01.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"SEC-01","h":"modules/sec01.html#why"},{"k":"lesson","t":"Sharing an account is never fine","s":"","m":"SEC-01","h":"modules/sec01.html#why"},{"k":"lesson","t":"Four habits worth having","s":"","m":"SEC-01","h":"modules/sec01.html#why"},{"k":"lesson","t":"The password rule","s":"","m":"SEC-01","h":"modules/sec01.html#why"},{"k":"term","t":"Credential stuffing","s":"Trying leaked email and password pairs automatically against many services at once.","m":"SEC-01","h":"modules/sec01.html#glossary"},{"k":"term","t":"Breach","s":"A site losing its user list, usually including email addresses and passwords.","m":"SEC-01","h":"modules/sec01.html#glossary"},{"k":"term","t":"Passphrase","s":"A password made of several unrelated words.","m":"SEC-01","h":"modules/sec01.html#glossary"},{"k":"term","t":"Password manager","s":"Software that stores a unique password for every account, behind one phrase you learn.","m":"SEC-01","h":"modules/sec01.html#glossary"},{"k":"term","t":"Shared account","s":"One login used by several people. It destroys any record of who did what.","m":"SEC-01","h":"modules/sec01.html#glossary"},{"k":"term","t":"Multi-factor","s":"A second proof of identity beyond the password.","m":"SEC-01","h":"modules/sec01.html#glossary"},{"k":"rule","t":"Nobody guesses","s":"They use passwords that already leaked from other sites, tried automatically.","m":"SEC-01","h":"modules/sec01.html#recap"},{"k":"rule","t":"Reuse is the whole risk","s":"Your work account is as safe as the least careful site you ever joined.","m":"SEC-01","h":"modules/sec01.html#recap"},{"k":"rule","t":"Length beats symbols","s":"Four unrelated words beat eight clever characters, every time.","m":"SEC-01","h":"modules/sec01.html#recap"},{"k":"rule","t":"Small changes are not changes","s":"Adding a digit or swapping a letter is the first thing attackers try.","m":"SEC-01","h":"modules/sec01.html#recap"},{"k":"rule","t":"Let software remember","s":"One phrase you learn, and a unique password for everything else.","m":"SEC-01","h":"modules/sec01.html#recap"},{"k":"rule","t":"Never share a login","s":"Their actions become your record, and you cannot prove otherwise.","m":"SEC-01","h":"modules/sec01.html#recap"},{"k":"toolkit","t":"The passphrase generator prompt","s":"Eight four-word phrases, no names, no dates.","m":"SEC-01","h":"modules/sec01.html#toolkit"},{"k":"toolkit","t":"The breach check","s":"Type your address and see which leaks included it.","m":"SEC-01","h":"modules/sec01.html#toolkit"},{"k":"toolkit","t":"The exposure checklist","s":"Change work first, report the same day, check your rules.","m":"SEC-01","h":"modules/sec01.html#toolkit"},{"k":"module","t":"Phishing & Social Engineering","s":"How people get talked into handing over the password, the payment or the file — and the pause that stops it.","m":"SEC-02","h":"modules/sec02.html"},{"k":"lesson","t":"They do not look wrong any more","s":"The badly spelled email is twenty years out of date.","m":"SEC-02","h":"modules/sec02.html#s_look"},{"k":"lesson","t":"A sender name proves nothing","s":"","m":"SEC-02","h":"modules/sec02.html#why"},{"k":"lesson","t":"Four signals in every attack","s":"Attacks do not need you to be careless. They need you to be busy and to feel pushed.","m":"SEC-02","h":"modules/sec02.html#s_signals"},{"k":"lesson","t":"Two together is enough to stop","s":"","m":"SEC-02","h":"modules/sec02.html#why"},{"k":"lesson","t":"One call, a number you had","s":"","m":"SEC-02","h":"modules/sec02.html#s_verify"},{"k":"lesson","t":"The wording, ready to use","s":"","m":"SEC-02","h":"modules/sec02.html#why"},{"k":"lesson","t":"Not only email","s":"","m":"SEC-02","h":"modules/sec02.html#s_channels"},{"k":"lesson","t":"The code that is never shared","s":"","m":"SEC-02","h":"modules/sec02.html#why"},{"k":"lesson","t":"Do this now: test one message","s":"","m":"SEC-02","h":"modules/sec02.html#s_do"},{"k":"lesson","t":"If you already clicked","s":"","m":"SEC-02","h":"modules/sec02.html#why"},{"k":"lesson","t":"Reporting a false alarm is free","s":"","m":"SEC-02","h":"modules/sec02.html#why"},{"k":"lesson","t":"Why smart people get caught","s":"","m":"SEC-02","h":"modules/sec02.html#why"},{"k":"lesson","t":"The phishing rule","s":"","m":"SEC-02","h":"modules/sec02.html#why"},{"k":"term","t":"Phishing","s":"A message designed to make you hand over access, money or a document.","m":"SEC-02","h":"modules/sec02.html#glossary"},{"k":"term","t":"Social engineering","s":"Manipulating a person rather than attacking a system.","m":"SEC-02","h":"modules/sec02.html#glossary"},{"k":"term","t":"Spoofing","s":"Making a message appear to come from somebody else.","m":"SEC-02","h":"modules/sec02.html#glossary"},{"k":"term","t":"Business email compromise","s":"An attacker using a real or lookalike account to redirect a payment.","m":"SEC-02","h":"modules/sec02.html#glossary"},{"k":"term","t":"One-time code","s":"A short code proving it is you. Never shared with anyone, for any reason.","m":"SEC-02","h":"modules/sec02.html#glossary"},{"k":"term","t":"Out-of-band","s":"Checking through a different channel the sender does not control.","m":"SEC-02","h":"modules/sec02.html#glossary"},{"k":"rule","t":"They do not look wrong","s":"Perfect English, real logos, your order number.","m":"SEC-02","h":"modules/sec02.html#recap"},{"k":"rule","t":"Four pressure signals","s":"Urgency, authority, secrecy, a change. Any two means stop.","m":"SEC-02","h":"modules/sec02.html#recap"},{"k":"rule","t":"Verify outside the channel","s":"A number you already had, not one from the message.","m":"SEC-02","h":"modules/sec02.html#recap"},{"k":"rule","t":"Never a one-time code","s":"Nobody legitimate asks. There is genuinely no exception.","m":"SEC-02","h":"modules/sec02.html#recap"},{"k":"rule","t":"If you clicked, disconnect and report","s":"Leave it powered on, change the password elsewhere, report within the hour.","m":"SEC-02","h":"modules/sec02.html#recap"},{"k":"rule","t":"Report false alarms too","s":"It reached your colleagues as well, and some of them are busier.","m":"SEC-02","h":"modules/sec02.html#recap"},{"k":"toolkit","t":"The verification call wording","s":"Confirms directly, on a number you already had.","m":"SEC-02","h":"modules/sec02.html#toolkit"},{"k":"toolkit","t":"The four-signal check","s":"Urgency, authority, secrecy, a change. Count them.","m":"SEC-02","h":"modules/sec02.html#toolkit"},{"k":"toolkit","t":"The first-hour checklist","s":"Disconnect, change elsewhere, report within the hour.","m":"SEC-02","h":"modules/sec02.html#toolkit"},{"k":"module","t":"Multi-Factor Authentication","s":"The second lock that makes a stolen password almost useless — and the one way people still get past it.","m":"SEC-03","h":"modules/sec03.html"},{"k":"lesson","t":"Something you know, something you have","s":"A password is something you know. It can be stolen without you noticing. A second factor is something you…","m":"SEC-03","h":"modules/sec03.html#s_what"},{"k":"lesson","t":"Why it matters so much","s":"","m":"SEC-03","h":"modules/sec03.html#why"},{"k":"lesson","t":"Not all factors are equal","s":"","m":"SEC-03","h":"modules/sec03.html#s_types"},{"k":"lesson","t":"Any factor beats none","s":"","m":"SEC-03","h":"modules/sec03.html#why"},{"k":"lesson","t":"The one way past it","s":"If they have your password, they can trigger approval prompts on your phone.","m":"SEC-03","h":"modules/sec03.html#s_fatigue"},{"k":"lesson","t":"What to do instead","s":"","m":"SEC-03","h":"modules/sec03.html#why"},{"k":"lesson","t":"The report wording","s":"","m":"SEC-03","h":"modules/sec03.html#why"},{"k":"lesson","t":"Before you lose the phone","s":"","m":"SEC-03","h":"modules/sec03.html#s_lost"},{"k":"lesson","t":"If it is lost or stolen","s":"","m":"SEC-03","h":"modules/sec03.html#why"},{"k":"lesson","t":"Do this now: check your setup","s":"","m":"SEC-03","h":"modules/sec03.html#s_do"},{"k":"lesson","t":"Four habits worth having","s":"","m":"SEC-03","h":"modules/sec03.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"SEC-03","h":"modules/sec03.html#why"},{"k":"lesson","t":"An unexpected prompt means what?","s":"","m":"SEC-03","h":"modules/sec03.html#why"},{"k":"lesson","t":"The MFA rule","s":"","m":"SEC-03","h":"modules/sec03.html#why"},{"k":"term","t":"Multi-factor authentication","s":"Proving who you are with two different kinds of thing: something you know and something you have.","m":"SEC-03","h":"modules/sec03.html#glossary"},{"k":"term","t":"Authenticator app","s":"An app showing a rotating code, tied to the device rather than to a phone number.","m":"SEC-03","h":"modules/sec03.html#glossary"},{"k":"term","t":"Passkey","s":"A modern factor tied to the real website address, so it cannot be used on a fake page.","m":"SEC-03","h":"modules/sec03.html#glossary"},{"k":"term","t":"MFA fatigue","s":"Flooding you with approval prompts until you tap one to stop the noise.","m":"SEC-03","h":"modules/sec03.html#glossary"},{"k":"term","t":"Backup codes","s":"One-time codes for when you lose your phone.","m":"SEC-03","h":"modules/sec03.html#glossary"},{"k":"term","t":"One-time code","s":"A short code proving it is you. Never shared with anyone, for any reason.","m":"SEC-03","h":"modules/sec03.html#glossary"},{"k":"rule","t":"Something you have","s":"A password can leak. The phone in your pocket cannot leak with it.","m":"SEC-03","h":"modules/sec03.html#recap"},{"k":"rule","t":"Pick the strongest offered","s":"Passkey or security key, then an authenticator app, then SMS.","m":"SEC-03","h":"modules/sec03.html#recap"},{"k":"rule","t":"Any factor beats none","s":"Even a texted code defeats an attacker holding only your password.","m":"SEC-03","h":"modules/sec03.html#recap"},{"k":"rule","t":"Approve only what you started","s":"An unexpected prompt means somebody already has your password.","m":"SEC-03","h":"modules/sec03.html#recap"},{"k":"rule","t":"Never read a code aloud","s":"There is no legitimate reason for anyone to ask for it.","m":"SEC-03","h":"modules/sec03.html#recap"},{"k":"rule","t":"Keep backup codes elsewhere","s":"Not on the phone they exist to replace.","m":"SEC-03","h":"modules/sec03.html#recap"},{"k":"toolkit","t":"The fatigue-attack report","s":"Denied, password changed elsewhere, time window given.","m":"SEC-03","h":"modules/sec03.html#toolkit"},{"k":"toolkit","t":"The lost-phone message","s":"Reset registration and check sign-ins since a stated time.","m":"SEC-03","h":"modules/sec03.html#toolkit"},{"k":"toolkit","t":"The approve-or-deny test","s":"Did I start this in the last minute? If not, deny.","m":"SEC-03","h":"modules/sec03.html#toolkit"},{"k":"module","t":"Data Protection Basics","s":"What counts as personal data, what the law expects, and what that means for your inbox on an ordinary Tuesday.","m":"SEC-04","h":"modules/sec04.html"},{"k":"lesson","t":"Wider than most people think","s":"If it points to one identifiable person, it is personal data.","m":"SEC-04","h":"modules/sec04.html#s_what"},{"k":"lesson","t":"Two laws, one habit","s":"","m":"SEC-04","h":"modules/sec04.html#why"},{"k":"lesson","t":"Four rules, most decisions","s":"","m":"SEC-04","h":"modules/sec04.html#s_rules"},{"k":"lesson","t":"Collect less is the strongest","s":"","m":"SEC-04","h":"modules/sec04.html#why"},{"k":"lesson","t":"No attacker required","s":"","m":"SEC-04","h":"modules/sec04.html#s_everyday"},{"k":"lesson","t":"The BCC habit","s":"","m":"SEC-04","h":"modules/sec04.html#why"},{"k":"lesson","t":"The clock starts when you know","s":"Notification deadlines are measured from the moment somebody in the company becomes aware.","m":"SEC-04","h":"modules/sec04.html#s_wrong"},{"k":"lesson","t":"The report, ready to send","s":"","m":"SEC-04","h":"modules/sec04.html#why"},{"k":"lesson","t":"Do this now: audit your inbox","s":"","m":"SEC-04","h":"modules/sec04.html#s_do"},{"k":"lesson","t":"When a customer asks what we hold","s":"","m":"SEC-04","h":"modules/sec04.html#why"},{"k":"lesson","t":"Where data is allowed to live","s":"","m":"SEC-04","h":"modules/sec04.html#why"},{"k":"lesson","t":"Four habits worth having","s":"","m":"SEC-04","h":"modules/sec04.html#why"},{"k":"lesson","t":"The data protection rule","s":"","m":"SEC-04","h":"modules/sec04.html#why"},{"k":"term","t":"Personal data","s":"Any information pointing to one identifiable person, with or without a name attached.","m":"SEC-04","h":"modules/sec04.html#glossary"},{"k":"term","t":"DPDP Act","s":"India's Digital Personal Data Protection Act, covering consent, purpose and breach notification.","m":"SEC-04","h":"modules/sec04.html#glossary"},{"k":"term","t":"Data minimisation","s":"Collecting only what you actually need. The strongest protection available.","m":"SEC-04","h":"modules/sec04.html#glossary"},{"k":"term","t":"Data breach","s":"Personal data going somewhere it should not.","m":"SEC-04","h":"modules/sec04.html#glossary"},{"k":"term","t":"Subject access request","s":"A person asking what data we hold about them.","m":"SEC-04","h":"modules/sec04.html#glossary"},{"k":"term","t":"Retention","s":"How long we keep something. Old copies are the ones that cause incidents.","m":"SEC-04","h":"modules/sec04.html#glossary"},{"k":"rule","t":"Personal data is wider than names","s":"Number plates, photos, employee numbers and addresses all count.","m":"SEC-04","h":"modules/sec04.html#recap"},{"k":"rule","t":"Collect less","s":"The only perfect protection. A field you never asked for cannot leak.","m":"SEC-04","h":"modules/sec04.html#recap"},{"k":"rule","t":"Keep it inside","s":"Company systems only. Never personal email, USB sticks or chat windows.","m":"SEC-04","h":"modules/sec04.html#recap"},{"k":"rule","t":"Delete when done","s":"Old copies from finished projects are what leak years later.","m":"SEC-04","h":"modules/sec04.html#recap"},{"k":"rule","t":"BCC, always","s":"One CC field exposes every customer address to every other customer.","m":"SEC-04","h":"modules/sec04.html#recap"},{"k":"rule","t":"Report the day you know","s":"The clock starts on awareness, not on harm.","m":"SEC-04","h":"modules/sec04.html#recap"},{"k":"toolkit","t":"The incident report wording","s":"What, when, how many, who knows, nothing deleted.","m":"SEC-04","h":"modules/sec04.html#toolkit"},{"k":"toolkit","t":"The four handling rules","s":"Collect less, stated purpose, keep inside, delete when done.","m":"SEC-04","h":"modules/sec04.html#toolkit"},{"k":"toolkit","t":"The inbox audit","s":"Sent items, personal email, old spreadsheets.","m":"SEC-04","h":"modules/sec04.html#toolkit"},{"k":"module","t":"Handling Confidential Information","s":"The commercial material that is not personal data, and still must never leave the building.","m":"SEC-05","h":"modules/sec05.html"},{"k":"lesson","t":"Four classes, few seconds","s":"Most companies use some version of this. The names matter less than the habit of asking.","m":"SEC-05","h":"modules/sec05.html#s_classes"},{"k":"lesson","t":"Restricted means inside too","s":"","m":"SEC-05","h":"modules/sec05.html#why"},{"k":"lesson","t":"It hides in reused files","s":"","m":"SEC-05","h":"modules/sec05.html#s_hides"},{"k":"lesson","t":"Check before it leaves","s":"","m":"SEC-05","h":"modules/sec05.html#why"},{"k":"lesson","t":"Need to know, not nice to know","s":"","m":"SEC-05","h":"modules/sec05.html#s_share"},{"k":"lesson","t":"The extract habit","s":"","m":"SEC-05","h":"modules/sec05.html#why"},{"k":"lesson","t":"Colleagues are not automatic","s":"Being employed here is not the same as needing to know.","m":"SEC-05","h":"modules/sec05.html#s_inside"},{"k":"lesson","t":"Saying no without friction","s":"","m":"SEC-05","h":"modules/sec05.html#why"},{"k":"lesson","t":"Do this now: classify five","s":"","m":"SEC-05","h":"modules/sec05.html#s_do"},{"k":"lesson","t":"What never leaves, ever","s":"","m":"SEC-05","h":"modules/sec05.html#why"},{"k":"lesson","t":"Marking things properly","s":"","m":"SEC-05","h":"modules/sec05.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"SEC-05","h":"modules/sec05.html#why"},{"k":"lesson","t":"The confidentiality rule","s":"","m":"SEC-05","h":"modules/sec05.html#why"},{"k":"term","t":"Classification","s":"Deciding which of the four classes a document belongs to, and who may open it.","m":"SEC-05","h":"modules/sec05.html#glossary"},{"k":"term","t":"Need to know","s":"The test for sharing: does this person require it for work they are actually doing?","m":"SEC-05","h":"modules/sec05.html#glossary"},{"k":"term","t":"Restricted","s":"Material limited to a named few, including inside the company.","m":"SEC-05","h":"modules/sec05.html#glossary"},{"k":"term","t":"Extract","s":"A fresh document containing only the part somebody actually needs.","m":"SEC-05","h":"modules/sec05.html#glossary"},{"k":"term","t":"Metadata","s":"Information about a file: its name, author, comments and tracked changes.","m":"SEC-05","h":"modules/sec05.html#glossary"},{"k":"term","t":"Confidential","s":"Damaging if it leaves the company, even though no individual is identifiable.","m":"SEC-05","h":"modules/sec05.html#glossary"},{"k":"rule","t":"Four classes","s":"Public, internal, confidential, restricted.","m":"SEC-05","h":"modules/sec05.html#recap"},{"k":"rule","t":"Restricted excludes most colleagues","s":"Salaries, legal matters and unannounced plans are not department-wide.","m":"SEC-05","h":"modules/sec05.html#recap"},{"k":"rule","t":"It hides in reused files","s":"Extra slides, hidden columns, tracked changes, file names, whiteboard photos.","m":"SEC-05","h":"modules/sec05.html#recap"},{"k":"rule","t":"Send the answer, not the file","s":"Extracting three lines takes two minutes and reveals nothing else.","m":"SEC-05","h":"modules/sec05.html#recap"},{"k":"rule","t":"Employment is not need-to-know","s":"Redirect to the owner rather than refusing.","m":"SEC-05","h":"modules/sec05.html#recap"},{"k":"rule","t":"Do not mark everything","s":"When every file is confidential, the label stops meaning anything.","m":"SEC-05","h":"modules/sec05.html#recap"},{"k":"toolkit","t":"The extract wording","s":"Says yes, explains why, commits to a time.","m":"SEC-05","h":"modules/sec05.html#toolkit"},{"k":"toolkit","t":"The internal redirect","s":"Points at the owner without refusing anything.","m":"SEC-05","h":"modules/sec05.html#toolkit"},{"k":"toolkit","t":"The before-sending check","s":"Scroll to the end, unhide, clear comments, rename.","m":"SEC-05","h":"modules/sec05.html#toolkit"},{"k":"module","t":"Safe Use of AI at Work","s":"Which tools are approved, which settings to switch off, and how to keep a trail you can actually explain.","m":"SEC-06","h":"modules/sec06.html"},{"k":"lesson","t":"The account decides everything","s":"The same model can be safe or unsafe depending entirely on which account you signed in with.","m":"SEC-06","h":"modules/sec06.html#s_approved"},{"k":"lesson","t":"Signs you are in the wrong place","s":"","m":"SEC-06","h":"modules/sec06.html#why"},{"k":"lesson","t":"Two switches worth finding","s":"","m":"SEC-06","h":"modules/sec06.html#s_settings"},{"k":"lesson","t":"Settings are not a substitute","s":"","m":"SEC-06","h":"modules/sec06.html#why"},{"k":"lesson","t":"It is already in your tools","s":"Most people using AI at work today did not decide to.","m":"SEC-06","h":"modules/sec06.html#s_hidden"},{"k":"lesson","t":"The uninvited meeting bot","s":"","m":"SEC-06","h":"modules/sec06.html#why"},{"k":"lesson","t":"Answering the audit question","s":"","m":"SEC-06","h":"modules/sec06.html#s_trail"},{"k":"lesson","t":"The one-line note","s":"","m":"SEC-06","h":"modules/sec06.html#why"},{"k":"lesson","t":"Do this now: check your setup","s":"","m":"SEC-06","h":"modules/sec06.html#s_do"},{"k":"lesson","t":"Saying that AI helped","s":"","m":"SEC-06","h":"modules/sec06.html#why"},{"k":"lesson","t":"The three rules that never change","s":"","m":"SEC-06","h":"modules/sec06.html#why"},{"k":"lesson","t":"Five mistakes people really make","s":"","m":"SEC-06","h":"modules/sec06.html#why"},{"k":"lesson","t":"The safe use rule","s":"","m":"SEC-06","h":"modules/sec06.html#why"},{"k":"term","t":"Approved tool","s":"An AI service the company holds an agreement with, used through your work account.","m":"SEC-06","h":"modules/sec06.html#glossary"},{"k":"term","t":"Consumer tier","s":"A free or personal subscription. Terms nobody here negotiated, and often training on your input.","m":"SEC-06","h":"modules/sec06.html#glossary"},{"k":"term","t":"Training on your data","s":"Using what you type to improve the service.","m":"SEC-06","h":"modules/sec06.html#glossary"},{"k":"term","t":"Shadow AI","s":"AI tools in use at work that nobody assessed or approved.","m":"SEC-06","h":"modules/sec06.html#glossary"},{"k":"term","t":"Audit trail","s":"A record of what was used, on what, by whom.","m":"SEC-06","h":"modules/sec06.html#glossary"},{"k":"term","t":"Accountability","s":"A named person owns the output, regardless of what helped produce it.","m":"SEC-06","h":"modules/sec06.html#glossary"},{"k":"rule","t":"The account decides","s":"The same model is safe on a work account and unassessed on a personal one.","m":"SEC-06","h":"modules/sec06.html#recap"},{"k":"rule","t":"Two settings worth finding","s":"Training on your data, and chat history. Turn both off where you can.","m":"SEC-06","h":"modules/sec06.html#recap"},{"k":"rule","t":"Settings are not permission","s":"They reduce reuse. The paste rules do not change.","m":"SEC-06","h":"modules/sec06.html#recap"},{"k":"rule","t":"AI is already in your tools","s":"Reply suggestions, rewrite buttons, meeting bots.","m":"SEC-06","h":"modules/sec06.html#recap"},{"k":"rule","t":"Keep a one-line note","s":"What for, which tool, what data, who checked it, when.","m":"SEC-06","h":"modules/sec06.html#recap"},{"k":"rule","t":"A person is always accountable","s":"You sent it, so it is yours, whatever helped you write it.","m":"SEC-06","h":"modules/sec06.html#recap"},{"k":"toolkit","t":"The one-line AI note","s":"Purpose, tool, data provided, who checked, date.","m":"SEC-06","h":"modules/sec06.html#toolkit"},{"k":"toolkit","t":"The four conditions","s":"Approved tool, work account, facts only, human check.","m":"SEC-06","h":"modules/sec06.html#toolkit"},{"k":"toolkit","t":"The settings sweep","s":"Training off, history off, extensions you can name.","m":"SEC-06","h":"modules/sec06.html#toolkit"},{"k":"module","t":"What Never to Paste Into AI","s":"The five red lines, the two-second test, and exactly what to type instead when you are in a hurry.","m":"SEC-07","h":"modules/sec07.html"},{"k":"lesson","t":"Five things that never go in","s":"","m":"SEC-07","h":"modules/sec07.html#s_lines"},{"k":"lesson","t":"Why one paste is hard to undo","s":"People expect a paste to behave like a draft email they can unsend.","m":"SEC-07","h":"modules/sec07.html#why"},{"k":"lesson","t":"What actually goes wrong","s":"","m":"SEC-07","h":"modules/sec07.html#s_why"},{"k":"lesson","t":"The test that takes two seconds","s":"","m":"SEC-07","h":"modules/sec07.html#why"},{"k":"lesson","t":"Turn a file into safe facts","s":"","m":"SEC-07","h":"modules/sec07.html#s_strip"},{"k":"lesson","t":"Do this now: strip a real request","s":"","m":"SEC-07","h":"modules/sec07.html#why"},{"k":"lesson","t":"Say it in your own words instead","s":"Describing a situation takes about fifteen seconds and removes the risk entirely.","m":"SEC-07","h":"modules/sec07.html#why"},{"k":"lesson","t":"Approved account or personal?","s":"","m":"SEC-07","h":"modules/sec07.html#s_tool"},{"k":"lesson","t":"Signs you are in the wrong place","s":"","m":"SEC-07","h":"modules/sec07.html#why"},{"k":"lesson","t":"If you have already pasted","s":"The first hour is worth more than the next month.","m":"SEC-07","h":"modules/sec07.html#s_oops"},{"k":"lesson","t":"Reporting early is not the problem","s":"","m":"SEC-07","h":"modules/sec07.html#why"},{"k":"lesson","t":"Four habits that keep you clear","s":"","m":"SEC-07","h":"modules/sec07.html#why"},{"k":"lesson","t":"What is fine to paste","s":"This module is not asking you to stop using AI.","m":"SEC-07","h":"modules/sec07.html#why"},{"k":"lesson","t":"The one-line test","s":"","m":"SEC-07","h":"modules/sec07.html#why"},{"k":"term","t":"Personal data","s":"Any information that points to one identifiable person — a name, a phone number, an ID, sometimes an address…","m":"SEC-07","h":"modules/sec07.html#glossary"},{"k":"term","t":"PII","s":"Personally Identifiable Information. Another term for personal data, used mostly in US and UAE documents.","m":"SEC-07","h":"modules/sec07.html#glossary"},{"k":"term","t":"DPDP Act","s":"India's Digital Personal Data Protection Act.","m":"SEC-07","h":"modules/sec07.html#glossary"},{"k":"term","t":"Data breach","s":"Personal data going somewhere it should not.","m":"SEC-07","h":"modules/sec07.html#glossary"},{"k":"term","t":"Approved tool","s":"An AI service the company holds an agreement with, signed into using your work account.","m":"SEC-07","h":"modules/sec07.html#glossary"},{"k":"term","t":"Prompt","s":"Everything you type into an AI tool. It leaves your device and is usually stored.","m":"SEC-07","h":"modules/sec07.html#glossary"},{"k":"rule","t":"Five things never go in","s":"Personal data, contract terms, financials, logins, anything marked confidential.","m":"SEC-07","h":"modules/sec07.html#recap"},{"k":"rule","t":"Facts, not files","s":"Describe the situation. Do not paste the document the situation came from.","m":"SEC-07","h":"modules/sec07.html#recap"},{"k":"rule","t":"Names come out first","s":"Names, numbers and addresses before anything else.","m":"SEC-07","h":"modules/sec07.html#recap"},{"k":"rule","t":"The account decides accountability","s":"Work account, under a company agreement, every single time.","m":"SEC-07","h":"modules/sec07.html#recap"},{"k":"rule","t":"You cannot recall a paste","s":"No delete button reaches every copy. Prevention is the only control you have.","m":"SEC-07","h":"modules/sec07.html#recap"},{"k":"rule","t":"Report it the same day","s":"An hour later there are options. A month later there is only an apology.","m":"SEC-07","h":"modules/sec07.html#recap"},{"k":"toolkit","t":"The two-second test","s":"Could this text identify a person or a customer? If yes, strip it before it goes in.","m":"SEC-07","h":"modules/sec07.html#toolkit"},{"k":"toolkit","t":"The safe payment-reminder prompt","s":"Situation, days overdue, tone. No names, no invoice number, no amount.","m":"SEC-07","h":"modules/sec07.html#toolkit"},{"k":"toolkit","t":"The first-hour checklist","s":"What, where, when — written down and reported the same day.","m":"SEC-07","h":"modules/sec07.html#toolkit"}],"paths":[{"id":"p_new","name":"New Joiner — Week 1","sub":"Six modules, about 100 minutes. Do these in your first week.","codes":["AI-01","SEC-01","SEC-02","SEC-07","PS-01","PS-02"]},{"id":"p_ai","name":"AI Basics","sub":"Six modules, about 110 minutes. The full grounding.","codes":["AI-01","AI-02","AI-03","AI-04","AI-05","PE-01"]},{"id":"p_mgr","name":"Manager track","sub":"Six modules, about 100 minutes. For anyone who runs work.","codes":["PS-01","PS-04","PS-06","PS-07","PS-08","PS-09"]}],"assessment":{"passMark":0.7,"questionCount":15,"questions":[{"module":"AI-01","q":"What should you assume?","stem":"You asked an AI assistant for a courier's customer care number. It replied with a ten-digit number, straight away.","options":[{"text":"It looked it up on the website just now","ok":false,"why":"It did not open any website. Unless the tool visibly shows you a link it visited, it produced that number the same way it produces a sentence — by predicting what a courier helpline number usually looks like. Digits are exactly the kind of detail this goes wrong on."},{"text":"It is probably right, because it sounded certain","ok":false,"why":"Certainty is not evidence. The tool writes every answer in the same confident tone, whether it is repeating something it saw a million times or filling a gap. There is no built-in \"I am unsure\" signal for you to look for."},{"text":"It may be invented — check it on the official site before using it","ok":true,"why":"Correct. Treat any number, name or date in an AI answer as unverified until you have seen it at the source. Ten seconds on the official website stops a wrong number going into a client email under your name."},{"text":"AI tools are not able to produce phone numbers","ok":false,"why":"They will produce one happily, and that is the problem. It will have the right number of digits, the right format and the right area code, and still be wrong. Nothing about it will look suspicious."}]},{"module":"AI-02","q":"Why are the answers different?","stem":"You and a colleague type the same question into the same tool a minute apart, and get different wording back.","options":[{"text":"One of you made a typing mistake","ok":false,"why":"Not needed. Even a character-perfect repeat gives different wording, because the answer is built fresh rather than looked up. Identical input does not mean identical output here."},{"text":"It builds a new answer every time","ok":true,"why":"Exactly. There is no stored answer to hand back. It constructs text word by word, and tiny differences compound. This is why you can never cite it and never assume a colleague saw what you saw."},{"text":"The tool learned something in that minute","ok":false,"why":"It did not. The model does not update between your question and your colleague's. What changed is the generation, not the model's knowledge."},{"text":"One of you is on a paid account","ok":false,"why":"Account tier changes speed and limits, not this. Two people on identical paid accounts still get different wording a minute apart."}]},{"module":"AI-03","q":"Which of these is a good fit?","stem":null,"options":[{"text":"\"Summarise our supplier contract\"","ok":false,"why":"It has never seen the contract. It will produce a summary of a typical supplier contract, which reads convincingly and describes an agreement you do not have."},{"text":"\"Turn these six figures into a short summary\"","ok":true,"why":"You supplied every number. The only work left is language, and you can check each sentence against your own figures in under a minute."},{"text":"\"What did we quote this customer last year?\"","ok":false,"why":"That lives in your system, not in the model. Asking here produces a number with no source, which is worse than no number at all."},{"text":"\"Should we drop this product line?\"","ok":false,"why":"A judgement with money attached, and it holds none of the history and none of the consequences. Ask it for the questions to consider, never for the decision."}]},{"module":"AI-04","q":"Which question is it safe to ask?","stem":null,"options":[{"text":"\"What is today's exchange rate?\"","ok":false,"why":"It has no live data. It will produce a rate that looks entirely normal and is simply whatever was common in its training text. Use your bank's page."},{"text":"\"Explain what ex-works means for a buyer\"","ok":true,"why":"A stable definition that has not changed in decades, and one you can sanity-check in seconds. This is solid ground for these tools."},{"text":"\"What did the circular last month change?\"","ok":false,"why":"Last month is after its cut-off. It will not say so — it will describe a change that sounds like the sort of change such circulars make."},{"text":"\"How much stock do we hold of this part?\"","ok":false,"why":"It has no connection to your systems and never will unless someone builds one. Any figure it gives is invented in full."}]},{"module":"AI-05","q":"Why does it invent a clause?","stem":null,"options":[{"text":"It is programmed to sound helpful","ok":false,"why":"There is no instruction to be helpful at the expense of truth. It simply has no mechanism for truth at all — it is choosing likely words, and a clause number is a likely word here."},{"text":"Your question implied one exists, so it produced one","ok":true,"why":"That is the mechanism. \"What does clause 7.3 say?\" makes a clause-shaped answer the most likely continuation. It has nothing to compare that against."},{"text":"It found a similar contract online","ok":false,"why":"It did not go online. Nothing was retrieved. The clause was constructed word by word, the same way as the sentence around it."},{"text":"The contract was in its training data","ok":false,"why":"Your contract was never in its training data, and even if a similar one had been, it does not store and retrieve documents. It stores patterns."}]},{"module":"DW-01","q":"What should never go in the prompt?","stem":null,"options":[{"text":"The delivery dates","ok":false,"why":"Dates are exactly what it needs and they identify nobody. Without them you get a vague apology with no commitment in it."},{"text":"The customer's original email, pasted whole","ok":true,"why":"It carries their name, company, address, phone number and signature block. All of that leaves the company, and none of it improves the reply you get back."},{"text":"Your position on the discount","ok":false,"why":"Essential. Without it the tool guesses, and it usually guesses generously, which is a difficult email to unsend."},{"text":"The tone you want","ok":false,"why":"One of the most useful lines in the prompt. Without it you get the same neutral register regardless of the situation."}]},{"module":"DW-02","q":"Which research task fits AI?","stem":null,"options":[{"text":"\"What is the current standard for this?\"","ok":false,"why":"A specific, checkable fact it has no access to. You will get a standard number that looks entirely plausible and may belong to a different application or a superseded version."},{"text":"\"What should I ask a buyer in this industry?\"","ok":true,"why":"Questions are stable, general and low-risk. Even an imperfect list makes you better prepared, and the person in the meeting supplies the real answers."},{"text":"\"What does this supplier charge?\"","ok":false,"why":"It has no visibility of any supplier's pricing. Any figure is invented, and pricing is exactly the sort of number people repeat without checking."},{"text":"\"Summarise last month's regulatory update\"","ok":false,"why":"Last month is after its cut-off. It will produce a fluent summary of an update it has never seen."}]},{"module":"DW-03","q":"Where does the recommendation go?","stem":null,"options":[{"text":"At the end, after the evidence","ok":false,"why":"That is the order the work happened, not the order it gets read. Your reader reaches page one and rings you for the answer."},{"text":"In the first paragraph, with the reason and the ask","ok":true,"why":"If they stop after eighty words they still know what you found, why it matters and what you want them to do. Everything after that is supporting evidence."},{"text":"In a separate covering email","ok":false,"why":"Then the report and its conclusion get separated the first time either is forwarded, and the report on its own reads as inconclusive."},{"text":"In the middle, after the context","ok":false,"why":"The middle is where attention is lowest. It is the worst place for the one paragraph that has to survive a skim."}]},{"module":"DW-04","q":"Why is a long total unreliable?","stem":null,"options":[{"text":"The tool rounds aggressively","ok":false,"why":"Rounding is not what happens. The number is produced as text, in the same way a sentence is, and over forty rows that process drifts."},{"text":"It produces a likely number, not a computed one","ok":true,"why":"Exactly. There is no addition happening. The result has the right shape and magnitude, which is precisely why nobody re-adds it."},{"text":"Long columns exceed its input limit","ok":false,"why":"Forty rows is well within any modern limit. The problem is not that it cannot see the numbers, it is that it does not add them."},{"text":"It sorts before adding","ok":false,"why":"It is not performing operations in any order. Nothing resembling a calculation takes place at all."}]},{"module":"DW-05","q":"What must you do before filling down?","stem":null,"options":[{"text":"Check the formula looks correct","ok":false,"why":"A formula that looks correct can match on the wrong column and still return plausible dates for every row. Looking is not testing."},{"text":"Test it on one row where you know the answer","ok":true,"why":"Ten seconds, and it is the only step that distinguishes a working formula from one producing six hundred confident errors."},{"text":"Ask the tool whether the formula is right","ok":false,"why":"It will say yes, in the same confident voice it used to give you the formula. It cannot see your sheet or your data."},{"text":"Save a backup of the file","ok":false,"why":"Sensible generally, but it does not tell you whether the formula works. You would simply have a backup of a file with wrong results in it."}]},{"module":"DW-06","q":"What comes before opening PowerPoint?","stem":null,"options":[{"text":"Choosing a template","ok":false,"why":"Templates are the last decision, not the first. A beautiful deck with no argument fails in exactly the same way as an ugly one."},{"text":"The point, three reasons, evidence and the ask","ok":true,"why":"Ten lines you can test at your desk. If they do not convince you, no amount of slide building will convince the room."},{"text":"Gathering all the charts","ok":false,"why":"You will gather charts you never use and miss the one you need. The argument tells you which evidence matters."},{"text":"Booking the room","ok":false,"why":"Necessary, and it has nothing to do with whether the presentation will work."}]},{"module":"DW-07","q":"Why do experts write bad procedures?","stem":null,"options":[{"text":"They write too much detail","ok":false,"why":"Usually the opposite. Experts write too little, because four minutes of automatic work collapses into a single six-word line."},{"text":"The steps they stopped noticing get left out","ok":true,"why":"After four years, which system, which tab and whose approval are invisible to you. They are the first four questions a new joiner has."},{"text":"They use too much jargon","ok":false,"why":"Jargon is a real problem and an easy one to fix on review. Missing steps are harder, because you cannot see the hole."},{"text":"They write in the wrong order","ok":false,"why":"Order is usually the one thing experts get right. It is completeness that suffers."}]},{"module":"DW-08","q":"What makes an action real?","stem":null,"options":[{"text":"It is written in the minutes","ok":false,"why":"Being written down is necessary and nowhere near sufficient. \"The team will review this\" is written down and will not happen."},{"text":"It names one person and one date","ok":true,"why":"An action with two owners has none, and one with no date is read as \"whenever\". Both gaps are invisible in the room and obvious nine days later."},{"text":"Everybody agreed to it","ok":false,"why":"Agreement in the room is exactly what everyone remembers afterwards. Ownership is the part that gets forgotten."},{"text":"It has a clear description","ok":false,"why":"A clearly described action with no owner still does not happen. Description is the easy half."}]},{"module":"DW-09","q":"Why ask for impractical ideas?","stem":null,"options":[{"text":"To make the list look longer","ok":false,"why":"Length is not the aim. If you wanted twenty sensible ideas you could ask for twenty sensible ideas and get twenty familiar ones."},{"text":"Impractical ideas point at unusual workable ones","ok":true,"why":"\"Stop packaging entirely\" is impossible everywhere except on two short local routes, where it works. Nobody says that out loud in a meeting, so the workable version never gets found."},{"text":"It shows the tool's limitations","ok":false,"why":"That is not what is happening. It produces the impractical ones perfectly well on request — the point is what they suggest to the humans reading them."},{"text":"They are easier to strike, which feels productive","ok":false,"why":"Striking is fast either way. The value is that some of them survive contact with a specific route, product or site."}]},{"module":"DW-10","q":"What should you sort a list by?","stem":null,"options":[{"text":"Urgency","ok":false,"why":"Urgency reflects who asked most recently and most loudly. The task that stops a line on Friday is rarely the one anybody is shouting about on Monday."},{"text":"What breaks if it slips","ok":true,"why":"A consequence is a fact you can check, and it does not change with mood or with who is in your inbox. It is also the only test that finds the quiet critical item."},{"text":"How long each will take","ok":false,"why":"Useful for scheduling once you have decided what matters. Sorting by duration means doing the quick things regardless of whether they count."},{"text":"The order they arrived","ok":false,"why":"That is what an unsorted list already does, and it is why the important item sits at number 31 for a fortnight."}]},{"module":"DW-11","q":"Which job can be automated?","stem":null,"options":[{"text":"Deciding whether a complaint deserves a credit","ok":false,"why":"That is a judgement weighing history, relationship and context. A rule can flag candidates for a person to look at, but it cannot make the call."},{"text":"Merging two files and emailing the result each morning","ok":true,"why":"Same trigger, same steps, same output, no decisions in the middle. Twenty-five minutes a day is a hundred hours a year for a process with no thinking in it."},{"text":"Choosing which supplier to use this quarter","ok":false,"why":"A commercial judgement with money and relationships attached. Automation could assemble the comparison, but the choice stays with a person."},{"text":"Wording a reply to an unhappy customer","ok":false,"why":"Every one is different and the tone depends on context a rule cannot see. Draft it with AI by all means, but a person sends it."}]},{"module":"PE-01","q":"Which prompt will work better?","stem":"Both are asking for the same thing: an email about a delivery that slipped by three days.","options":[{"text":"\"Write a professional email about the delay.\"","ok":false,"why":"\"Professional\" gives it nothing to act on. You will get a polite, empty letter with no order number and no date, because you supplied neither. The word is doing no work at all."},{"text":"\"Write a 100-word email. Order 4471 was due 12 March, now arriving 15 March, delayed by a strike. Apologetic but calm.\"","ok":true,"why":"Task, facts, tone and length are all there. Every sentence it writes can be checked against something you typed, so there is nothing left for it to invent."},{"text":"\"Write the best possible email about the delay.\"","ok":false,"why":"\"Best possible\" is not an instruction — there is no scale for it to measure against. It falls back on a generic template, the same one everybody else gets."},{"text":"\"Write an email about the delay, ASAP.\"","ok":false,"why":"The tool has no clock and no queue, so ASAP changes nothing about the answer. You have spent a word on urgency that could have been the order number."}]},{"module":"PE-02","q":"Which of these is context?","stem":null,"options":[{"text":"\"Under 100 words\"","ok":false,"why":"That is an instruction — it tells the tool what to do with the facts. Useful, but it describes the output rather than the situation."},{"text":"\"The client escalated to my director this morning\"","ok":true,"why":"A fact about the situation that changes how the whole message should read. Nobody could infer it, and it carries no identifying detail."},{"text":"\"End with a question\"","ok":false,"why":"An instruction about the shape of the output. Good to include, but it tells the tool nothing about what is actually going on."},{"text":"\"Apologetic but firm\"","ok":false,"why":"A tone instruction. It shapes the wording, but the tool still has no idea what happened or who it is writing to."}]},{"module":"PE-03","q":"What does a role actually change?","stem":null,"options":[{"text":"What the tool knows about the subject","ok":false,"why":"Nothing changes about what it knows. The same patterns are there before and after the role line — only which ones become likely has shifted."},{"text":"The vocabulary, the depth and what it assumes","ok":true,"why":"That is exactly it. A role makes certain words and a certain level of detail more likely, and stops it explaining things that reader would already know."},{"text":"How accurate the answer is","ok":false,"why":"Accuracy is unaffected. \"Act as an expert\" produces more confident phrasing around exactly the same reliability, which is a worse position, not a better one."},{"text":"Whether it can access your systems","ok":false,"why":"No role grants access to anything. \"Pretend you can see our data\" produces pretending, presented in the same tone as fact."}]},{"module":"PE-04","q":"Why does an example beat a description?","stem":null,"options":[{"text":"Examples are shorter","ok":false,"why":"They usually are, but that is a side benefit. A long example still beats a short description, because there is nothing left to interpret."},{"text":"A description must be interpreted; an example cannot be","ok":true,"why":"Exactly. Your three sentences about layout become its reading of your sentences. An example is the picture itself, so the translation step disappears."},{"text":"The tool copies examples word for word","ok":false,"why":"It does not copy — it follows the pattern. That is what you want, because your new content is different while the shape stays fixed."},{"text":"Examples stop it inventing facts","ok":false,"why":"Different problem. Examples fix format and tone. Invented facts are controlled by supplying the facts and saying \"add nothing\"."}]},{"module":"PE-05","q":"Why does one big ask fail?","stem":null,"options":[{"text":"The tool runs out of memory","ok":false,"why":"Length limits exist but are rarely the issue here. The problem is not that it cannot hold the job — it is that you cannot inspect the middle of it."},{"text":"The middle stages are never shown to you","ok":true,"why":"You get one polished result. The gap analysis inside it was performed invisibly, so you review the wording of the conclusion instead of the reasoning that produced it."},{"text":"Long prompts confuse it","ok":false,"why":"It handles long prompts perfectly well. The risk is not confusion, it is that an early error becomes undetectable by the final paragraph."},{"text":"It takes longer to answer","ok":false,"why":"Speed is not the concern. A fast wrong answer that reaches a board is far more expensive than a slower checked one."}]},{"module":"PE-06","q":"Which prompt is worth saving?","stem":null,"options":[{"text":"One that worked on the first attempt","ok":false,"why":"If it worked immediately, you will get it right immediately next time too. The filing costs more than the rewriting would."},{"text":"One that took four attempts and you will need again","ok":true,"why":"Those four attempts were real thinking. Saving it means you never repeat that work, and a colleague gets it without doing it at all."},{"text":"A one-off question about today's document","ok":false,"why":"It only makes sense alongside a document you will never open again. Storing it clutters the file without helping anyone."},{"text":"Any prompt at all — save everything","ok":false,"why":"A library of two hundred prompts is one nobody reads. Ten to twenty good ones is the range where people actually look before writing."}]},{"module":"PE-07","q":"What does question two ask?","stem":"The four questions are traceable, complete, usable, safe.","options":[{"text":"Is it long enough?","ok":false,"why":"Length is a formatting matter and easy to fix in one line. Completeness is about whether your actual question was addressed at all."},{"text":"Did it answer what I actually asked?","ok":true,"why":"This is where most answers fail. You asked whether to accept a payment term; you received a balanced overview of payment terms. Fluent, relevant, and not an answer."},{"text":"Is the grammar correct?","ok":false,"why":"It essentially always is. Grammar is the one thing you never need to check, and checking it distracts from the things you do."},{"text":"Does it sound professional?","ok":false,"why":"It always sounds professional. That constant tone is precisely why it cannot be used as a signal of anything."}]},{"module":"PS-01","q":"Where should the ask go?","stem":null,"options":[{"text":"At the end, after the reasoning","ok":false,"why":"Almost nobody reaches the end of a work email. Your question sits below the point where the reader stopped, meaning to come back later."},{"text":"In the first sentence, with the deadline","ok":true,"why":"The reader can decide in four seconds whether this needs them, and can answer without reading anything else. Background belongs below, for the few who want it."},{"text":"In the middle, after the context","ok":false,"why":"The middle is where attention is lowest. It is the worst place in the message for the one sentence that has to be read."},{"text":"In a separate follow-up message","ok":false,"why":"Now there are two messages and it is unclear which one to reply to. One message with one ask is the goal."}]},{"module":"PS-02","q":"What should the first line contain?","stem":null,"options":[{"text":"A polite enquiry about the reader","ok":false,"why":"Everybody skips it, and it delays the information by a line. Warmth belongs in the close, where it is actually read."},{"text":"The point — what happened or what you need","ok":true,"why":"The reader knows immediately whether the message concerns them. It also makes the email findable and forwardable later."},{"text":"A reference to your previous email","ok":false,"why":"\"As per my previous email\" reads as an accusation however you meant it. If you must refer back, say \"following up on\"."},{"text":"The full background to the situation","ok":false,"why":"Background belongs below the ask, for the minority who want it. Leading with it loses the majority."}]},{"module":"PS-03","q":"What is the fastest improvement?","stem":null,"options":[{"text":"Using more formal vocabulary","ok":false,"why":"Formality usually makes sentences longer and harder, which is the opposite of what helps. Plain words are clearer for everyone."},{"text":"One idea per sentence","ok":true,"why":"It costs nothing to apply, works in any language, and removes most ambiguity immediately. Nobody has ever complained that a work email was too easy to read."},{"text":"Perfect punctuation","ok":false,"why":"Worth having, and it barely affects whether you are understood. A clear short sentence with a missing comma communicates fine."},{"text":"Longer, more detailed explanations","ok":false,"why":"More words usually means more chances to be misunderstood, and a reader who stops earlier."}]},{"module":"PS-04","q":"What does an interruption actually cost?","stem":null,"options":[{"text":"The two minutes it takes to answer","ok":false,"why":"That is the visible part and much the smaller one. The expensive part is getting back to where you were in the work."},{"text":"The two minutes plus about fifteen to refocus","ok":true,"why":"This is why eleven small interruptions can consume a morning without anyone noticing where it went. The arithmetic is invisible until you do it."},{"text":"Nothing, if you were not concentrating","ok":false,"why":"If you were not concentrating, the block was already lost. The cost applies precisely when the work mattered."},{"text":"It depends on who is interrupting","ok":false,"why":"Seniority changes how you respond, not what it costs your attention. A director's question breaks focus the same way."}]},{"module":"PS-05","q":"Why do most systems get abandoned?","stem":null,"options":[{"text":"People lack discipline","ok":false,"why":"The same people run complex operations reliably every day. If a system only works in calm weeks, the system is badly designed for the job."},{"text":"They demand more upkeep than a bad week allows","ok":true,"why":"Week three always brings a crisis. A system needing ninety minutes weekly gets skipped, goes stale, and is then abandoned because it is out of date."},{"text":"The apps are not good enough","ok":false,"why":"Apps are not the constraint. People run perfectly good systems on paper, and abandon excellent apps for the same reason."},{"text":"Work is too unpredictable to plan","ok":false,"why":"Unpredictability is exactly why capture matters. It is an argument for a simpler system, not for none."}]},{"module":"PS-06","q":"What is the most useful first question?","stem":null,"options":[{"text":"What is broken?","ok":false,"why":"You usually already know what is broken — that is the symptom that interrupted you. Knowing it rarely points at the cause."},{"text":"When did this start happening?","ok":true,"why":"A start date lets you ask what changed around it, and changes are where causes live. It is the single highest-value question in the whole method."},{"text":"Who was operating it?","ok":false,"why":"It invites human error as an answer, which is almost always the end of a chain that should have continued for two more steps."},{"text":"How much will it cost to fix?","ok":false,"why":"An important question later. Asked first, it pushes you towards fixing the symptom because that is the thing with a price on it."}]},{"module":"PS-07","q":"Which question do people skip?","stem":null,"options":[{"text":"Where did this come from?","ok":false,"why":"People do ask this, at least sometimes. It is also the easiest of the three, because it is about somebody else's work."},{"text":"What would change my mind?","ok":true,"why":"It is the only one that works on your own reasoning, which is why it gets skipped. If no evidence would change your view, you are defending a position rather than holding a conclusion."},{"text":"When was this true?","ok":false,"why":"Underused and still asked more often than the third. It is a comfortable question because it blames time rather than anyone's judgement."},{"text":"Who said it?","ok":false,"why":"Frequently asked and the least useful of the four. Who said something tells you little about whether it is true."}]},{"module":"PS-08","q":"What comes first on a slide?","stem":null,"options":[{"text":"A description of what the chart shows","ok":false,"why":"The room can already see what it shows, and faster than you can say it. Describing it wastes the moment they were listening."},{"text":"The point the slide is making","ok":true,"why":"\"Volumes held; the problem is rejects\" tells them what to look for. They then read the chart for your point rather than constructing their own."},{"text":"The methodology behind the figures","ok":false,"why":"Important if challenged, and not first. Method belongs in an appendix or in your answer to a question."},{"text":"An apology for the formatting","ok":false,"why":"It draws attention to something most people had not noticed, and lowers their expectation of everything that follows."}]},{"module":"PS-09","q":"What is missing from \"please complete\"?","stem":null,"options":[{"text":"Politeness","ok":false,"why":"It is perfectly polite. The problem is that it contains none of the information the other person needs in order to start."},{"text":"What done looks like, the deadline, and who to ask","ok":true,"why":"Three of the four lines are absent. Each one produces a round of messages, which is exactly where the three days went."},{"text":"The reason the work is needed","ok":false,"why":"Helpful context and rarely the blocker. People usually stall on scope and standard, not on motivation."},{"text":"An offer to help","ok":false,"why":"\"If stuck, ask Priya\" covers this better, because it names somebody specific rather than offering vaguely."}]},{"module":"SEC-01","q":"How do accounts usually get taken?","stem":null,"options":[{"text":"Someone guesses the password","ok":false,"why":"Almost never. Guessing is slow, usually blocked after a few attempts, and unnecessary when millions of real passwords are already available in leaked lists."},{"text":"A password leaked elsewhere is tried here","ok":true,"why":"This is the standard attack. Your email and password from a breached site are tried automatically against hundreds of services. If you reused it, one of them works."},{"text":"The password was too short","ok":false,"why":"Length matters against guessing, which is rarely how it happens. A twenty-character password that leaked is just as usable to an attacker as a short one."},{"text":"Someone watched you type it","ok":false,"why":"It happens, and it is a tiny fraction of cases. The overwhelming majority need nobody anywhere near your desk."}]},{"module":"SEC-02","q":"What proves an email is genuine?","stem":null,"options":[{"text":"The sender's name and address look right","ok":false,"why":"Display names are free text and addresses can be lookalikes or genuinely compromised. Looking right is the entire design goal of the message."},{"text":"Nothing in the message. Only a separate channel","ok":true,"why":"Every element of an email can be copied or controlled by the sender. A phone call to a number you already had is outside their control, which is why it works."},{"text":"The logo and invoice format match exactly","ok":false,"why":"Those are copied from real correspondence, often from a genuine earlier email. A perfect match is evidence of effort, not of authenticity."},{"text":"They knew your order number","ok":false,"why":"Order numbers appear in emails, attachments and sometimes breached systems. Knowing details makes the message convincing, not legitimate."}]},{"module":"SEC-03","q":"What is a second factor?","stem":null,"options":[{"text":"A second, longer password","ok":false,"why":"Two passwords are two things you know, and both can leak in the same way. The point is to add something of a completely different kind."},{"text":"Something physical you have, like your phone","ok":true,"why":"A leaked list can contain your password. It cannot contain the phone in your pocket, which is why stolen credentials stop being enough."},{"text":"A security question about your first school","ok":false,"why":"Another thing you know, and usually findable on social media. Security questions are among the weakest protections there are."},{"text":"Logging in from the office network","ok":false,"why":"Location can be a useful signal for the security team and it is not a factor you supply. It also fails entirely for anyone working remotely."}]},{"module":"SEC-04","q":"Which of these is personal data?","stem":null,"options":[{"text":"A vehicle number plate on a gate pass","ok":true,"why":"It identifies a vehicle, which identifies its keeper. Number plates, employee numbers and delivery addresses are all personal data even with no name attached."},{"text":"The total number of visitors last month","ok":false,"why":"An aggregate figure with nobody identifiable in it. Counts and totals are exactly what you should use when you need to share something."},{"text":"Our published price list","ok":false,"why":"Commercial information, not personal data. It may be confidential for other reasons, but no individual is identifiable from it."},{"text":"The name of a supplier company","ok":false,"why":"A company is not a person. A named contact at that company, with their direct line, certainly is."}]},{"module":"SEC-05","q":"What does restricted actually mean?","stem":null,"options":[{"text":"Cannot leave the company","ok":false,"why":"That describes confidential. Restricted goes further — it also cannot circulate freely inside the company."},{"text":"Only a named few can see it, inside or out","ok":true,"why":"Salaries, live legal matters and unannounced plans are restricted from most employees. Being employed here does not qualify anyone."},{"text":"Needs a password to open","ok":false,"why":"A control that may be used, not a definition. Classification is about who should see it; passwords are one way of enforcing that."},{"text":"Must be deleted after use","ok":false,"why":"Retention is a separate question. Plenty of restricted material is kept for years by the few people entitled to it."}]},{"module":"SEC-06","q":"What makes a tool approved?","stem":null,"options":[{"text":"It is a well-known brand","ok":false,"why":"Brand tells you nothing about the terms you are using. The same well-known tool is safe on a company account and unassessed on a personal free one."},{"text":"The company has an agreement and you use your work account","ok":true,"why":"Those two together give terms somebody has read, managed access, and a person who can answer questions about it afterwards. Without them, none of that exists."},{"text":"It has a privacy policy","ok":false,"why":"Every service has one, and almost nobody at this company has read the one on a free consumer tier. A policy is not an agreement we negotiated."},{"text":"You turned the training setting off","ok":false,"why":"That helps and it does not create an agreement, a record or any ability to delete data later. Settings are one layer, not the whole thing."}]},{"module":"SEC-07","q":"Which of these is safe to paste?","stem":"You are drafting a reply to a customer whose order arrived two cartons short.","options":[{"text":"The customer's email, exactly as they sent it","ok":false,"why":"Their email carries their name, their signature block and usually a phone number and address. All of it goes outside the company for no benefit — the tool does not need to know who they are to write well."},{"text":"A description of what happened, with no names","ok":true,"why":"This is the habit to build. \"An order was short by two cartons and the customer wants a credit note.\" Everything it needs to write, nothing that could harm anyone if it leaked."},{"text":"The customer's email with the name deleted","ok":false,"why":"Better, but not enough. Signature blocks, order numbers, addresses and phone numbers survive that edit, and any one of them identifies the customer. Rewriting the situation is faster than sanitising a real email."},{"text":"The full order history, so it has proper context","ok":false,"why":"Far more data for no extra quality. Every extra row is more personal information outside our control, and none of it changes the four paragraphs you get back."}]}]},"org":{"name":null,"owner":null,"tenantId":null}};
